    /**
     * @param array<int, string> $objects
     * @param list<string> $filters
     * @return array{
     *     present: true,
     *     value: int|null,
     *     valid_value: bool,
     *     filter_is_jpx: bool,
     *     uses_embedded_soft_mask: bool,
     *     encoded_soft_mask_values: bool,
     *     preblended_with_matte: bool,
     *     external_soft_mask_present: bool,
     *     external_soft_mask_ignored: bool,
     *     external_soft_mask_object: int|null,
     *     external_soft_mask_generation: int|null,
     *     ignored_without_jpx: bool,
     *     review_only: bool
     * }|null
     */
    private function imageXObjectJpxSoftMaskInDataReview(string $imageDictionary, array $filters, array $objects): ?array
    {
        $value = $this->topLevelPdfValueAfterNameInDictionaryBody($imageDictionary, 'SMaskInData');
        if ($value === null) {
            return null;
        }

        $integer = $this->streamLengthValueAt($value, 0, $objects);
        $validValue = is_int($integer) && in_array($integer, [0, 1, 2], true);
        $filterIsJpx = in_array('JPXDecode', $filters, true);
        $usesEmbeddedSoftMask = $filterIsJpx && $validValue && $integer !== 0;
        $softMaskValue = $this->topLevelPdfValueAfterNameInDictionaryBody($imageDictionary, 'SMask');
        $externalSoftMaskReference = is_string($softMaskValue)
            ? ($this->objectReferencePairs($softMaskValue)[0] ?? null)
            : null;
        $externalSoftMaskPresent = $softMaskValue !== null
            && $this->pdfNameValueAt($softMaskValue, 0, $objects) !== 'None';

        return [
            'present' => true,
            'value' => $integer,
            'valid_value' => $validValue,
            'filter_is_jpx' => $filterIsJpx,
            'uses_embedded_soft_mask' => $usesEmbeddedSoftMask,
            'encoded_soft_mask_values' => $usesEmbeddedSoftMask && $integer === 1,
            'preblended_with_matte' => $usesEmbeddedSoftMask && $integer === 2,
            'external_soft_mask_present' => $externalSoftMaskPresent,
            'external_soft_mask_ignored' => $usesEmbeddedSoftMask && $externalSoftMaskPresent,
            'external_soft_mask_object' => is_array($externalSoftMaskReference)
                ? $externalSoftMaskReference['objectNumber']
                : null,
            'external_soft_mask_generation' => is_array($externalSoftMaskReference)
                ? $externalSoftMaskReference['generation']
                : null,
            'ignored_without_jpx' => !$filterIsJpx,
            'review_only' => $usesEmbeddedSoftMask || ($filterIsJpx && !$validValue),
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return array<string, mixed>|null
     */
    private function imageXObjectSoftMaskReview(string $imageDictionary, array $objects): ?array
    {
        $value = $this->topLevelPdfValueAfterNameInDictionaryBody($imageDictionary, 'SMask');
        if ($value === null) {
            return null;
        }

        if ($this->pdfNameValueAt($value, 0, $objects) === 'None') {
            return [
                'type' => 'soft_mask_none',
                'present' => false,
                'object_number' => null,
                'object_generation' => null,
                'payload_in_visible_text' => false,
                'review_only' => true,
            ];
        }

        $reference = $this->objectReferencePairs($value)[0] ?? null;
        if ($reference === null) {
            return null;
        }

        $objectBody = $this->objectBodyForExactReference(
            $objects,
            $reference['objectNumber'],
            $reference['generation']
        );
        if ($objectBody === null) {
            return null;
        }

        return $this->imageXObjectSoftMaskStreamReview(
            $reference['objectNumber'],
            $reference['generation'],
            $objectBody,
            $objects
        );
    }

    /**
     * @param array<int, string> $objects
     * @return array<string, mixed>|null
     */
    private function imageXObjectSoftMaskStreamReview(
        int $objectNumber,
        int $objectGeneration,
        string $objectBody,
        array $objects
    ): ?array {
        $stream = $this->streamDictionaryAndPayload($objectBody, $objects);
        if ($stream === null || !$this->isImageStreamDictionary($stream['dict'], $objects)) {
            return null;
        }

        $filters = $this->streamFilters($stream['dict'], $objects);
        $resolvedFilters = $filters === null
            ? []
            : array_values(array_filter($filters, static fn (?string $filter): bool => is_string($filter)));
        $previewOnlyFilters = $this->previewOnlyImageXObjectFilters($resolvedFilters);
        $decoded = $filters === null ? null : $this->decodeStream($stream['dict'], $stream['stream'], $objects);
        $bitsPerComponent = $this->pdfIntegerValueAfterNameResolvingObjects(
            $stream['dict'],
            'BitsPerComponent',
            $objects
        );
        $imageMask = $this->pdfBooleanValueAfterName($stream['dict'], 'ImageMask') === true;
        $effectiveBits = $imageMask ? ($bitsPerComponent ?? 1) : $bitsPerComponent;
        $colorSpace = $this->imageColorSpaceFamily($stream['dict'], $objects);
        $decode = $this->imageXObjectDecodeReview(
            $stream['dict'],
            $objects,
            $imageMask ? 1 : $this->imageXObjectColorSpaceComponentCount($colorSpace),
            true
        );
        $ccittFilterReview = $this->nestedImageXObjectCcittFilterReview(
            $filters,
            $stream['dict'],
            $objects,
            $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Width', $objects),
            $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Height', $objects),
            $imageMask,
            $decode,
            $effectiveBits ?? 1
        );
        $maxSample = (2 ** min($effectiveBits ?? 1, 30)) - 1;

        return [
            'type' => 'soft_mask_stream',
            'present' => true,
            'object_number' => $objectNumber,
            'object_generation' => $objectGeneration,
            'subtype' => $this->pdfNameValueAfterNameResolvingObjects($stream['dict'], 'Subtype', $objects) ?? 'Image',
            'width' => $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Width', $objects),
            'height' => $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Height', $objects),
            'color_space' => $colorSpace,
            'bits_per_component' => $effectiveBits,
            'image_mask' => $imageMask,
            'decode' => $decode,
            'opacity_for_zero' => $decode !== null ? $this->imageXObjectDecodedSampleValue(0, $decode, $effectiveBits ?? 1) : null,
            'opacity_for_max' => $decode !== null ? $this->imageXObjectDecodedSampleValue($maxSample, $decode, $effectiveBits ?? 1) : null,
            'filters' => $resolvedFilters,
            'preview_only_filters' => $previewOnlyFilters,
            ...$ccittFilterReview,
            'native_raster_decode' => $filters !== null && $previewOnlyFilters === [],
            'raw_length' => strlen($stream['stream']),
            'decoded_with_current_filters' => $decoded !== null,
            'decoded_length' => $decoded === null ? null : strlen($decoded),
            'decoded_sha256' => $decoded === null ? null : hash('sha256', $decoded),
            'payload_in_visible_text' => false,
            'review_only' => true,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return array<string, mixed>|null
     */
    private function imageXObjectMaskReview(
        string $imageDictionary,
        array $objects,
        ?string $parentColorSpace,
        bool $softMaskPresent
    ): ?array {
        $value = $this->topLevelPdfValueAfterNameInDictionaryBody($imageDictionary, 'Mask');
        if ($value === null) {
            return null;
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);
        if ($arrayBody !== null) {
            return $this->imageXObjectColorKeyMaskReview($arrayBody, $objects, $parentColorSpace, $softMaskPresent);
        }

        $reference = $this->objectReferencePairs($value)[0] ?? null;
        if ($reference === null) {
            return null;
        }

        $objectBody = $this->objectBodyForExactReference(
            $objects,
            $reference['objectNumber'],
            $reference['generation']
        );
        if ($objectBody === null) {
            return null;
        }

        return $this->imageXObjectMaskStreamReview($reference['objectNumber'], $reference['generation'], $objectBody, $objects);
    }

    /**
     * @return array<string, mixed>
     * @param array<int, string> $objects
     */
    private function imageXObjectColorKeyMaskReview(string $arrayBody, array $objects, ?string $parentColorSpace, bool $softMaskPresent): array
    {
        $numbers = $this->numbersFromPdfArrayResolvingObjects($arrayBody, $objects);
        $ranges = [];
        for ($index = 0; $index + 1 < count($numbers); $index += 2) {
            $ranges[] = [
                'min' => (float) $numbers[$index],
                'max' => (float) $numbers[$index + 1],
            ];
        }

        $componentCount = count($ranges);
        $expectedComponents = $this->imageXObjectColorSpaceComponentCount($parentColorSpace);

        return [
            'type' => 'color_key_mask_array',
            'ranges' => $ranges,
            'component_count' => $componentCount,
            'expected_components' => $expectedComponents,
            'valid_for_components' => $expectedComponents === null || $expectedComponents === $componentCount,
            'compares_before_decode' => true,
            'transparent_when_all_components_match' => true,
            'suppressed_by_soft_mask' => $softMaskPresent,
            'review_only' => true,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return array<string, mixed>|null
     */
    private function imageXObjectMaskStreamReview(
        int $objectNumber,
        int $objectGeneration,
        string $objectBody,
        array $objects
    ): ?array
    {
        $stream = $this->streamDictionaryAndPayload($objectBody, $objects);
        if ($stream === null || !$this->isImageStreamDictionary($stream['dict'], $objects)) {
            return null;
        }

        $filters = $this->streamFilters($stream['dict'], $objects);
        $resolvedFilters = $filters === null
            ? []
            : array_values(array_filter($filters, static fn (?string $filter): bool => is_string($filter)));
        $previewOnlyFilters = $this->previewOnlyImageXObjectFilters($resolvedFilters);
        $decoded = $filters === null ? null : $this->decodeStream($stream['dict'], $stream['stream'], $objects);
        $bitsPerComponent = $this->pdfIntegerValueAfterNameResolvingObjects(
            $stream['dict'],
            'BitsPerComponent',
            $objects
        );
        $imageMask = $this->pdfBooleanValueAfterName($stream['dict'], 'ImageMask') === true;
        $effectiveBits = $imageMask ? ($bitsPerComponent ?? 1) : $bitsPerComponent;
        $colorSpace = $this->imageColorSpaceFamily($stream['dict'], $objects);
        $decode = $this->imageXObjectDecodeReview($stream['dict'], $objects, $imageMask ? 1 : $this->imageXObjectColorSpaceComponentCount($colorSpace), $imageMask);
        $ccittFilterReview = $this->nestedImageXObjectCcittFilterReview(
            $filters,
            $stream['dict'],
            $objects,
            $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Width', $objects),
            $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Height', $objects),
            $imageMask,
            $decode,
            $effectiveBits ?? 1
        );

        return [
            'type' => $imageMask ? 'image_mask_stream' : 'explicit_mask_stream',
            'object_number' => $objectNumber,
            'object_generation' => $objectGeneration,
            'subtype' => $this->pdfNameValueAfterNameResolvingObjects($stream['dict'], 'Subtype', $objects) ?? 'Image',
            'width' => $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Width', $objects),
            'height' => $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Height', $objects),
            'color_space' => $colorSpace,
            'bits_per_component' => $effectiveBits,
            'image_mask' => $imageMask,
            'decode' => $decode,
            'opacity_for_zero' => $imageMask && $decode !== null ? $this->imageXObjectDecodedSampleValue(0, $decode, $effectiveBits ?? 1) : null,
            'opacity_for_one' => $imageMask && $decode !== null ? $this->imageXObjectDecodedSampleValue((2 ** min($effectiveBits ?? 1, 30)) - 1, $decode, $effectiveBits ?? 1) : null,
            'filters' => $resolvedFilters,
            'preview_only_filters' => $previewOnlyFilters,
            ...$ccittFilterReview,
            'native_raster_decode' => $filters !== null && $previewOnlyFilters === [],
            'raw_length' => strlen($stream['stream']),
            'decoded_with_current_filters' => $decoded !== null,
            'decoded_length' => $decoded === null ? null : strlen($decoded),
            'decoded_sha256' => $decoded === null ? null : hash('sha256', $decoded),
            'payload_in_visible_text' => false,
            'review_only' => true,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return array{ranges: list<array{min: float, max: float}>, component_count: int, expected_components: int|null, valid_for_components: bool, identity: bool, inverted_components: list<int>, source: string}|null
     */
    private function imageXObjectDecodeReview(
        string $dictionary,
        array $objects,
        ?int $expectedComponents,
        bool $defaultIfMissing = false
    ): ?array {
        $arrayBody = $this->pdfArrayValueAfterNameResolvingObjects($dictionary, 'Decode', $objects);
        $source = 'explicit';
        if ($arrayBody === null) {
            if (!$defaultIfMissing) {
                return null;
            }

            $arrayBody = '0 1';
            $source = 'default';
        }

        $numbers = $this->numbersFromPdfArrayResolvingObjects($arrayBody, $objects);
        $ranges = [];
        for ($index = 0; $index + 1 < count($numbers); $index += 2) {
            $ranges[] = [
                'min' => (float) $numbers[$index],
                'max' => (float) $numbers[$index + 1],
            ];
        }

        $inverted = [];
        $identity = $ranges !== [];
        foreach ($ranges as $index => $range) {
            if ($range['min'] > $range['max']) {
                $inverted[] = $index;
            }
            if (abs($range['min']) > 0.000001 || abs($range['max'] - 1.0) > 0.000001) {
                $identity = false;
            }
        }

        $componentCount = count($ranges);

        return [
            'ranges' => $ranges,
            'component_count' => $componentCount,
            'expected_components' => $expectedComponents,
            'valid_for_components' => $expectedComponents === null || $componentCount === $expectedComponents,
            'identity' => $identity,
            'inverted_components' => $inverted,
            'source' => $source,
        ];
    }

    /**
     * @param array{ranges: list<array{min: float, max: float}>, valid_for_components: bool} $decode
     */
    private function imageXObjectDecodedSampleValue(int|float $sample, array $decode, int $bitsPerComponent): ?float
    {
        if (($decode['valid_for_components'] ?? false) !== true || !isset($decode['ranges'][0])) {
            return null;
        }

        $maxSample = (2 ** min(max(1, $bitsPerComponent), 30)) - 1;
        $ratio = max(0.0, min(1.0, (float) $sample / $maxSample));
        $range = $decode['ranges'][0];

        return $range['min'] + (($range['max'] - $range['min']) * $ratio);
    }

    private function imageXObjectColorSpaceComponentCount(?string $colorSpace): ?int
    {
        return match ($colorSpace) {
            'DeviceGray', 'G', 'Indexed', 'I' => 1,
            'DeviceRGB', 'RGB' => 3,
            'DeviceCMYK', 'CMYK' => 4,
            default => null,
        };
    }

    /**
     * @param array<int, string> $objects
     * @return list<array<string, mixed>>
     */
    private function imageXObjectAlternateImageReviews(string $imageDictionary, array $objects): array
    {
        $value = $this->topLevelPdfValueAfterNameInDictionaryBody($imageDictionary, 'Alternates');
        if ($value === null) {
            return [];
        }

        $arrayBody = $this->pdfArrayAtStart(trim($value));
        if ($arrayBody === null) {
            return [];
        }

        $reviews = [];
        foreach ($this->pdfArrayItems($arrayBody) as $item) {
            $item = trim($item);
            $defaultForPrinting = null;
            $reference = null;

            if (str_starts_with($item, '<<')) {
                $dictionary = $this->readPdfDictionaryAt($item, 0);
                if ($dictionary === null) {
                    continue;
                }

                $reference = $this->objectReferenceAfterName($dictionary, 'Image');
                $defaultForPrinting = $this->pdfBooleanValueAfterName($dictionary, 'DefaultForPrinting');
            } else {
                $reference = $this->objectReferencePairs($item)[0] ?? null;
            }

            if ($reference === null) {
                continue;
            }

            $objectBody = $this->objectBodyForExactReference(
                $objects,
                $reference['objectNumber'],
                $reference['generation']
            );
            if ($objectBody === null) {
                continue;
            }

            $review = $this->imageXObjectAlternateStreamReview(
                $reference['objectNumber'],
                $reference['generation'],
                $defaultForPrinting,
                $objectBody,
                $objects
            );
            if ($review !== null) {
                $reviews[] = $review;
            }
        }

        return $reviews;
    }

    /**
     * @param array<int, string> $objects
     * @return array<string, mixed>|null
     */
    private function imageXObjectAlternateStreamReview(
        int $objectNumber,
        int $objectGeneration,
        ?bool $defaultForPrinting,
        string $objectBody,
        array $objects
    ): ?array
    {
        $stream = $this->streamDictionaryAndPayload($objectBody, $objects);
        if ($stream === null || !$this->isImageStreamDictionary($stream['dict'], $objects)) {
            return null;
        }

        $filters = $this->streamFilters($stream['dict'], $objects);
        $resolvedFilters = $filters === null
            ? []
            : array_values(array_filter($filters, static fn (?string $filter): bool => is_string($filter)));
        $previewOnlyFilters = $this->previewOnlyImageXObjectFilters($resolvedFilters);
        $decoded = $filters === null ? null : $this->decodeStream($stream['dict'], $stream['stream'], $objects);
        $bitsPerComponent = $this->pdfIntegerValueAfterNameResolvingObjects(
            $stream['dict'],
            'BitsPerComponent',
            $objects
        );
        $imageMask = $this->pdfBooleanValueAfterName($stream['dict'], 'ImageMask') === true;
        $effectiveBits = $imageMask ? ($bitsPerComponent ?? 1) : $bitsPerComponent;
        $colorSpace = $this->imageColorSpaceFamily($stream['dict'], $objects);
        $decode = $this->imageXObjectDecodeReview(
            $stream['dict'],
            $objects,
            $imageMask ? 1 : $this->imageXObjectColorSpaceComponentCount($colorSpace),
            $imageMask
        );
        $ccittFilterReview = $this->nestedImageXObjectCcittFilterReview(
            $filters,
            $stream['dict'],
            $objects,
            $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Width', $objects),
            $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Height', $objects),
            $imageMask,
            $decode,
            $effectiveBits ?? 1
        );

        return [
            'object_number' => $objectNumber,
            'object_generation' => $objectGeneration,
            'default_for_printing' => $defaultForPrinting,
            'subtype' => $this->pdfNameValueAfterNameResolvingObjects($stream['dict'], 'Subtype', $objects) ?? 'Image',
            'width' => $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Width', $objects),
            'height' => $this->pdfIntegerValueAfterNameResolvingObjects($stream['dict'], 'Height', $objects),
            'color_space' => $colorSpace,
            'bits_per_component' => $effectiveBits,
            'image_mask' => $imageMask,
            'filters' => $resolvedFilters,
            'preview_only_filters' => $previewOnlyFilters,
            ...$ccittFilterReview,
            'native_raster_decode' => $filters !== null && $previewOnlyFilters === [],
            'raw_length' => strlen($stream['stream']),
            'decoded_with_current_filters' => $decoded !== null,
            'decoded_length' => $decoded === null ? null : strlen($decoded),
            'decoded_sha256' => $decoded === null ? null : hash('sha256', $decoded),
            'payload_in_visible_text' => false,
            'review_only' => true,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return array{
     *     object_number: int,
     *     subtype: string|null,
     *     filters: list<string>,
     *     preview_only_filters: list<string>,
     *     raw_length: int,
     *     decoded_with_current_filters: bool,
     *     decoded_length: int|null,
     *     decoded_sha256: string|null,
     *     payload_in_visible_text: false,
     *     review_only: true
     * }|null
     */
    private function imageXObjectMetadataStreamReview(string $imageDictionary, array $objects): ?array
    {
        $reference = $this->objectReferenceAfterName($imageDictionary, 'Metadata');
        if ($reference === null) {
            return null;
        }

        $objectBody = $this->objectBodyForExactReference(
            $objects,
            $reference['objectNumber'],
            $reference['generation']
        );
        if ($objectBody === null) {
            return null;
        }

        $stream = $this->streamDictionaryAndPayload($objectBody, $objects);
        if ($stream === null) {
            return null;
        }

        $filters = $this->streamFilters($stream['dict'], $objects);
        $resolvedFilters = $filters === null
            ? []
            : array_values(array_filter($filters, static fn (?string $filter): bool => is_string($filter)));
        $decoded = $filters === null ? null : $this->decodeStream($stream['dict'], $stream['stream'], $objects);

        return [
            'object_number' => $reference['objectNumber'],
            'object_generation' => $reference['generation'],
            'subtype' => $this->pdfNameValueAfterNameResolvingObjects($stream['dict'], 'Subtype', $objects),
            'filters' => $resolvedFilters,
            'preview_only_filters' => $this->previewOnlyImageXObjectFilters($resolvedFilters),
            'raw_length' => strlen($stream['stream']),
            'decoded_with_current_filters' => $decoded !== null,
            'decoded_length' => $decoded === null ? null : strlen($decoded),
            'decoded_sha256' => $decoded === null ? null : hash('sha256', $decoded),
            'payload_in_visible_text' => false,
            'review_only' => true,
        ];
    }

    /**
     * @param list<string> $filters
     * @return list<string>
     */
    private function previewOnlyImageXObjectFilters(array $filters): array
    {
        return array_values(array_filter(
            $filters,
            static fn (string $filter): bool => in_array(
                $filter,
                ['DCTDecode', 'DCT', 'CCITTFaxDecode', 'CCF', 'JPXDecode', 'JBIG2Decode'],
                true
            )
        ));
    }

    /**
     * @param list<string|null>|null $filters
     * @param array<int, string> $objects
     * @return array{filter_details: list<array{filter: string, preview_only: bool, decode_parms: array<string, int|bool|string|null|list<string>>|null}>, ccitt_fax_decode_boundary: array<string, mixed>, ccitt_fax_coding_boundary: array<string, mixed>|null}|array{}
     */
    private function nestedImageXObjectCcittFilterReview(
        ?array $filters,
        string $dictionary,
        array $objects,
        ?int $width,
        ?int $height,
        bool $imageMask = false,
        ?array $decode = null,
        int $bitsPerComponent = 1
    ): array {
        if ($filters === null || $filters === []) {
            return [];
        }

        $decodeParms = $this->streamDecodeParms($dictionary, $objects);
        $filterDetails = $this->imageXObjectFilterDetails(
            $filters,
            $decodeParms,
            $objects,
            $this->topLevelNameValueOffset($dictionary, 'DecodeParms') !== null,
            $dictionary
        );
        $boundary = $this->ccittFaxDecodeBoundaryReview($filterDetails, $width, $height);
        if ($boundary === null) {
            return [];
        }

        $review = [
            'filter_details' => $filterDetails,
            'ccitt_fax_filter_boundary' => $this->ccittFaxFilterBoundaryReview($filterDetails),
            'ccitt_fax_decode_boundary' => $boundary,
            'ccitt_fax_coding_boundary' => $this->ccittFaxCodingBoundaryReview($filterDetails),
        ];
        $polarity = $this->ccittFaxImageMaskPolarityBoundary($boundary, $imageMask, $decode, $bitsPerComponent);
        if ($polarity !== null) {
            $review['ccitt_fax_imagemask_polarity_boundary'] = $polarity;
        }

        return $review;
    }

    /**
     * @param list<string|null> $filters
     * @param list<string|null>|null $decodeParms
     * @param array<int, string> $objects
     * @return list<array{filter: string, preview_only: bool, decode_parms: array<string, int|bool|string|null|list<string>>|null}>
     */
    private function imageXObjectFilterDetails(
        array $filters,
        ?array $decodeParms,
        array $objects,
        bool $decodeParmsPresent = false,
        ?string $dictionary = null
    ): array
    {
        $details = [];
        $decodeParmsOperandFailure = $decodeParms === null && $decodeParmsPresent
            ? $this->imageXObjectDecodeParmsOperandFailureReview($dictionary ?? '', $objects)
            : null;

        foreach ($filters as $index => $filter) {
            if (!is_string($filter)) {
                continue;
            }

            $decodeParmsIndex = $decodeParms === null
                ? null
                : $this->decodeParmsIndexForFilterIndex($filters, $decodeParms, $index);
            $decodeParmsValue = $decodeParmsIndex === null || $decodeParms === null
                ? null
                : ($decodeParms[$decodeParmsIndex] ?? null);

            $details[] = [
                'filter' => $filter,
                'preview_only' => in_array($filter, ['DCTDecode', 'DCT', 'CCITTFaxDecode', 'CCF', 'JPXDecode', 'JBIG2Decode'], true),
                'decode_parms' => ($decodeParmsValue === null && $decodeParmsOperandFailure !== null && ($filter === 'CCITTFaxDecode' || $filter === 'CCF'))
                    ? $decodeParmsOperandFailure
                    : (
                        $this->imageXObjectFilterDecodeParms($filter, $decodeParmsValue, $objects)
                        ?? $this->ccittFaxUnalignedDecodeParmsReview($filter, $filters, $decodeParms ?? [], $decodeParmsIndex)
                    ),
            ];
        }

        return $details;
    }

    /**
     * @return array<string, int|bool|string|null|list<string>>|null
     * @param array<int, string> $objects
     */
    private function imageXObjectDecodeParmsOperandFailureReview(string $dictionary, array $objects): ?array
    {
        $offset = $this->topLevelNameValueOffset($dictionary, 'DecodeParms');
        $value = $offset === null ? null : $this->pdfValueAtOffset($dictionary, $offset);
        if (!is_string($value) || strtolower(trim($value)) === 'null') {
            return null;
        }

        $operand = $this->imageXObjectDecodeParmsOperandFailureKind($value, $objects);

        return [
            'type' => 'CCITTFaxDecode',
            'k' => null,
            'columns' => null,
            'rows' => null,
            'black_is_1' => null,
            'encoded_byte_align' => null,
            'end_of_line' => null,
            'end_of_block' => null,
            'damaged_rows_before_error' => null,
            'valid_decode_parms' => false,
            'invalid_decode_parms_fields' => ['decode_parms_operand'],
            'decode_parms_review' => $operand === 'unresolved_reference'
                ? 'unresolved_ccitt_decodeparms_fail_closed'
                : 'malformed_ccitt_decodeparms_fail_closed',
            'decode_parms_operand' => $operand,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seenReferences
     */
    private function imageXObjectDecodeParmsOperandFailureKind(
        string $value,
        array $objects,
        array $seenReferences = []
    ): string {
        $trimmed = trim($value);
        if (preg_match('/^(\d+)\s+(\d+)\s+R$/', $trimmed, $match) !== 1) {
            return 'malformed_operand';
        }

        $objectNumber = (int) $match[1];
        $generation = (int) $match[2];
        $key = $objectNumber . ':' . $generation;
        if ($objectNumber <= 0 || isset($seenReferences[$key])) {
            return 'unresolved_reference';
        }

        $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return 'unresolved_reference';
        }

        $body = trim($body);
        if (strtolower($body) === 'null') {
            return 'malformed_operand';
        }

        $seenReferences[$key] = true;
        if (preg_match('/^(\d+)\s+(\d+)\s+R$/', $body) === 1) {
            return $this->imageXObjectDecodeParmsOperandFailureKind($body, $objects, $seenReferences);
        }

        return 'malformed_operand';
    }

    /**
     * @param array<int, string> $objects
     * @return array<string, int|bool|string|null|list<string>>|null
     */
    private function imageXObjectFilterDecodeParms(string $filter, ?string $value, array $objects): ?array
    {
        if ($value === null || trim($value) === '') {
            return null;
        }

        if ($filter === 'CCITTFaxDecode' || $filter === 'CCF') {
            return $this->ccittFaxDecodeParmsReview($value, $objects);
        }

        if ($filter === 'DCTDecode' || $filter === 'DCT') {
            $colorTransform = $this->decodeParmsInt($value, 'ColorTransform', $objects);

            return [
                'type' => 'DCTDecode',
                'color_transform' => $colorTransform,
                'valid_color_transform' => $colorTransform === null || in_array($colorTransform, [0, 1, 2], true),
            ];
        }

        return ['type' => $filter];
    }

    /**
     * @param list<string|null> $filters
     * @param list<string|null> $decodeParms
     * @return array<string, int|bool|string|null|list<string>>|null
     */
    private function ccittFaxUnalignedDecodeParmsReview(
        string $filter,
        array $filters,
        array $decodeParms,
        ?int $decodeParmsIndex
    ): ?array {
        if (($filter !== 'CCITTFaxDecode' && $filter !== 'CCF') || $decodeParmsIndex !== null) {
            return null;
        }

        $hasDeclaredNonNullDecodeParms = false;
        foreach ($decodeParms as $value) {
            if ($value !== null && trim($value) !== '') {
                $hasDeclaredNonNullDecodeParms = true;
                break;
            }
        }
        if (!$hasDeclaredNonNullDecodeParms) {
            return null;
        }

        $filterSlots = count($filters);
        $decodeParmsSlots = count($decodeParms);

        return [
            'type' => 'CCITTFaxDecode',
            'k' => null,
            'columns' => null,
            'rows' => null,
            'black_is_1' => null,
            'encoded_byte_align' => null,
            'end_of_line' => null,
            'end_of_block' => null,
            'damaged_rows_before_error' => null,
            'valid_decode_parms' => false,
            'invalid_decode_parms_fields' => ['decode_parms_alignment'],
            'decode_parms_review' => 'unaligned_ccitt_decodeparms_fail_closed',
            'decode_parms_alignment' => $decodeParmsSlots < $filterSlots ? 'missing_filter_slot' : 'unapplied_filter_slot',
            'filter_slot_count' => $filterSlots,
            'decode_parms_slot_count' => $decodeParmsSlots,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return array<string, int|bool|string|null|list<string>>
     */
    private function ccittFaxDecodeParmsReview(string $decodeParms, array $objects): array
    {
        $details = [
            'type' => 'CCITTFaxDecode',
            'k' => $this->decodeParmsInt($decodeParms, 'K', $objects),
            'columns' => $this->decodeParmsInt($decodeParms, 'Columns', $objects),
            'rows' => $this->decodeParmsInt($decodeParms, 'Rows', $objects),
            'black_is_1' => $this->decodeParmsBool($decodeParms, 'BlackIs1', $objects),
            'encoded_byte_align' => $this->decodeParmsBool($decodeParms, 'EncodedByteAlign', $objects),
            'end_of_line' => $this->decodeParmsBool($decodeParms, 'EndOfLine', $objects),
            'end_of_block' => $this->decodeParmsBool($decodeParms, 'EndOfBlock', $objects),
            'damaged_rows_before_error' => $this->decodeParmsInt($decodeParms, 'DamagedRowsBeforeError', $objects),
        ];

        $invalidFields = [];
        foreach (['K' => 'k'] as $pdfName => $field) {
            if ($this->decodeParmsHasName($decodeParms, $pdfName) && $details[$field] === null) {
                $invalidFields[$field] = true;
            }
        }

        foreach (['Columns' => 'columns'] as $pdfName => $field) {
            if (
                $this->decodeParmsHasName($decodeParms, $pdfName)
                && (!is_int($details[$field]) || $details[$field] < 1)
            ) {
                $invalidFields[$field] = true;
            }
        }

        foreach (['Rows' => 'rows', 'DamagedRowsBeforeError' => 'damaged_rows_before_error'] as $pdfName => $field) {
            if (
                $this->decodeParmsHasName($decodeParms, $pdfName)
                && (!is_int($details[$field]) || $details[$field] < 0)
            ) {
                $invalidFields[$field] = true;
            }
        }

        foreach ([
            'BlackIs1' => 'black_is_1',
            'EncodedByteAlign' => 'encoded_byte_align',
            'EndOfLine' => 'end_of_line',
            'EndOfBlock' => 'end_of_block',
        ] as $pdfName => $field) {
            if ($this->decodeParmsHasName($decodeParms, $pdfName) && !is_bool($details[$field])) {
                $invalidFields[$field] = true;
            }
        }

        if ($invalidFields !== []) {
            $details['valid_decode_parms'] = false;
            $details['invalid_decode_parms_fields'] = array_values(array_filter(
                [
                    'k',
                    'columns',
                    'rows',
                    'black_is_1',
                    'encoded_byte_align',
                    'end_of_line',
                    'end_of_block',
                    'damaged_rows_before_error',
                ],
                static fn (string $field): bool => isset($invalidFields[$field])
            ));
            $details['decode_parms_review'] = 'invalid_ccitt_decodeparms_fail_closed';
        }

        return $details;
    }

    /**
     * @param list<array{filter: string, preview_only: bool, decode_parms: array<string, int|bool|string|null|list<string>>|null}> $filterDetails
     * @return array<string, mixed>|null
     */
    private function ccittFaxDecodeBoundaryReview(array $filterDetails, ?int $dictionaryWidth, ?int $dictionaryHeight): ?array
    {
        $detail = null;
        foreach ($filterDetails as $candidate) {
            if (($candidate['filter'] ?? null) === 'CCITTFaxDecode' || ($candidate['filter'] ?? null) === 'CCF') {
                $detail = $candidate;
                break;
            }
        }

        if ($detail === null) {
            return null;
        }

        $decodeParms = is_array($detail['decode_parms'] ?? null) ? $detail['decode_parms'] : null;
        $invalidFields = is_array($decodeParms)
            ? array_values(array_filter(
                $decodeParms['invalid_decode_parms_fields'] ?? [],
                static fn (mixed $field): bool => is_string($field)
            ))
            : [];
        $invalidLookup = array_fill_keys($invalidFields, true);

        $effective = [
            'k' => $this->ccittEffectiveInt($decodeParms, 'k', 0, $invalidLookup),
            'columns' => $this->ccittEffectivePositiveInt($decodeParms, 'columns', 1728, $invalidLookup),
            'rows' => $this->ccittEffectiveNonNegativeInt($decodeParms, 'rows', 0, $invalidLookup),
            'black_is_1' => $this->ccittEffectiveBool($decodeParms, 'black_is_1', false, $invalidLookup),
            'encoded_byte_align' => $this->ccittEffectiveBool($decodeParms, 'encoded_byte_align', false, $invalidLookup),
            'end_of_line' => $this->ccittEffectiveBool($decodeParms, 'end_of_line', false, $invalidLookup),
            'end_of_block' => $this->ccittEffectiveBool($decodeParms, 'end_of_block', true, $invalidLookup),
            'damaged_rows_before_error' => $this->ccittEffectiveNonNegativeInt($decodeParms, 'damaged_rows_before_error', 0, $invalidLookup),
        ];
        $defaultsApplied = $this->ccittDefaultsApplied($decodeParms, $invalidLookup, [
            'k',
            'columns',
            'rows',
            'black_is_1',
            'encoded_byte_align',
            'end_of_line',
            'end_of_block',
            'damaged_rows_before_error',
        ]);

        $effectiveWidth = $dictionaryWidth ?? $effective['columns'];
        $effectiveHeight = $dictionaryHeight ?? ($effective['rows'] > 0 ? $effective['rows'] : null);
        $columnsMatchWidth = $dictionaryWidth === null ? null : $dictionaryWidth === $effective['columns'];
        $rowsMatchHeight = $dictionaryHeight === null || $effective['rows'] === 0
            ? null
            : $dictionaryHeight === $effective['rows'];

        return [
            'filter' => (string) $detail['filter'],
            'review_only' => true,
            'native_raster_decode' => false,
            'decode_parms_present' => $decodeParms !== null,
            'invalid_decode_parms' => $invalidFields !== [],
            'invalid_decode_parms_fields' => $invalidFields,
            'effective_decode_parms' => $effective,
            'defaults_applied' => $defaultsApplied,
            'dictionary_width' => $dictionaryWidth,
            'dictionary_height' => $dictionaryHeight,
            'effective_width' => $effectiveWidth,
            'effective_height' => $effectiveHeight,
            'width_source' => $dictionaryWidth === null
                ? ($decodeParms !== null && !isset($invalidLookup['columns']) && is_int($decodeParms['columns'] ?? null) ? 'decodeparms_columns' : 'decodeparms_columns_default')
                : 'image_dictionary',
            'height_source' => $dictionaryHeight === null
                ? ($effective['rows'] > 0 ? 'decodeparms_rows' : 'unbounded_rows')
                : 'image_dictionary',
            'columns_match_width' => $columnsMatchWidth,
            'rows_match_height' => $rowsMatchHeight,
            'dimension_mismatch' => $columnsMatchWidth === false || $rowsMatchHeight === false,
        ];
    }

    /**
     * @param list<array{filter: string, preview_only: bool, decode_parms: array<string, int|bool|string|null|list<string>>|null}> $filterDetails
     * @return array<string, mixed>|null
     */
    private function ccittFaxFilterBoundaryReview(array $filterDetails): ?array
    {
        $filters = [];
        $previewOnly = [];
        $nativePrefix = [];
        foreach ($filterDetails as $detailIndex => $detail) {
            $filter = $detail['filter'] ?? null;
            if (!is_string($filter)) {
                continue;
            }

            if ($filter === 'CCITTFaxDecode' || $filter === 'CCF') {
                $filtersAfterCcitt = [];
                $nativeFiltersAfterCcitt = [];
                $previewOnlyFiltersAfterCcitt = [];
                for ($afterIndex = $detailIndex + 1, $count = count($filterDetails); $afterIndex < $count; $afterIndex++) {
                    $afterFilter = $filterDetails[$afterIndex]['filter'] ?? null;
                    if (!is_string($afterFilter)) {
                        continue;
                    }

                    $filtersAfterCcitt[] = $afterFilter;
                    if (($filterDetails[$afterIndex]['preview_only'] ?? false) === true) {
                        $previewOnlyFiltersAfterCcitt[] = $afterFilter;
                    } else {
                        $nativeFiltersAfterCcitt[] = $afterFilter;
                    }
                }

                return [
                    'declared_filter' => $filter,
                    'canonical_filter' => 'CCITTFaxDecode',
                    'alias_used' => $filter === 'CCF',
                    'non_null_filter_index' => count($filters),
                    'filters_before_ccitt' => $filters,
                    'native_prefix_filters' => $nativePrefix,
                    'preview_only_filters_before_ccitt' => $previewOnly,
                    'filters_after_ccitt' => $filtersAfterCcitt,
                    'native_filters_after_ccitt' => $nativeFiltersAfterCcitt,
                    'preview_only_filters_after_ccitt' => $previewOnlyFiltersAfterCcitt,
                    'ccitt_is_terminal_filter' => $filtersAfterCcitt === [],
                    'post_ccitt_filters_present' => $filtersAfterCcitt !== [],
                    'post_ccitt_filters_block_native_decode' => $filtersAfterCcitt !== [],
                    'source_filter_preserved' => true,
                    'review_only' => true,
                    'native_raster_decode' => false,
                ];
            }

            $filters[] = $filter;
            if (($detail['preview_only'] ?? false) === true) {
                $previewOnly[] = $filter;
            } else {
                $nativePrefix[] = $filter;
            }
        }

        return null;
    }

    /**
     * @param list<array{filter: string, preview_only: bool, decode_parms: array<string, int|bool|string|null|list<string>>|null}> $filterDetails
     * @return array<string, mixed>|null
     */
    private function ccittFaxCodingBoundaryReview(array $filterDetails): ?array
    {
        $boundary = $this->ccittFaxDecodeBoundaryReview($filterDetails, null, null);
        if ($boundary === null) {
            return null;
        }

        $effective = is_array($boundary['effective_decode_parms'] ?? null)
            ? $boundary['effective_decode_parms']
            : [];
        $k = is_int($effective['k'] ?? null) ? $effective['k'] : 0;
        $endOfBlock = is_bool($effective['end_of_block'] ?? null) ? $effective['end_of_block'] : true;

        return [
            'filter' => (string) ($boundary['filter'] ?? 'CCITTFaxDecode'),
            'review_only' => true,
            'native_raster_decode' => false,
            'decode_parms_present' => ($boundary['decode_parms_present'] ?? false) === true,
            'invalid_decode_parms' => ($boundary['invalid_decode_parms'] ?? false) === true,
            'effective_k' => $k,
            'coding_mode' => $this->ccittFaxCodingMode($k),
            'uses_two_dimensional_coding' => $k !== 0,
            'two_dimensional_line_interval' => $k > 0 ? $k : null,
            'end_of_block' => $endOfBlock,
            'end_of_block_marker' => $this->ccittFaxEndOfBlockMarkerName($k, $endOfBlock),
        ];
    }

    /**
     * @param array<string, mixed>|null $ccittBoundary
     * @param array{ranges: list<array{min: float, max: float}>, valid_for_components: bool, source: string, inverted_components: list<int>}|null $decode
     * @return array<string, mixed>|null
     */
    private function ccittFaxImageMaskPolarityBoundary(
        ?array $ccittBoundary,
        bool $imageMask,
        ?array $decode,
        int $bitsPerComponent
    ): ?array {
        if ($ccittBoundary === null || !$imageMask) {
            return null;
        }

        $effective = is_array($ccittBoundary['effective_decode_parms'] ?? null)
            ? $ccittBoundary['effective_decode_parms']
            : [];
        $blackIs1 = is_bool($effective['black_is_1'] ?? null) ? $effective['black_is_1'] : false;
        $blackSampleValue = $blackIs1 ? 1 : 0;
        $whiteSampleValue = $blackIs1 ? 0 : 1;
        $decodeValid = is_array($decode) && ($decode['valid_for_components'] ?? false) === true;
        $blackOpacity = $decodeValid
            ? $this->imageXObjectDecodedSampleValue($blackSampleValue, $decode, $bitsPerComponent)
            : null;
        $whiteOpacity = $decodeValid
            ? $this->imageXObjectDecodedSampleValue($whiteSampleValue, $decode, $bitsPerComponent)
            : null;

        return [
            'filter' => (string) ($ccittBoundary['filter'] ?? 'CCITTFaxDecode'),
            'review_only' => true,
            'native_raster_decode' => false,
            'image_mask' => true,
            'black_is_1' => $blackIs1,
            'black_sample_value' => $blackSampleValue,
            'white_sample_value' => $whiteSampleValue,
            'image_mask_decode_source' => is_array($decode) ? ($decode['source'] ?? null) : null,
            'decode_inverts_stencil' => is_array($decode) && ($decode['inverted_components'] ?? []) !== [],
            'black_sample_opacity' => $blackOpacity,
            'white_sample_opacity' => $whiteOpacity,
            'black_sample_is_visible' => $blackOpacity === null ? null : $blackOpacity > 0.0,
            'white_sample_is_visible' => $whiteOpacity === null ? null : $whiteOpacity > 0.0,
        ];
    }

    private function ccittFaxCodingMode(int $k): string
    {
        if ($k < 0) {
            return 'group4_two_dimensional';
        }

        if ($k > 0) {
            return 'group3_mixed_two_dimensional';
        }

        return 'group3_one_dimensional';
    }

    private function ccittFaxEndOfBlockMarkerName(int $k, bool $endOfBlock): ?string
    {
        if (!$endOfBlock) {
            return null;
        }

        return $k < 0 ? 'eofb' : 'rtc';
    }

    /**
     * @param array<string, int|bool|string|null|list<string>>|null $decodeParms
     * @param array<string, true> $invalidLookup
     */
    private function ccittEffectiveInt(?array $decodeParms, string $field, int $default, array $invalidLookup): int
    {
        $value = $decodeParms[$field] ?? null;

        return is_int($value) && !isset($invalidLookup[$field]) ? $value : $default;
    }

    /**
     * @param array<string, int|bool|string|null|list<string>>|null $decodeParms
     * @param array<string, true> $invalidLookup
     */
    private function ccittEffectivePositiveInt(?array $decodeParms, string $field, int $default, array $invalidLookup): int
    {
        $value = $this->ccittEffectiveInt($decodeParms, $field, $default, $invalidLookup);

        return $value >= 1 ? $value : $default;
    }

    /**
     * @param array<string, int|bool|string|null|list<string>>|null $decodeParms
     * @param array<string, true> $invalidLookup
     */
    private function ccittEffectiveNonNegativeInt(?array $decodeParms, string $field, int $default, array $invalidLookup): int
    {
        $value = $this->ccittEffectiveInt($decodeParms, $field, $default, $invalidLookup);

        return $value >= 0 ? $value : $default;
    }

    /**
     * @param array<string, int|bool|string|null|list<string>>|null $decodeParms
     * @param array<string, true> $invalidLookup
     */
    private function ccittEffectiveBool(?array $decodeParms, string $field, bool $default, array $invalidLookup): bool
    {
        $value = $decodeParms[$field] ?? null;

        return is_bool($value) && !isset($invalidLookup[$field]) ? $value : $default;
    }

    /**
     * @param array<string, int|bool|string|null|list<string>>|null $decodeParms
     * @param array<string, true> $invalidLookup
     * @param list<string> $fields
     * @return list<string>
     */
    private function ccittDefaultsApplied(?array $decodeParms, array $invalidLookup, array $fields): array
    {
        $defaults = [];
        foreach ($fields as $field) {
            if ($decodeParms === null || !array_key_exists($field, $decodeParms) || $decodeParms[$field] === null || isset($invalidLookup[$field])) {
                $defaults[] = $field;
            }
        }

        return $defaults;
    }

    /**
     * @param array<int, string> $objects
     */
    private function xObjectResourceDictionaryBody(string $resourceDictionary, array $objects): ?string
    {
        return $this->resourceCategoryDictionaryBody($resourceDictionary, $objects, 'XObject');
    }

    /**
     * @return array{body: string, stream: string}|null
     * @param array<int, string> $objects
     */
    private function decodedFormXObject(array $objects, int $objectNumber): ?array
    {
        return $this->decodedFormXObjectBody($objects[$objectNumber] ?? null, $objects);
    }

    /**
     * @return array{body: string, stream: string}|null
     * @param array<int, string> $objects
     */
    private function decodedFormXObjectBody(?string $objectBody, array $objects): ?array
    {
        if ($objectBody === null || preg_match('/\/Subtype\s*\/Form\b/', $objectBody) !== 1) {
            return null;
        }

        $decoded = $this->decodeStreamObject($objectBody, $objects, true, true);
        if ($decoded === null) {
            return null;
        }

        return [
            'body' => $objectBody,
            'stream' => $decoded,
        ];
    }

    /**
     * @return array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}>
     * @param array<int, string> $objects
     * @param array<int, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}> $fontObjectMaps
     */
    private function fontResourceMapsForResourceOwnerBody(string $resourceOwnerBody, array $objects, array $fontObjectMaps): array
    {
        $resourceDictionary = $this->resourceDictionaryBody($resourceOwnerBody, $objects) ?? $resourceOwnerBody;

        return $this->fontResourceMapsFromResourceDictionary($resourceDictionary, $objects, $fontObjectMaps);
    }

    /**
     * @return array<string, array{actualText: string|null, altText: string|null}>
     * @param array<int, string> $objects
     */
    private function markedContentPropertiesForResourceOwnerBody(string $resourceOwnerBody, array $objects): array
    {
        $resourceDictionary = $this->resourceDictionaryBody($resourceOwnerBody, $objects) ?? $resourceOwnerBody;

        return $this->markedContentPropertiesFromResourceDictionary($resourceDictionary, $objects);
    }

    /**
     * @return array<string, array{actualText: string|null, altText: string|null}>
     * @param array<int, string> $objects
     */
    private function pageMarkedContentProperties(int $pageObjectNumber, array $objects): array
    {
        $resourceDictionary = $this->pageResourceDictionaryBody($pageObjectNumber, $objects);
        if ($resourceDictionary === null) {
            return [];
        }

        return $this->markedContentPropertiesFromResourceDictionary($resourceDictionary, $objects);
    }

    /**
     * @return array<string, string>
     * @param array<int, string> $objects
     */
    private function pageMarkedContentPropertyDictionaries(int $pageObjectNumber, array $objects): array
    {
        $resourceDictionary = $this->pageResourceDictionaryBody($pageObjectNumber, $objects);
        if ($resourceDictionary === null) {
            return [];
        }

        return $this->markedContentPropertyDictionariesFromResourceDictionary($resourceDictionary, $objects);
    }

    /**
     * @param array<string, string> $fontAliases
     */
    private function rewriteFontResourceOperands(string $content, array $fontAliases): string
    {
        if ($fontAliases === []) {
            return $content;
        }

        $rewritten = [];
        $operands = [];
        foreach ($this->contentTokens($content) as $token) {
            if ($this->isOperator($token)) {
                if ($token === 'Tf' && count($operands) >= 2) {
                    $fontOperandIndex = count($operands) - 2;
                    $fontOperand = $operands[$fontOperandIndex];
                    if (str_starts_with($fontOperand, '/')) {
                        $fontName = $this->decodePdfName(substr($fontOperand, 1));
                        if (isset($fontAliases[$fontName])) {
                            $operands[$fontOperandIndex] = '/' . $fontAliases[$fontName];
                        }
                    }
                }

                foreach ($operands as $operand) {
                    $rewritten[] = $operand;
                }
                $rewritten[] = $token;
                $operands = [];
                continue;
            }

            $operands[] = $token;
        }

        foreach ($operands as $operand) {
            $rewritten[] = $operand;
        }

        return implode(' ', $rewritten);
    }

    /**
     * @param array<string, string> $propertyAliases
     */
    private function rewriteMarkedContentPropertyOperands(string $content, array $propertyAliases): string
    {
        if ($propertyAliases === []) {
            return $content;
        }

        $rewritten = [];
        $operands = [];
        foreach ($this->contentTokens($content) as $token) {
            if ($this->isOperator($token)) {
                if ($token === 'BDC' && count($operands) >= 2) {
                    $propertyOperandIndex = count($operands) - 1;
                    $propertyOperand = $operands[$propertyOperandIndex];
                    if (str_starts_with($propertyOperand, '/')) {
                        $propertyName = $this->decodePdfName(substr($propertyOperand, 1));
                        if (isset($propertyAliases[$propertyName])) {
                            $operands[$propertyOperandIndex] = '/' . $propertyAliases[$propertyName];
                        }
                    }
                }

                foreach ($operands as $operand) {
                    $rewritten[] = $operand;
                }
                $rewritten[] = $token;
                $operands = [];
                continue;
            }

            $operands[] = $token;
        }

        foreach ($operands as $operand) {
            $rewritten[] = $operand;
        }

        return implode(' ', $rewritten);
    }

    private function formFontResourceAlias(int $formObjectNumber, string $resourceName): string
    {
        return 'Fm' . $formObjectNumber . '_' . bin2hex($resourceName);
    }

    private function formMarkedContentPropertyAlias(int $formObjectNumber, string $resourceName): string
    {
        return 'FmProp' . $formObjectNumber . '_' . bin2hex($resourceName);
    }

    private function appearanceFontResourceAlias(int $appearanceObjectNumber, string $resourceName): string
    {
        return 'Ap' . $appearanceObjectNumber . '_' . bin2hex($resourceName);
    }

    /**
     * @return list<array{stream: string, fontToUnicodeMaps: array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}>}>
     * @param array<int, string> $objects
     * @param array<int, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}> $fontObjectMaps
     * @param array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}> $fontToUnicodeMaps
     * @param array<int|string, bool> $optionalContentStates
     */
    private function annotationAppearanceStreamsWithFontMaps(
        string $pageBody,
        array $objects,
        array $fontObjectMaps,
        array $fontToUnicodeMaps,
        array $optionalContentStates = []
    ): array {
        $appearances = [];
        $currentFontToUnicodeMaps = $fontToUnicodeMaps;

        foreach ($this->annotationBodiesForPage($pageBody, $objects) as $annotation) {
            if (!$this->annotationAppearanceContributesText($annotation['body'])) {
                continue;
            }

            if (!$this->optionalContentObjectVisible($annotation['body'], $objects, $optionalContentStates)) {
                continue;
            }

            $appearanceObjectNumber = $this->normalAppearanceObjectNumber($annotation['body'], $objects);
            if ($appearanceObjectNumber === null) {
                continue;
            }

            $appearance = $this->decodedAppearanceStreamWithFontMaps(
                $appearanceObjectNumber,
                $objects,
                $fontObjectMaps,
                $currentFontToUnicodeMaps,
                $optionalContentStates
            );
            if ($appearance === null) {
                continue;
            }

            $appearances[] = $appearance;
            $currentFontToUnicodeMaps = $appearance['fontToUnicodeMaps'];
        }

        return $appearances;
    }

    private function annotationAppearanceContributesText(string $annotationBody): bool
    {
        $subtype = $this->pdfNameValueAfterName($annotationBody, 'Subtype');
        if ($subtype === null) {
            return false;
        }

        return !in_array($subtype, ['3D', 'FileAttachment', 'Movie', 'RichMedia', 'Screen', 'Sound'], true);
    }

    /**
     * @return list<array{body: string, object: int|null}>
     * @param array<int, string> $objects
     */
    private function annotationBodiesForPage(string $pageBody, array $objects): array
    {
        $annots = $this->pdfValueAfterName($pageBody, 'Annots');
        if ($annots === null) {
            return [];
        }

        return $this->annotationBodiesFromValue($annots, $objects);
    }

    /**
     * @return list<array{body: string, object: int|null}>
     * @param array<int, string> $objects
     */
    private function annotationBodiesFromValue(string $value, array $objects): array
    {
        $value = trim($value);
        if ($value === '') {
            return [];
        }

        if (preg_match('/^(\d+)\s+\d+\s+R\b/', $value, $match) === 1) {
            $objectNumber = (int) $match[1];
            if (!isset($objects[$objectNumber])) {
                return [];
            }

            $objectBody = trim($objects[$objectNumber]);
            if (str_starts_with($objectBody, '[')) {
                return $this->annotationBodiesFromArray($this->pdfArrayAtStart($objectBody), $objects);
            }

            $dictionary = $this->dictionaryObjectBody($objectBody);
            return $dictionary === null ? [] : [['body' => $dictionary, 'object' => $objectNumber]];
        }

        if (str_starts_with($value, '[')) {
            return $this->annotationBodiesFromArray($this->pdfArrayAtStart($value), $objects);
        }

        if (str_starts_with($value, '<<')) {
            $dictionary = $this->readPdfDictionaryAt($value, 0);
            return $dictionary === null ? [] : [['body' => $dictionary, 'object' => null]];
        }

        return [];
    }

    /**
     * @return list<array{body: string, object: int|null}>
     * @param array<int, string> $objects
     */
    private function annotationBodiesFromArray(?string $arrayBody, array $objects): array
    {
        if ($arrayBody === null) {
            return [];
        }

        $annotations = [];
        foreach ($this->objectReferences($arrayBody) as $objectNumber) {
            if (!isset($objects[$objectNumber])) {
                continue;
            }

            $dictionary = $this->dictionaryObjectBody($objects[$objectNumber]);
            if ($dictionary !== null) {
                $annotations[] = ['body' => $dictionary, 'object' => $objectNumber];
            }
        }

        foreach ($this->directDictionaries($arrayBody) as $dictionary) {
            $annotations[] = ['body' => $dictionary, 'object' => null];
        }

        return $annotations;
    }

    /**
     * @return list<string>
     */
    private function directDictionaries(string $value): array
    {
        $dictionaries = [];
        $offset = 0;
        while (($start = strpos($value, '<<', $offset)) !== false) {
            $dictionary = $this->readPdfDictionaryAt($value, $start);
            $end = $this->pdfDictionaryEndOffset($value, $start);
            if ($dictionary === null || $end === null) {
                break;
            }

            $dictionaries[] = $dictionary;
            $offset = $end + 1;
        }

        return $dictionaries;
    }

    /**
     * @param array<int, string> $objects
     */
    private function normalAppearanceObjectNumber(string $annotationBody, array $objects): ?int
    {
        $appearanceDictionary = $this->appearanceDictionaryBody($annotationBody, $objects);
        if ($appearanceDictionary === null) {
            return null;
        }

        $normalAppearance = $this->pdfValueAfterName($appearanceDictionary, 'N');
        if ($normalAppearance === null) {
            return null;
        }

        $appearanceState = $this->pdfNameValueAfterName($annotationBody, 'AS');
        $normalAppearance = trim($normalAppearance);
        if (preg_match('/^(\d+)\s+\d+\s+R\b/', $normalAppearance, $match) === 1) {
            $objectNumber = (int) $match[1];
            if (!isset($objects[$objectNumber])) {
                return null;
            }

            if ($this->isStreamObject($objects[$objectNumber])) {
                return $objectNumber;
            }

            $dictionary = $this->dictionaryObjectBody($objects[$objectNumber]);
            return $dictionary === null ? null : $this->appearanceObjectNumberFromStateDictionary($dictionary, $appearanceState);
        }

        if (str_starts_with($normalAppearance, '<<')) {
            $dictionary = $this->readPdfDictionaryAt($normalAppearance, 0);
            return $dictionary === null ? null : $this->appearanceObjectNumberFromStateDictionary($dictionary, $appearanceState);
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function appearanceDictionaryBody(string $annotationBody, array $objects): ?string
    {
        $appearance = $this->pdfValueAfterName($annotationBody, 'AP');
        if ($appearance === null) {
            return null;
        }

        $appearance = trim($appearance);
        if (str_starts_with($appearance, '<<')) {
            return $this->readPdfDictionaryAt($appearance, 0);
        }

        if (preg_match('/^(\d+)\s+\d+\s+R\b/', $appearance, $match) === 1) {
            $objectNumber = (int) $match[1];
            return isset($objects[$objectNumber]) ? $this->dictionaryObjectBody($objects[$objectNumber]) : null;
        }

        return null;
    }

    private function appearanceObjectNumberFromStateDictionary(string $dictionary, ?string $appearanceState): ?int
    {
        if ($appearanceState !== null) {
            return $this->objectReferenceValueAfterName($dictionary, $appearanceState);
        }

        $fallback = null;
        if (!preg_match_all('/\/([^\s\[\]()<>{}\/%]+)\s+(\d+)\s+\d+\s+R\b/', $dictionary, $matches, PREG_SET_ORDER)) {
            return null;
        }

        foreach ($matches as $match) {
            $state = $this->decodePdfName($match[1]);
            $objectNumber = (int) $match[2];
            if ($fallback === null) {
                $fallback = $objectNumber;
            }
            if ($state !== 'Off') {
                return $objectNumber;
            }
        }

        return $fallback;
    }

    /**
     * @return array{stream: string, fontToUnicodeMaps: array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}>}|null
     * @param array<int, string> $objects
     * @param array<int, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}> $fontObjectMaps
     * @param array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}> $fontToUnicodeMaps
     * @param array<int|string, bool> $optionalContentStates
     */
    private function decodedAppearanceStreamWithFontMaps(
        int $appearanceObjectNumber,
        array $objects,
        array $fontObjectMaps,
        array $fontToUnicodeMaps,
        array $optionalContentStates = []
    ): ?array {
        if (!isset($objects[$appearanceObjectNumber]) || preg_match('/\/Subtype\s*\/Form\b/', $objects[$appearanceObjectNumber]) !== 1) {
            return null;
        }

        if (!$this->optionalContentObjectVisible($objects[$appearanceObjectNumber], $objects, $optionalContentStates)) {
            return null;
        }

        $decoded = $this->decodeStreamObject($objects[$appearanceObjectNumber], $objects, true, true);
        if ($decoded === null) {
            return null;
        }

        $expandedFontToUnicodeMaps = $fontToUnicodeMaps;
        $fontAliases = [];
        foreach ($this->fontResourceMapsForResourceOwnerBody($objects[$appearanceObjectNumber], $objects, $fontObjectMaps) as $name => $map) {
            $alias = $this->appearanceFontResourceAlias($appearanceObjectNumber, $name);
            $fontAliases[$name] = $alias;
            $expandedFontToUnicodeMaps[$alias] = $map;
        }

        $decoded = $this->filterOptionalContentMarkedBlocks(
            $decoded,
            $this->optionalContentPropertyVisibilityMapForResourceOwnerBody(
                $objects[$appearanceObjectNumber],
                $objects,
                $optionalContentStates
            ),
            $objects,
            $optionalContentStates
        );

        return $this->expandFormXObjectInvocations(
            $this->rewriteFontResourceOperands($decoded, $fontAliases),
            $objects[$appearanceObjectNumber],
            $objects,
            $fontObjectMaps,
            $expandedFontToUnicodeMaps,
            [],
            $optionalContentStates,
            [],
            $this->pdfMatrixValueAfterName($objects[$appearanceObjectNumber], 'Matrix', $objects),
            $this->pdfRectangleValueAfterName($objects[$appearanceObjectNumber], 'BBox', $objects)
        );
    }

    /**
     * Native boundary for PDFium-style default-view optional content checks.
     *
     * @return array<string, bool>
     * @param array<int, string> $objects
     */
    private function optionalContentVisibilityStates(array $objects): array
    {
        $ocProperties = $this->optionalContentPropertiesDictionaryBody($objects);
        if ($ocProperties === null) {
            return [];
        }

        $ocgArray = $this->pdfArrayValueAfterNameResolved($ocProperties, 'OCGs', $objects);
        if ($ocgArray === null) {
            return [];
        }

        $states = [];
        foreach ($this->optionalContentObjectReferencesFromValue($ocgArray, $objects) as $reference) {
            $states[$this->optionalContentReferenceKey($reference['objectNumber'], $reference['generation'])] = true;
        }

        if ($states === []) {
            return [];
        }

        $defaultConfig = $this->pdfDictionaryValueAfterNameResolved($ocProperties, 'D', $objects);
        if ($defaultConfig === null) {
            return $states;
        }

        $configIntents = $this->optionalContentIntentNames($defaultConfig, $objects, ['View']);
        $intentMatches = [];
        foreach (array_keys($states) as $referenceKey) {
            $reference = $this->optionalContentReferenceFromKey((string) $referenceKey);
            if ($reference === null) {
                continue;
            }

            $intentMatches[$referenceKey] = $this->optionalContentReferenceMatchesIntent(
                $reference['objectNumber'],
                $reference['generation'],
                $objects,
                $configIntents
            );
        }

        $baseState = $this->pdfNameValueAfterName($defaultConfig, 'BaseState') ?? 'ON';
        $baseVisible = $baseState !== 'OFF';
        foreach (array_keys($states) as $referenceKey) {
            $states[$referenceKey] = $baseVisible && ($intentMatches[$referenceKey] ?? true);
        }

        foreach ($this->optionalContentObjectReferencesAfterName($defaultConfig, 'ON', $objects) as $reference) {
            $referenceKey = $this->optionalContentReferenceKey($reference['objectNumber'], $reference['generation']);
            if (array_key_exists($referenceKey, $states) && ($intentMatches[$referenceKey] ?? true)) {
                $states[$referenceKey] = true;
            }
        }

        foreach ($this->optionalContentObjectReferencesAfterName($defaultConfig, 'OFF', $objects) as $reference) {
            $referenceKey = $this->optionalContentReferenceKey($reference['objectNumber'], $reference['generation']);
            if (array_key_exists($referenceKey, $states)) {
                $states[$referenceKey] = false;
            }
        }

        $states = $this->optionalContentUsageApplicationStates($defaultConfig, $objects, $states, $configIntents);
        foreach ($intentMatches as $referenceKey => $matches) {
            if (!$matches) {
                $states[$referenceKey] = false;
            }
        }

        return $states;
    }

    /**
     * @param array<int, string> $objects
     */
    private function optionalContentPropertiesDictionaryBody(array $objects): ?string
    {
        $catalog = $this->catalogObjectBody($objects);
        if ($catalog === null) {
            return null;
        }

        $value = $this->pdfValueAfterName($catalog, 'OCProperties');
        return $value === null ? null : $this->pdfDictionaryFromValue($value, $objects);
    }

    /**
     * @return list<array{objectNumber: int, generation: int}>
     * @param array<int, string> $objects
     */
    private function optionalContentObjectReferencesAfterName(string $dictionary, string $name, array $objects): array
    {
        $arrayBody = $this->pdfArrayValueAfterNameResolved($dictionary, $name, $objects);
        return $arrayBody === null ? [] : $this->optionalContentObjectReferencesFromValue($arrayBody, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, bool> $states
     * @param list<string> $configIntents
     * @return array<string, bool>
     */
    private function optionalContentUsageApplicationStates(
        string $defaultConfig,
        array $objects,
        array $states,
        array $configIntents
    ): array {
        $applicationArray = $this->pdfArrayValueAfterNameResolved($defaultConfig, 'AS', $objects);
        if ($applicationArray === null) {
            return $states;
        }

        foreach ($this->pdfArrayItems($applicationArray) as $applicationValue) {
            $application = $this->pdfDictionaryFromValue($applicationValue, $objects);
            if ($application === null) {
                continue;
            }

            $event = $this->pdfNameValueAfterName($application, 'Event');
            if ($event !== null && $event !== 'View') {
                continue;
            }

            $categories = $this->optionalContentNameListValueAfterName($application, 'Category', $objects, []);
            if ($categories === []) {
                continue;
            }

            $ocgValue = $this->pdfValueAfterName($application, 'OCGs');
            if ($ocgValue === null) {
                continue;
            }

            foreach ($this->optionalContentObjectReferencesFromValue($ocgValue, $objects) as $reference) {
                $referenceKey = $this->optionalContentReferenceKey($reference['objectNumber'], $reference['generation']);
                if (!array_key_exists($referenceKey, $states)) {
                    continue;
                }

                $objectBody = $this->objectBodyForExactReference(
                    $objects,
                    $reference['objectNumber'],
                    $reference['generation']
                );
                $dictionary = $objectBody === null ? null : $this->dictionaryObjectBody($objectBody);
                if (
                    $dictionary === null
                    || !$this->optionalContentDictionaryMatchesIntent($dictionary, $objects, $configIntents)
                ) {
                    continue;
                }

                $usageState = $this->optionalContentUsageStateForCategories($dictionary, $categories, $objects);
                if ($usageState !== null) {
                    $states[$referenceKey] = $usageState;
                }
            }
        }

        return $states;
    }

    /**
     * @return list<array{objectNumber: int, generation: int}>
     * @param array<int, string> $objects
     */
    private function optionalContentObjectReferencesFromValue(string $value, array $objects): array
    {
        $value = trim($value);
        if ($value === '') {
            return [];
        }

        if (preg_match('/^(\d+)\s+(\d+)\s+R\s*$/s', $value, $match) === 1) {
            $reference = [
                'objectNumber' => (int) $match[1],
                'generation' => (int) $match[2],
            ];
            $arrayBody = $this->pdfArrayFromValue($value, $objects);
            return $arrayBody === null ? [$reference] : $this->objectReferencePairs($arrayBody);
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);
        return $arrayBody === null ? $this->objectReferencePairs($value) : $this->objectReferencePairs($arrayBody);
    }

    /**
     * @param array<int, string> $objects
     * @param list<string> $configIntents
     */
    private function optionalContentReferenceMatchesIntent(
        int $objectNumber,
        int $generation,
        array $objects,
        array $configIntents
    ): bool
    {
        $objectBody = $this->objectBodyForExactReference($objects, $objectNumber, $generation);
        if ($objectBody === null) {
            return true;
        }

        $dictionary = $this->dictionaryObjectBody($objectBody);
        return $dictionary === null
            || $this->optionalContentDictionaryMatchesIntent($dictionary, $objects, $configIntents);
    }

    private function optionalContentReferenceKey(int $objectNumber, int $generation): string
    {
        return $objectNumber . ':' . $generation;
    }

    /**
     * @return array{objectNumber: int, generation: int}|null
     */
    private function optionalContentReferenceFromKey(string $referenceKey): ?array
    {
        if (preg_match('/^(\d+):(\d+)$/', $referenceKey, $match) !== 1) {
            return null;
        }

        return [
            'objectNumber' => (int) $match[1],
            'generation' => (int) $match[2],
        ];
    }

    /**
     * @param array<int, string> $objects
     * @param list<string> $configIntents
     */
    private function optionalContentDictionaryMatchesIntent(string $dictionary, array $objects, array $configIntents): bool
    {
        $type = $this->pdfNameValueAfterName($dictionary, 'Type') ?? 'OCG';
        if ($type !== 'OCG') {
            return true;
        }

        $groupIntents = $this->optionalContentIntentNames($dictionary, $objects, ['View']);
        return $this->optionalContentIntentsIntersect($configIntents, $groupIntents);
    }

    /**
     * @return list<string>
     * @param array<int, string> $objects
     * @param list<string> $default
     */
    private function optionalContentIntentNames(string $dictionary, array $objects, array $default): array
    {
        return $this->optionalContentNameListValueAfterName($dictionary, 'Intent', $objects, $default);
    }

    /**
     * @return list<string>
     * @param array<int, string> $objects
     * @param list<string> $default
     */
    private function optionalContentNameListValueAfterName(
        string $dictionary,
        string $name,
        array $objects,
        array $default
    ): array {
        $value = $this->pdfValueAfterName($dictionary, $name);
        if ($value === null) {
            return $default;
        }

        $names = $this->optionalContentNameListFromValue($value, $objects);
        return $names === [] ? $default : $names;
    }

    /**
     * @return list<string>
     * @param array<int, string> $objects
     */
    private function optionalContentNameListFromValue(string $value, array $objects): array
    {
        $value = trim($value);
        if ($value === '') {
            return [];
        }

        if (str_starts_with($value, '/')) {
            return [$this->decodePdfName(substr($value, 1))];
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);
        if ($arrayBody === null) {
            return [];
        }

        $names = [];
        foreach ($this->pdfArrayItems($arrayBody) as $item) {
            $item = trim($item);
            if (str_starts_with($item, '/')) {
                $names[] = $this->decodePdfName(substr($item, 1));
            }
        }

        return array_values(array_unique($names));
    }

    /**
     * @param list<string> $configIntents
     * @param list<string> $groupIntents
     */
    private function optionalContentIntentsIntersect(array $configIntents, array $groupIntents): bool
    {
        if (in_array('All', $configIntents, true) || in_array('All', $groupIntents, true)) {
            return true;
        }

        foreach ($groupIntents as $intent) {
            if (in_array($intent, $configIntents, true)) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param list<string> $categories
     * @param array<int, string> $objects
     */
    private function optionalContentUsageStateForCategories(
        string $dictionary,
        array $categories,
        array $objects
    ): ?bool {
        $usage = $this->pdfDictionaryValueAfterNameResolved($dictionary, 'Usage', $objects);
        if ($usage === null) {
            return null;
        }

        foreach ($categories as $category) {
            $categoryUsage = $this->pdfDictionaryValueAfterNameResolved($usage, $category, $objects);
            if ($categoryUsage === null) {
                continue;
            }

            $stateName = match ($category) {
                'Print' => 'PrintState',
                'Export' => 'ExportState',
                default => $category . 'State',
            };
            $state = $this->pdfNameValueAfterName($categoryUsage, $stateName);
            if ($state === 'ON') {
                return true;
            }
            if ($state === 'OFF') {
                return false;
            }
        }

        return null;
    }

    /**
     * @return array<string, bool>
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function pageOptionalContentPropertyVisibilityMap(
        int $pageObjectNumber,
        array $objects,
        array $optionalContentStates
    ): array {
        $resourceDictionary = $this->pageResourceDictionaryBody($pageObjectNumber, $objects);
        if ($resourceDictionary === null) {
            return [];
        }

        return $this->optionalContentPropertyVisibilityMapForResourceOwnerBody(
            $resourceDictionary,
            $objects,
            $optionalContentStates
        );
    }

    /**
     * @return array<string, bool>
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function optionalContentPropertyVisibilityMapForResourceOwnerBody(
        string $resourceOwnerBody,
        array $objects,
        array $optionalContentStates
    ): array {
        $resourceDictionary = $this->resourceDictionaryBody($resourceOwnerBody, $objects) ?? $resourceOwnerBody;
        $propertiesDictionary = $this->propertiesResourceDictionaryBody($resourceDictionary, $objects);
        if ($propertiesDictionary === null) {
            return [];
        }

        $properties = [];
        $offset = 0;
        while (preg_match('/\/([^\s\[\]()<>{}\/%]+)/s', $propertiesDictionary, $match, PREG_OFFSET_CAPTURE, $offset) === 1) {
            $name = $this->decodePdfName($match[1][0]);
            $valueOffset = $this->skipPdfWhitespace($propertiesDictionary, $match[0][1] + strlen($match[0][0]));
            if ($valueOffset >= strlen($propertiesDictionary)) {
                break;
            }

            if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $propertiesDictionary, $referenceMatch, 0, $valueOffset) === 1) {
                $properties[$name] = $this->optionalContentReferenceVisible(
                    (int) $referenceMatch[1],
                    (int) $referenceMatch[2],
                    $objects,
                    $optionalContentStates
                );
                $offset = $valueOffset + strlen($referenceMatch[0]);
                continue;
            }

            if (substr($propertiesDictionary, $valueOffset, 2) === '<<') {
                $dictionaryOffset = $valueOffset;
                $dictionary = $this->readPdfDictionaryTokenAt($propertiesDictionary, $dictionaryOffset);
                if ($dictionary !== null) {
                    $properties[$name] = $this->optionalContentDictionaryVisible(
                        $dictionary,
                        $objects,
                        $optionalContentStates
                    );
                    $offset = $dictionaryOffset;
                    continue;
                }
            }

            $offset = $valueOffset + 1;
        }

        return $properties;
    }

    /**
     * @param array<string, bool> $propertyVisibility
     */
    private function filterOptionalContentMarkedBlocks(
        string $content,
        array $propertyVisibility,
        array $objects = [],
        array $optionalContentStates = []
    ): string
    {
        if (!str_contains($content, 'BDC')) {
            return $content;
        }

        $filtered = [];
        $operands = [];
        $hiddenDepth = 0;

        foreach ($this->contentTokens($content) as $token) {
            if ($token === 'BDC') {
                $hidden = $hiddenDepth > 0 || $this->markedOptionalContentIsHidden(
                    $operands,
                    $propertyVisibility,
                    $objects,
                    $optionalContentStates
                );
                if ($hidden) {
                    $hiddenDepth++;
                    $operands = [];
                    continue;
                }

                foreach ($operands as $operand) {
                    $filtered[] = $operand;
                }
                $filtered[] = $token;
                $operands = [];
                continue;
            }

            if ($token === 'BMC') {
                if ($hiddenDepth > 0) {
                    $hiddenDepth++;
                    $operands = [];
                    continue;
                }

                foreach ($operands as $operand) {
                    $filtered[] = $operand;
                }
                $filtered[] = $token;
                $operands = [];
                continue;
            }

            if ($token === 'EMC') {
                if ($hiddenDepth > 0) {
                    $hiddenDepth--;
                    $operands = [];
                    continue;
                }

                foreach ($operands as $operand) {
                    $filtered[] = $operand;
                }
                $filtered[] = $token;
                $operands = [];
                continue;
            }

            if ($hiddenDepth > 0) {
                if ($this->isOperator($token)) {
                    $operands = [];
                    continue;
                }

                $operands[] = $token;
                continue;
            }

            if ($this->isOperator($token)) {
                foreach ($operands as $operand) {
                    $filtered[] = $operand;
                }
                $filtered[] = $token;
                $operands = [];
                continue;
            }

            $operands[] = $token;
        }

        if ($hiddenDepth === 0) {
            foreach ($operands as $operand) {
                $filtered[] = $operand;
            }
        }

        return implode(' ', $filtered);
    }

    private function filterArtifactMarkedContentBlocks(string $content): string
    {
        if (!str_contains($content, 'BMC') && !str_contains($content, 'BDC')) {
            return $content;
        }

        $filtered = [];
        $operands = [];
        $hiddenDepth = 0;

        foreach ($this->contentTokens($content) as $token) {
            if ($token === 'BMC' || $token === 'BDC') {
                $hidden = $hiddenDepth > 0 || $this->markedContentTagIsArtifact($operands);
                if ($hidden) {
                    $hiddenDepth++;
                    $operands = [];
                    continue;
                }

                foreach ($operands as $operand) {
                    $filtered[] = $operand;
                }
                $filtered[] = $token;
                $operands = [];
                continue;
            }

            if ($token === 'EMC') {
                if ($hiddenDepth > 0) {
                    $hiddenDepth--;
                    $operands = [];
                    continue;
                }

                foreach ($operands as $operand) {
                    $filtered[] = $operand;
                }
                $filtered[] = $token;
                $operands = [];
                continue;
            }

            if ($hiddenDepth > 0) {
                if ($this->isOperator($token)) {
                    $operands = [];
                    continue;
                }

                $operands[] = $token;
                continue;
            }

            if ($this->isOperator($token)) {
                foreach ($operands as $operand) {
                    $filtered[] = $operand;
                }
                $filtered[] = $token;
                $operands = [];
                continue;
            }

            $operands[] = $token;
        }

        if ($hiddenDepth === 0) {
            foreach ($operands as $operand) {
                $filtered[] = $operand;
            }
        }

        return implode(' ', $filtered);
    }

    /**
     * @param list<string> $operands
     */
    private function markedContentTagIsArtifact(array $operands): bool
    {
        foreach ($operands as $operand) {
            if (is_string($operand) && str_starts_with($operand, '/')) {
                return $this->decodePdfName(substr($operand, 1)) === 'Artifact';
            }
        }

        return false;
    }

    /**
     * @param list<string> $operands
     * @param array<string, bool> $propertyVisibility
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function markedOptionalContentIsHidden(
        array $operands,
        array $propertyVisibility,
        array $objects = [],
        array $optionalContentStates = []
    ): bool
    {
        if (count($operands) < 2) {
            return false;
        }

        $tagIndex = count($operands) - 2;
        $propertyOperand = $operands[count($operands) - 1];
        if (
            count($operands) >= 4
            && $operands[count($operands) - 1] === 'R'
            && preg_match('/^\d+$/', $operands[count($operands) - 3]) === 1
            && preg_match('/^\d+$/', $operands[count($operands) - 2]) === 1
        ) {
            $tagIndex = count($operands) - 4;
            $propertyOperand = $operands[count($operands) - 3]
                . ' '
                . $operands[count($operands) - 2]
                . ' R';
        }

        if (!isset($operands[$tagIndex])) {
            return false;
        }

        $tagOperand = $operands[$tagIndex];
        if (!str_starts_with($tagOperand, '/') || $this->decodePdfName(substr($tagOperand, 1)) !== 'OC') {
            return false;
        }

        $propertyOperand = trim($propertyOperand);
        if (str_starts_with($propertyOperand, '/')) {
            $propertyName = $this->decodePdfName(substr($propertyOperand, 1));
            return isset($propertyVisibility[$propertyName]) && !$propertyVisibility[$propertyName];
        }

        if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', $propertyOperand, $match) === 1) {
            return !$this->optionalContentReferenceVisible(
                (int) $match[1],
                (int) $match[2],
                $objects,
                $optionalContentStates
            );
        }

        if (str_starts_with($propertyOperand, '<<')) {
            $dictionary = $this->readPdfDictionaryAt($propertyOperand, 0);
            return $dictionary !== null
                && !$this->optionalContentDictionaryVisible($dictionary, $objects, $optionalContentStates);
        }

        return false;
    }

    /**
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function optionalContentObjectVisible(string $objectBody, array $objects, array $optionalContentStates): bool
    {
        $trimmed = trim($objectBody);
        $dictionary = str_starts_with($trimmed, '<<')
            ? ($this->dictionaryObjectBody($objectBody) ?? $objectBody)
            : $objectBody;
        $optionalContent = $this->pdfValueAfterName($dictionary, 'OC');
        return $optionalContent === null
            || $this->optionalContentValueVisible($optionalContent, $objects, $optionalContentStates);
    }

    /**
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function optionalContentValueVisible(string $value, array $objects, array $optionalContentStates): bool
    {
        $value = trim($value);
        if ($value === '') {
            return true;
        }

        if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', $value, $match) === 1) {
            return $this->optionalContentReferenceVisible(
                (int) $match[1],
                (int) $match[2],
                $objects,
                $optionalContentStates
            );
        }

        if (str_starts_with($value, '<<')) {
            $dictionary = $this->readPdfDictionaryAt($value, 0);
            return $dictionary === null
                || $this->optionalContentDictionaryVisible($dictionary, $objects, $optionalContentStates);
        }

        if (str_starts_with($value, '[')) {
            $values = $this->optionalContentVisibilityValuesFromValue($value, $objects, $optionalContentStates);
            return $values === [] || in_array(true, $values, true);
        }

        return true;
    }

    /**
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function optionalContentReferenceVisible(
        int $objectNumber,
        int $generation,
        array $objects,
        array $optionalContentStates
    ): bool
    {
        $referenceKey = $this->optionalContentReferenceKey($objectNumber, $generation);
        if (array_key_exists($referenceKey, $optionalContentStates)) {
            return $optionalContentStates[$referenceKey];
        }
        if ($generation === 0 && array_key_exists($objectNumber, $optionalContentStates)) {
            return $optionalContentStates[$objectNumber];
        }

        $objectBody = $this->objectBodyForExactReference($objects, $objectNumber, $generation);
        if ($objectBody === null) {
            return true;
        }

        $dictionary = $this->dictionaryObjectBody($objectBody);
        if ($dictionary === null) {
            return true;
        }

        return $this->optionalContentDictionaryVisible(
            $dictionary,
            $objects,
            $optionalContentStates,
            $objectNumber,
            $generation
        );
    }

    /**
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function optionalContentDictionaryVisible(
        string $dictionary,
        array $objects,
        array $optionalContentStates,
        ?int $objectNumber = null,
        int $generation = 0
    ): bool {
        $type = $this->pdfNameValueAfterName($dictionary, 'Type') ?? 'OCG';
        if ($type === 'OCMD') {
            return $this->optionalContentMembershipVisible($dictionary, $objects, $optionalContentStates);
        }

        if ($type !== 'OCG') {
            return true;
        }

        if ($objectNumber !== null) {
            $referenceKey = $this->optionalContentReferenceKey($objectNumber, $generation);
            if (array_key_exists($referenceKey, $optionalContentStates)) {
                return $optionalContentStates[$referenceKey];
            }
            if ($generation === 0 && array_key_exists($objectNumber, $optionalContentStates)) {
                return $optionalContentStates[$objectNumber];
            }
        }

        if (!$this->optionalContentDictionaryMatchesIntent($dictionary, $objects, ['View'])) {
            return false;
        }

        return $this->optionalContentUsageStateForCategories($dictionary, ['View'], $objects) ?? true;
    }

    /**
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function optionalContentMembershipVisible(
        string $dictionary,
        array $objects,
        array $optionalContentStates
    ): bool {
        $ocgs = $this->pdfValueAfterName($dictionary, 'OCGs');
        if ($ocgs === null) {
            return true;
        }

        $values = $this->optionalContentVisibilityValuesFromValue($ocgs, $objects, $optionalContentStates);
        if ($values === []) {
            return true;
        }

        $policy = $this->pdfNameValueAfterName($dictionary, 'P') ?? 'AnyOn';
        return match ($policy) {
            'AllOn' => !in_array(false, $values, true),
            'AnyOff' => in_array(false, $values, true),
            'AllOff' => !in_array(true, $values, true),
            default => in_array(true, $values, true),
        };
    }

    /**
     * @return list<bool>
     * @param array<int, string> $objects
     * @param array<int|string, bool> $optionalContentStates
     */
    private function optionalContentVisibilityValuesFromValue(
        string $value,
        array $objects,
        array $optionalContentStates
    ): array {
        $value = trim($value);
        if ($value === '') {
            return [];
        }

        if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', $value, $match) === 1) {
            return [
                $this->optionalContentReferenceVisible(
                    (int) $match[1],
                    (int) $match[2],
                    $objects,
                    $optionalContentStates
                ),
            ];
        }

        if (str_starts_with($value, '<<')) {
            $dictionary = $this->readPdfDictionaryAt($value, 0);
            return $dictionary === null ? [] : [$this->optionalContentDictionaryVisible($dictionary, $objects, $optionalContentStates)];
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);
        if ($arrayBody === null) {
            return [];
        }

        $values = [];
        foreach ($this->objectReferencePairs($arrayBody) as $reference) {
            $values[] = $this->optionalContentReferenceVisible(
                $reference['objectNumber'],
                $reference['generation'],
                $objects,
                $optionalContentStates
            );
        }

        return $values;
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfArrayValueAfterNameResolved(string $body, string $name, array $objects): ?string
    {
        $value = $this->pdfValueAfterName($body, $name);
        return $value === null ? null : $this->pdfArrayFromValue($value, $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfDictionaryValueAfterNameResolved(string $body, string $name, array $objects): ?string
    {
        $value = $this->pdfValueAfterName($body, $name);
        return $value === null ? null : $this->pdfDictionaryFromValue($value, $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfArrayFromValue(string $value, array $objects): ?string
    {
        $offset = $this->skipPdfWhitespace($value, 0);
        if (($value[$offset] ?? '') === '[') {
            return $this->readPdfArrayAt($value, $offset);
        }

        if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $value, $match, 0, $offset) !== 1) {
            return null;
        }

        $objectNumber = (int) $match[1];
        $generation = (int) $match[2];
        $body = $this->objectBodyForExactReference($objects, $objectNumber, $generation);

        return $body === null ? null : $this->pdfArrayAtStart(trim($body));
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfDictionaryFromValue(string $value, array $objects): ?string
    {
        $offset = $this->skipPdfWhitespace($value, 0);
        if (substr($value, $offset, 2) === '<<') {
            return $this->readPdfDictionaryAt($value, $offset);
        }

        if (preg_match('/\G(\d+)\s+\d+\s+R\b/s', $value, $match, 0, $offset) !== 1) {
            return null;
        }

        $objectNumber = (int) $match[1];
        return isset($objects[$objectNumber]) ? $this->dictionaryObjectBody($objects[$objectNumber]) : null;
    }

    private function isStreamObject(string $objectBody): bool
    {
        return preg_match('/\bstream\r?\n?/s', $objectBody) === 1;
    }

    /**
     * @param list<string> $operands
     */
    private function xObjectNameOperand(array $operands): ?string
    {
        if (count($operands) !== 1) {
            return null;
        }

        $operand = end($operands);
        if (!is_string($operand) || !str_starts_with($operand, '/')) {
            return null;
        }

        return $this->decodePdfName(substr($operand, 1));
    }

    /**
     * @return list<string>
     * @param array<int, string> $objects
     */
    private function allDecodedStreams(string $pdfBytes, array $objects): array
    {
        $streams = [];
        $definitions = $this->directObjectDefinitions($pdfBytes);
        if ($definitions === []) {
            return $streams;
        }

        $preliminaryObjects = $this->latestDirectObjects($definitions);
        if ($this->startxrefXrefStreamFilterDecodeFailed($pdfBytes, $preliminaryObjects, $definitions)) {
            return $streams;
        }

        $xrefEntries = $this->xrefEntries($pdfBytes, $preliminaryObjects, $definitions);
        $linearizedHintRanges = $this->linearizedHintTableRanges($pdfBytes);
        $linearizedHintObjectNumbers = array_fill_keys(
            $this->linearizedHintTableObjectNumbers($pdfBytes, $definitions, $linearizedHintRanges, $objects),
            true
        );
        $embeddedFilePayloadObjectNumbers = $this->embeddedFilePayloadObjectNumbers($objects);
        $pieceInfoPrivateObjectNumbers = $this->pieceInfoPrivateStreamObjectNumbers($objects);
        $type3CharProcObjectGenerations = $this->type3CharProcObjectGenerationSet($objects);
        $type3CharProcResourceObjectGenerations = $this->type3CharProcResourceObjectGenerationSet($objects);
        foreach ($this->liveDirectObjectDefinitionsInFileOrder($definitions, $xrefEntries) as $definition) {
            $streamObjectNumber = $definition['objectNumber'];
            if (
                isset($linearizedHintObjectNumbers[$streamObjectNumber])
                || !isset($objects[$streamObjectNumber])
                || $objects[$streamObjectNumber] !== $definition['body']
                || isset($embeddedFilePayloadObjectNumbers[$streamObjectNumber])
                || isset($pieceInfoPrivateObjectNumbers[$streamObjectNumber])
                || isset($type3CharProcObjectGenerations[$streamObjectNumber][$definition['generation']])
                || isset($type3CharProcResourceObjectGenerations[$streamObjectNumber][$definition['generation']])
            ) {
                continue;
            }

            $entry = $this->streamDictionaryAndPayload($definition['body'], $objects);
            if ($entry === null) {
                continue;
            }

            if (
                $this->isObjectStreamDictionary($entry['dict'], $objects)
                || $this->isXrefStreamDictionary($entry['dict'], $objects)
                || $this->isImageStreamDictionary($entry['dict'], $objects)
                || $this->isEmbeddedFileStreamDictionary($entry['dict'])
            ) {
                continue;
            }

            $decoded = $this->decodeStream($entry['dict'], $entry['stream'], $objects, false, true, true);
            if ($decoded === null) {
                continue;
            }
            $streams[] = $decoded;
        }

        return $streams;
    }

    /**
     * @return array<int, array<int, true>>
     * @param array<int, string> $objects
     */
    private function type3CharProcObjectGenerationSet(array $objects): array
    {
        $references = [];
        foreach ($objects as $body) {
            if (!$this->isType3FontBody($body)) {
                continue;
            }

            foreach ($this->charProcObjectReferences($body, $objects) as $reference) {
                $references[$reference['objectNumber']][$reference['generation']] = true;
            }
        }

        return $references;
    }

    /**
     * @return array<int, array<int, true>>
     * @param array<int, string> $objects
     */
    private function type3CharProcResourceObjectGenerationSet(array $objects): array
    {
        $references = [];
        foreach ($objects as $body) {
            if (!$this->isType3FontBody($body)) {
                continue;
            }

            $this->collectType3PrivateXObjectResourceGenerations($body, $objects, $references);
            foreach ($this->charProcObjectReferences($body, $objects) as $reference) {
                $charProcBody = $this->objectBodyForExactReference(
                    $objects,
                    $reference['objectNumber'],
                    $reference['generation']
                );
                if ($charProcBody === null) {
                    continue;
                }

                $this->collectType3PrivateXObjectResourceGenerations($charProcBody, $objects, $references);
            }
        }

        return $references;
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, array<int, true>> $references
     * @param array<string, true> $seen
     */
    private function collectType3PrivateXObjectResourceGenerations(
        string $resourceOwnerBody,
        array $objects,
        array &$references,
        array $seen = []
    ): void {
        foreach ($this->xObjectResourceReferences($resourceOwnerBody, $objects) as $reference) {
            $key = $reference['objectNumber'] . ':' . $reference['generation'];
            if (isset($seen[$key])) {
                continue;
            }

            $references[$reference['objectNumber']][$reference['generation']] = true;
            $seen[$key] = true;

            $body = $reference['body'];
            if ($body === null || !$this->isFormXObjectBody($body, $objects)) {
                continue;
            }

            $this->collectType3PrivateXObjectResourceGenerations($body, $objects, $references, $seen);
        }
    }

    /**
     * @param array<int, string> $objects
     */
    private function isFormXObjectBody(string $body, array $objects): bool
    {
        $dictionary = $this->dictionaryObjectBody($body);
        if ($dictionary === null) {
            return false;
        }

        return $this->streamDictionaryHasName($dictionary, 'Subtype', 'Form', $objects);
    }

    /**
     * @param array<int, string> $objects
     * @return array<int, true>
     */
    private function embeddedFilePayloadObjectNumbers(array $objects): array
    {
        $payloadObjectNumbers = [];
        foreach ($objects as $body) {
            foreach ($this->embeddedFileDictionariesFromBody($body, $objects) as $efDictionary) {
                foreach (['F', 'UF', 'DOS', 'Unix', 'Mac'] as $key) {
                    $value = $this->pdfValueAfterName($efDictionary, $key);
                    if ($value === null) {
                        continue;
                    }

                    foreach ($this->objectReferences($value) as $objectNumber) {
                        $payloadObjectNumbers[$objectNumber] = true;
                    }
                }
            }
        }

        return $payloadObjectNumbers;
    }

    /**
     * @param array<int, string> $objects
     * @return array<int, true>
     */
    private function pieceInfoPrivateStreamObjectNumbers(array $objects): array
    {
        $streamObjectNumbers = [];
        foreach ($objects as $body) {
            foreach ($this->pieceInfoDictionariesFromBody($body, $objects) as $pieceInfoDictionary) {
                foreach ($this->pieceInfoPrivateObjectNumbersFromDictionary($pieceInfoDictionary, $objects) as $privateObjectNumber) {
                    if (!isset($objects[$privateObjectNumber])) {
                        continue;
                    }

                    if ($this->streamDictionaryAndPayload($objects[$privateObjectNumber], $objects) !== null) {
                        $streamObjectNumbers[$privateObjectNumber] = true;
                    }
                }
            }
        }

        return $streamObjectNumbers;
    }

    /**
     * @param array<int, string> $objects
     * @return list<int>
     */
    private function pieceInfoPrivateObjectNumbersFromDictionary(string $pieceInfoDictionary, array $objects): array
    {
        $objectNumbers = $this->directPrivateObjectNumbers($pieceInfoDictionary);
        foreach ($this->pieceInfoApplicationDictionaries($pieceInfoDictionary, $objects) as $applicationDictionary) {
            foreach ($this->directPrivateObjectNumbers($applicationDictionary) as $objectNumber) {
                $objectNumbers[] = $objectNumber;
            }
        }

        return array_values(array_unique($objectNumbers));
    }

    /**
     * @return list<int>
     */
    private function directPrivateObjectNumbers(string $dictionary): array
    {
        $matchCount = preg_match_all('/\/Private\s+(\d+)\s+\d+\s+R\b/s', $dictionary, $matches);
        if ($matchCount === false || $matchCount === 0) {
            return [];
        }

        return array_map('intval', $matches[1]);
    }

    /**
     * @param array<int, string> $objects
     * @return list<string>
     */
    private function pieceInfoApplicationDictionaries(string $pieceInfoDictionary, array $objects): array
    {
        $dictionaries = [];
        for ($offset = 0, $length = strlen($pieceInfoDictionary); $offset < $length;) {
            $offset = $this->skipPdfWhitespace($pieceInfoDictionary, $offset);
            if ($offset >= $length) {
                break;
            }

            if (($pieceInfoDictionary[$offset] ?? '') !== '/') {
                $offset++;
                continue;
            }

            if (preg_match('/\G\/[^\s\[\]()<>{}\/%]+/s', $pieceInfoDictionary, $nameMatch, 0, $offset) !== 1) {
                $offset++;
                continue;
            }

            $valueOffset = $this->skipPdfWhitespace($pieceInfoDictionary, $offset + strlen($nameMatch[0]));
            $value = $this->pdfValueAtOffset($pieceInfoDictionary, $valueOffset);
            if ($value === null) {
                $offset += strlen($nameMatch[0]);
                continue;
            }

            $applicationDictionary = $this->pdfDictionaryFromValue($value, $objects);
            if ($applicationDictionary !== null) {
                $dictionaries[] = $applicationDictionary;
            }

            $offset = max($valueOffset + strlen($value), $offset + strlen($nameMatch[0]));
        }

        return $dictionaries;
    }

    /**
     * @param array<int, string> $objects
     * @return list<string>
     */
    private function pieceInfoDictionariesFromBody(string $body, array $objects): array
    {
        $dictionaries = [];
        $offset = 0;
        while (preg_match('/\/PieceInfo\b/s', $body, $match, PREG_OFFSET_CAPTURE, $offset) === 1) {
            $valueOffset = $this->skipPdfWhitespace($body, $match[0][1] + strlen($match[0][0]));
            $value = $this->pdfValueAtOffset($body, $valueOffset);
            if ($value !== null) {
                $dictionary = $this->pdfDictionaryFromValue($value, $objects);
                if ($dictionary !== null) {
                    $dictionaries[] = $dictionary;
                }
            }

            $offset = max($valueOffset + 1, $match[0][1] + strlen($match[0][0]));
        }

        return $dictionaries;
    }

    /**
     * @param array<int, string> $objects
     * @return list<string>
     */
    private function embeddedFileDictionariesFromBody(string $body, array $objects): array
    {
        $dictionaries = [];
        $offset = 0;
        while (preg_match('/\/(?:EF|RF)\b/s', $body, $match, PREG_OFFSET_CAPTURE, $offset) === 1) {
            $valueOffset = $this->skipPdfWhitespace($body, $match[0][1] + strlen($match[0][0]));
            $value = $this->pdfValueAtOffset($body, $valueOffset);
            if ($value !== null) {
                $dictionary = $this->pdfDictionaryFromValue($value, $objects);
                if ($dictionary !== null) {
                    $dictionaries[] = $dictionary;
                }
            }

            $offset = max($valueOffset + 1, $match[0][1] + strlen($match[0][0]));
        }

        return $dictionaries;
    }

    private function pdfValueAtOffset(string $body, int $offset): ?string
    {
        $offset = $this->skipPdfWhitespace($body, $offset);
        if ($offset >= strlen($body)) {
            return null;
        }

        if ($body[$offset] === '[') {
            $array = $this->readPdfArrayAt($body, $offset);
            return $array === null ? null : '[' . $array . ']';
        }

        if (substr($body, $offset, 2) === '<<') {
            $end = $this->pdfDictionaryEndOffset($body, $offset);
            return $end === null ? null : substr($body, $offset, $end - $offset + 1);
        }

        if ($body[$offset] === '(') {
            $end = $this->skipPdfLiteralStringAt($body, $offset);
            return $end === null ? null : substr($body, $offset, $end - $offset + 1);
        }

        if ($body[$offset] === '<') {
            $end = strpos($body, '>', $offset + 1);
            return $end === false ? null : substr($body, $offset, $end - $offset + 1);
        }

        $reference = $this->pdfIndirectReferenceTokenAt($body, $offset);
        if ($reference !== null) {
            return $reference['token'];
        }

        if ($body[$offset] === '/') {
            $end = $offset + 1;
            while ($end < strlen($body) && !str_contains(" \t\r\n\f[]()<>{}/%", $body[$end])) {
                $end++;
            }

            return substr($body, $offset, $end - $offset);
        }

        $end = $offset;
        while ($end < strlen($body) && !ctype_space($body[$end]) && !str_contains('[]()<>{}/%', $body[$end])) {
            $end++;
        }

        return $end === $offset ? null : substr($body, $offset, $end - $offset);
    }

    /**
     * @param array<int, list<array{generation: int, offset: int, bodyStart: int, bodyEnd: int, body: string}>>|null $definitions
     */
    private function directObjectNumberAtOffset(string $pdfBytes, int $offset, ?array $definitions = null): ?int
    {
        $definitions ??= $this->directObjectDefinitions($pdfBytes);
        $ownerObjectNumber = null;
        $ownerOffset = -1;
        foreach ($definitions as $objectNumber => $entries) {
            foreach ($entries as $definition) {
                if (
                    $offset < $definition['bodyStart']
                    || $offset > $definition['bodyEnd']
                    || $definition['offset'] < $ownerOffset
                ) {
                    continue;
                }

                $ownerObjectNumber = $objectNumber;
                $ownerOffset = $definition['offset'];
            }
        }

        return $ownerObjectNumber;
    }

    /**
     * @param array<int, string> $objects
     */
    private function isImageStreamDictionary(string $dict, array $objects): bool
    {
        $subtype = $this->topLevelPdfValueAfterNameInDictionaryBody($dict, 'Subtype');
        if ($subtype !== null && $this->pdfNameValueAt($subtype, 0, $objects) === 'Image') {
            return true;
        }

        if (!$this->hasPdfNumberishName($dict, 'Width') || !$this->hasPdfNumberishName($dict, 'Height')) {
            return false;
        }

        $hasBitsPerComponent = $this->hasPdfNumberishName($dict, 'BitsPerComponent')
            || $this->hasPdfNumberishName($dict, 'BPC');
        if (!$hasBitsPerComponent && preg_match('/\/ImageMask\s+true\b/', $dict) !== 1) {
            return false;
        }

        return $this->imageColorSpaceFamily($dict, $objects) !== null
            || preg_match('/\/ImageMask\s+true\b/', $dict) === 1;
    }

    private function hasPdfNumberishName(string $dict, string $name): bool
    {
        $offset = $this->topLevelNameValueOffset($dict, $name);
        if ($offset === null) {
            return false;
        }

        return preg_match('/\G(?:[+-]?(?:\d+(?:\.\d*)?|\.\d+)|\d+\s+\d+\s+R\b)/s', $dict, $match, 0, $offset) === 1;
    }

    /**
     * @param array<int, string> $objects
     */
    private function imageColorSpaceFamily(string $dict, array $objects): ?string
    {
        return $this->imageColorSpaceReview($dict, $objects)['family'];
    }

    /**
     * @param array<int, string> $objects
     * @return array{family: string|null, resource_name: string|null, resolved_from_resources: bool, resource_source: string|null}
     */
    private function imageColorSpaceReview(string $dict, array $objects, ?string $resourceOwnerBody = null): array
    {
        foreach (['ColorSpace', 'CS'] as $name) {
            $offset = $this->topLevelNameValueOffset($dict, $name);
            if ($offset === null) {
                continue;
            }

            $review = $this->colorSpaceFamilyReviewAt($dict, $offset, $objects, $resourceOwnerBody);
            if ($review['family'] !== null) {
                return $review;
            }
        }

        return [
            'family' => null,
            'resource_name' => null,
            'resolved_from_resources' => false,
            'resource_source' => null,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, true> $seenObjects
     */
    private function colorSpaceFamilyAt(string $value, int $offset, array $objects, array $seenObjects = []): ?string
    {
        return $this->colorSpaceFamilyReviewAt($value, $offset, $objects, null, $seenObjects)['family'];
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, true> $seenObjects
     * @param array<string, true> $seenResourceNames
     * @return array{family: string|null, resource_name: string|null, resolved_from_resources: bool, resource_source: string|null}
     */
    private function colorSpaceFamilyReviewAt(
        string $value,
        int $offset,
        array $objects,
        ?string $resourceOwnerBody = null,
        array $seenObjects = [],
        array $seenResourceNames = []
    ): array
    {
        $offset = $this->skipPdfWhitespace($value, $offset);
        if ($offset >= strlen($value)) {
            return [
                'family' => null,
                'resource_name' => null,
                'resolved_from_resources' => false,
                'resource_source' => null,
            ];
        }

        if (preg_match('/\G\/([^\s\[\]()<>{}\/%]+)/s', $value, $match, 0, $offset) === 1) {
            $name = $this->decodePdfName($match[1]);
            $family = $this->recognizedImageColorSpace($name);
            if ($family !== null) {
                return [
                    'family' => $family,
                    'resource_name' => null,
                    'resolved_from_resources' => false,
                    'resource_source' => null,
                ];
            }

            if ($resourceOwnerBody === null || isset($seenResourceNames[$name])) {
                return [
                    'family' => null,
                    'resource_name' => null,
                    'resolved_from_resources' => false,
                    'resource_source' => null,
                ];
            }

            $resourceValue = $this->colorSpaceResourceValue($resourceOwnerBody, $objects, $name);
            if ($resourceValue === null) {
                return [
                    'family' => null,
                    'resource_name' => null,
                    'resolved_from_resources' => false,
                    'resource_source' => null,
                ];
            }

            $seenResourceNames[$name] = true;
            $resourceReview = $this->colorSpaceFamilyReviewAt(
                $resourceValue,
                0,
                $objects,
                $resourceOwnerBody,
                $seenObjects,
                $seenResourceNames
            );
            if ($resourceReview['family'] === null) {
                return $resourceReview;
            }

            return [
                'family' => $resourceReview['family'],
                'resource_name' => $name,
                'resolved_from_resources' => true,
                'resource_source' => 'Resources.ColorSpace',
            ];
        }

        if ($value[$offset] === '[') {
            $arrayBody = $this->readPdfArrayAt($value, $offset);
            if ($arrayBody === null) {
                return [
                    'family' => null,
                    'resource_name' => null,
                    'resolved_from_resources' => false,
                    'resource_source' => null,
                ];
            }

            return $this->colorSpaceFamilyReviewAt(
                $arrayBody,
                0,
                $objects,
                $resourceOwnerBody,
                $seenObjects,
                $seenResourceNames
            );
        }

        if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $value, $match, 0, $offset) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            if (isset($seenObjects[$objectNumber])) {
                return [
                    'family' => null,
                    'resource_name' => null,
                    'resolved_from_resources' => false,
                    'resource_source' => null,
                ];
            }

            $objectBody = $this->objectBodyForExactReference($objects, $objectNumber, $generation);
            if ($objectBody === null) {
                return [
                    'family' => null,
                    'resource_name' => null,
                    'resolved_from_resources' => false,
                    'resource_source' => null,
                ];
            }

            $seenObjects[$objectNumber] = true;
            return $this->colorSpaceFamilyReviewAt(
                trim($objectBody),
                0,
                $objects,
                $resourceOwnerBody,
                $seenObjects,
                $seenResourceNames
            );
        }

        return [
            'family' => null,
            'resource_name' => null,
            'resolved_from_resources' => false,
            'resource_source' => null,
        ];
    }

    /**
     * @param array<int, string> $objects
     */
    private function colorSpaceResourceValue(string $resourceOwnerBody, array $objects, string $resourceName): ?string
    {
        $resourceDictionary = $this->resourceDictionaryBody($resourceOwnerBody, $objects) ?? $resourceOwnerBody;
        $colorSpaceDictionary = $this->resourceCategoryDictionaryBody($resourceDictionary, $objects, 'ColorSpace');
        if ($colorSpaceDictionary === null) {
            return null;
        }

        return $this->topLevelPdfValueAfterNameInDictionaryBody($colorSpaceDictionary, $resourceName);
    }

    private function recognizedImageColorSpace(string $name): ?string
    {
        return match ($name) {
            'DeviceGray', 'DeviceRGB', 'DeviceCMYK',
            'G', 'RGB', 'CMYK',
            'Indexed', 'I',
            'ICCBased' => $name,
            default => null,
        };
    }

    /**
     * @return list<int>
     * @param array<int, string> $objects
     */
    private function orderedPageObjectNumbers(array $objects): array
    {
        $catalog = $this->catalogObjectBody($objects);
        if ($catalog !== null) {
            $pagesReference = $this->objectReferenceAfterName($catalog, 'Pages');
            if ($pagesReference === null) {
                return [];
            }

            $pages = $this->pageObjectNumbersFromTree(
                $pagesReference['objectNumber'],
                $pagesReference['generation'],
                $objects
            );
            return array_values(array_unique($pages, SORT_REGULAR));
        }

        if ($this->currentTrailerRootReferenceBlocksFallback) {
            return [];
        }

        $pages = [];
        foreach ($objects as $objectNumber => $body) {
            if ($this->isPageObject($body)) {
                $pages[] = $objectNumber;
            }
        }

        return $pages;
    }

    /**
     * @param array<int, string> $objects
     */
    private function hasCatalogPageTreeReference(array $objects): bool
    {
        foreach ($objects as $body) {
            if ($this->isCatalogObject($body) && $this->objectReferenceAfterName($body, 'Pages') !== null) {
                return true;
            }
        }

        return false;
    }

    /**
     * Native boundary for PDF catalog /PageLabels metadata.
     *
     * @return list<string>
     * @param array<int, string> $objects
     */
    private function pageLabels(array $objects, int $pageCount): array
    {
        if ($pageCount <= 0) {
            return [];
        }

        $fallback = [];
        for ($index = 0; $index < $pageCount; $index++) {
            $fallback[] = (string) ($index + 1);
        }

        $dictionary = $this->pageLabelsDictionaryBody($objects);
        if ($dictionary === null) {
            return $fallback;
        }

        $sections = $this->pageLabelNumberTreeEntries($dictionary, $objects, $pageCount);
        if ($sections === []) {
            return $fallback;
        }

        ksort($sections, SORT_NUMERIC);
        $labels = [];
        $activeSection = ['prefix' => '', 'style' => 'D', 'start' => 1];
        $activeIndex = 0;
        $sectionOffset = 0;
        $sectionIndexes = array_keys($sections);
        $sectionCount = count($sectionIndexes);

        for ($pageIndex = 0; $pageIndex < $pageCount; $pageIndex++) {
            while (
                $sectionOffset < $sectionCount
                && $sectionIndexes[$sectionOffset] <= $pageIndex
            ) {
                $activeIndex = (int) $sectionIndexes[$sectionOffset];
                $activeSection = $sections[$activeIndex];
                $sectionOffset++;
            }

            $number = $activeSection['start'] + ($pageIndex - $activeIndex);
            $label = $activeSection['prefix'];
            if ($activeSection['style'] !== null) {
                $label .= $this->formatPageLabelNumber($number, $activeSection['style']);
            }

            $labels[] = $label !== '' ? $label : (string) ($pageIndex + 1);
        }

        return $labels;
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelsDictionaryBody(array $objects): ?string
    {
        foreach ($objects as $body) {
            if (!$this->isCatalogObject($body)) {
                continue;
            }

            $value = $this->topLevelPdfValueAfterName($body, 'PageLabels');
            if ($value !== null) {
                return $this->pageLabelDictionaryFromValue($value, $objects);
            }
        }

        return null;
    }

    /**
     * @return array<int, array{prefix: string, style: string|null, start: int}>
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     * @param array{0: int, 1: int}|null $inheritedLimits
     */
    private function pageLabelNumberTreeEntries(
        string $dictionary,
        array $objects,
        int $pageCount,
        array $seen = [],
        ?array $inheritedLimits = null
    ): array
    {
        $limits = $inheritedLimits;
        $localLimits = $this->pageLabelLimits($dictionary, $objects);
        if ($localLimits !== null) {
            if ($limits !== null) {
                $lower = max($limits[0], $localLimits[0]);
                $upper = min($limits[1], $localLimits[1]);
                if ($lower > $upper) {
                    return [];
                }
                $limits = [$lower, $upper];
            } else {
                $limits = $localLimits;
            }
        }

        $entries = [];
        if ($this->pageLabelTopLevelValueAfterName($dictionary, 'Nums') !== null) {
            $entries = $this->pageLabelNumsEntries($dictionary, $objects, $limits, $pageCount);
        }

        $kidNodes = [];
        $kidOrder = 0;

        foreach ($this->pageLabelKidObjectReferences($dictionary, $objects) as $kidReference) {
            $kidObjectNumber = $kidReference['objectNumber'];
            $kidGeneration = $kidReference['generation'];
            $kidKey = $kidObjectNumber . ':' . $kidGeneration;
            if (isset($seen[$kidKey])) {
                continue;
            }

            $kidBody = $this->pageLabelObjectBodyForReference($objects, $kidObjectNumber, $kidGeneration);
            if ($kidBody === null) {
                continue;
            }

            $kidDictionary = $this->dictionaryObjectBody($kidBody);
            if ($kidDictionary === null) {
                continue;
            }

            $nextSeen = $seen;
            $nextSeen[$kidKey] = true;
            $kidLocalLimits = $this->pageLabelLimits($kidDictionary, $objects);
            $kidNodes[] = [
                'dictionary' => $kidDictionary,
                'seen' => $nextSeen,
                'limits' => $this->pageLabelMergedLimits($limits, $kidLocalLimits),
                'local_limits' => $kidLocalLimits,
                'order' => $kidOrder++,
            ];
        }

        usort(
            $kidNodes,
            static function (array $left, array $right): int {
                $leftLimits = $left['limits'];
                $rightLimits = $right['limits'];

                return ($leftLimits[0] ?? PHP_INT_MAX) <=> ($rightLimits[0] ?? PHP_INT_MAX)
                    ?: $left['order'] <=> $right['order'];
            }
        );

        $sameLowerKidLimits = [];
        foreach ($kidNodes as $kidNode) {
            $kidLimits = $kidNode['limits'];
            $sameLowerLimits = $kidNode['local_limits'] === null ? null : $kidLimits;
            foreach ($this->pageLabelNumberTreeEntries($kidNode['dictionary'], $objects, $pageCount, $kidNode['seen'], $limits) as $pageIndex => $section) {
                if ($sameLowerLimits !== null) {
                    foreach ($sameLowerKidLimits[$sameLowerLimits[0]] ?? [] as $claimedLimits) {
                        if ($pageIndex >= $claimedLimits[0] && $pageIndex <= $claimedLimits[1]) {
                            continue 2;
                        }
                    }
                }

                if (!array_key_exists($pageIndex, $entries)) {
                    $entries[$pageIndex] = $section;
                }
            }

            if ($sameLowerLimits !== null) {
                $sameLowerKidLimits[$sameLowerLimits[0]][] = $sameLowerLimits;
            }
        }

        return $entries;
    }

    /**
     * @return list<array{objectNumber: int, generation: int}>
     * @param array<int, string> $objects
     */
    private function pageLabelKidObjectReferences(string $dictionary, array $objects): array
    {
        $arrayBody = $this->pageLabelArrayValueAfterNameResolved($dictionary, 'Kids', $objects);
        if ($arrayBody === null) {
            return [];
        }

        $references = [];
        foreach ($this->pdfArrayItems($arrayBody) as $item) {
            $reference = $this->pageLabelReferenceOperand($item);
            if ($reference === null) {
                continue;
            }

            $references[] = [
                'objectNumber' => $reference['objectNumber'],
                'generation' => $reference['generation'],
            ];
        }

        return $references;
    }

    /**
     * @return array<int, array{prefix: string, style: string|null, start: int}>
     * @param array<int, string> $objects
     * @param array{0: int, 1: int}|null $limits
     */
    private function pageLabelNumsEntries(string $dictionary, array $objects, ?array $limits, int $pageCount): array
    {
        $arrayBody = $this->pageLabelArrayValueAfterNameResolved($dictionary, 'Nums', $objects);
        if ($arrayBody === null) {
            return [];
        }

        $entries = [];
        $items = $this->pdfArrayItems($arrayBody);
        $itemCount = count($items);
        $lastAcceptedPageIndex = null;
        for ($index = 0; $index + 1 < $itemCount; $index += 2) {
            $pageIndex = $this->pageLabelPageIndexOperand($items[$index], $objects);
            if ($pageIndex === null) {
                continue;
            }

            $labelDictionary = $this->pageLabelDictionaryFromValue($items[$index + 1], $objects);
            if ($labelDictionary === null) {
                continue;
            }

            if (
                $pageIndex < 0
                || $pageIndex >= $pageCount
                || ($limits !== null && ($pageIndex < $limits[0] || $pageIndex > $limits[1]))
            ) {
                continue;
            }

            if ($lastAcceptedPageIndex !== null && $pageIndex <= $lastAcceptedPageIndex) {
                continue;
            }

            $lastAcceptedPageIndex = $pageIndex;
            if (!array_key_exists($pageIndex, $entries)) {
                $entries[$pageIndex] = $this->parsePageLabelDictionary($labelDictionary, $objects);
            }
        }

        return $entries;
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageLabelPageIndexOperand(string $value, array $objects, array $seen = []): ?int
    {
        $value = trim($value);
        $integer = $this->pageLabelIntegerScalarValue($value);
        if ($integer !== null) {
            return $integer;
        }

        $reference = $this->pageLabelReferenceOperand($value);
        if ($reference === null) {
            return null;
        }

        $objectNumber = $reference['objectNumber'];
        $generation = $reference['generation'];
        $key = $objectNumber . ':' . $generation;
        if ($objectNumber <= 0 || isset($seen[$key])) {
            return null;
        }

        $body = $this->pageLabelObjectBodyForReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return null;
        }

        $seen[$key] = true;
        return $this->pageLabelPageIndexOperand($body, $objects, $seen);
    }

    /**
     * @param array<int, string> $objects
     * @return array{0: int, 1: int}|null
     */
    private function pageLabelLimits(string $dictionary, array $objects): ?array
    {
        $arrayBody = $this->pageLabelArrayValueAfterNameResolved($dictionary, 'Limits', $objects);
        if ($arrayBody === null) {
            return null;
        }

        $items = $this->pdfArrayItems($arrayBody);
        if (count($items) >= 2) {
            $lower = $this->pageLabelLimitOperand($items[0], $objects);
            $upper = $this->pageLabelLimitOperand($items[1], $objects);
            if ($lower === null || $upper === null) {
                return null;
            }

            return $lower <= $upper ? [$lower, $upper] : null;
        }

        return null;
    }

    /**
     * @param array{0: int, 1: int}|null $parentLimits
     * @param array{0: int, 1: int}|null $localLimits
     * @return array{0: int, 1: int}|null
     */
    private function pageLabelMergedLimits(?array $parentLimits, ?array $localLimits): ?array
    {
        if ($parentLimits === null) {
            return $localLimits;
        }
        if ($localLimits === null) {
            return $parentLimits;
        }

        $lower = max($parentLimits[0], $localLimits[0]);
        $upper = min($parentLimits[1], $localLimits[1]);

        return $lower <= $upper ? [$lower, $upper] : null;
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageLabelLimitOperand(string $value, array $objects, array $seen = []): ?int
    {
        $value = trim($value);
        $integer = $this->pageLabelIntegerScalarValue($value);
        if ($integer !== null) {
            return $integer;
        }

        $reference = $this->pageLabelReferenceOperand($value);
        if ($reference === null) {
            return null;
        }

        $objectNumber = $reference['objectNumber'];
        $generation = $reference['generation'];
        $key = $objectNumber . ':' . $generation;
        if ($objectNumber <= 0 || isset($seen[$key])) {
            return null;
        }

        $body = $this->pageLabelObjectBodyForReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return null;
        }

        $seen[$key] = true;
        return $this->pageLabelLimitOperand($body, $objects, $seen);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelDictionaryFromValue(string $value, array $objects): ?string
    {
        return $this->pageLabelDictionaryFromValueResolved($value, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageLabelDictionaryFromValueResolved(string $value, array $objects, array $seen = []): ?string
    {
        $value = trim($value);
        if (str_starts_with($value, '<<')) {
            $offset = 0;
            return $this->readPdfDictionaryTokenAt($value, $offset);
        }

        $reference = $this->pageLabelReferenceOperand($value);
        if ($reference === null) {
            return null;
        }

        $objectNumber = $reference['objectNumber'];
        $generation = $reference['generation'];
        $objectKey = $objectNumber . ':' . $generation;
        if ($objectNumber <= 0 || isset($seen[$objectKey])) {
            return null;
        }

        $body = $this->pageLabelObjectBodyForReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return null;
        }

        $seen[$objectKey] = true;
        return $this->pageLabelDictionaryFromValueResolved($body, $objects, $seen);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelObjectBodyForReference(array $objects, int $objectNumber, int $generation): ?string
    {
        $directExactBody = $this->currentDirectObjectBodiesByGeneration[$objectNumber][$generation] ?? null;
        $owner = $this->currentObjectReferenceOwners[$objectNumber] ?? null;
        if ($owner !== null && isset($objects[$objectNumber]) && $objects[$objectNumber] === $owner['body']) {
            return $owner['generation'] === $generation ? $owner['body'] : $directExactBody;
        }

        return $directExactBody ?? $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
    }

    /**
     * @return array{objectNumber: int, generation: int}|null
     */
    private function pageLabelReferenceOperand(string $value): ?array
    {
        $offset = $this->skipPdfWhitespace($value, 0);
        $reference = $this->pdfIndirectReferenceTokenAt($value, $offset);
        if ($reference === null) {
            return null;
        }

        $endOffset = $this->skipPdfWhitespace($value, $reference['endOffset']);
        if ($endOffset < strlen($value)) {
            return null;
        }

        return [
            'objectNumber' => $reference['objectNumber'],
            'generation' => $reference['generation'],
        ];
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelArrayValueAfterNameResolved(string $body, string $name, array $objects): ?string
    {
        $value = $this->pageLabelTopLevelValueAfterName($body, $name);
        return $value === null ? null : $this->pageLabelArrayFromValue($value, $objects);
    }

    private function pageLabelTopLevelValueAfterName(string $dictionary, string $name): ?string
    {
        $dictionary = trim($dictionary);
        if (str_starts_with($dictionary, '<<')) {
            return $this->topLevelPdfValueAfterName($dictionary, $name);
        }

        return $this->topLevelPdfValueAfterNameInDictionaryBody($dictionary, $name);
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageLabelArrayFromValue(string $value, array $objects, array $seen = []): ?string
    {
        $offset = $this->skipPdfWhitespace($value, 0);
        if (($value[$offset] ?? '') === '[') {
            return $this->readPdfArrayAt($value, $offset);
        }

        $reference = $this->pageLabelReferenceOperand($value);
        if ($reference === null) {
            return null;
        }

        $objectNumber = $reference['objectNumber'];
        $generation = $reference['generation'];
        $objectKey = $objectNumber . ':' . $generation;
        if ($objectNumber <= 0 || isset($seen[$objectKey])) {
            return null;
        }

        $body = $this->pageLabelObjectBodyForReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return null;
        }

        $seen[$objectKey] = true;
        return $this->pageLabelArrayFromValue($body, $objects, $seen);
    }

    /**
     * @return array{prefix: string, style: string|null, start: int}
     */
    private function parsePageLabelDictionary(string $dictionary, array $objects): array
    {
        $candidate = $this->pageLabelNameValueAfterName($dictionary, 'S', $objects);
        $style = in_array($candidate, ['D', 'R', 'r', 'A', 'a'], true) ? $candidate : null;

        $start = 1;
        $startValue = $this->pageLabelIntegerValueAfterName($dictionary, 'St', $objects);
        if ($startValue !== null) {
            $start = max(1, $startValue);
        }

        return [
            'prefix' => $this->pageLabelPrefix($dictionary, $objects),
            'style' => $style,
            'start' => $start,
        ];
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelPrefix(string $dictionary, array $objects): string
    {
        $value = $this->pageLabelTopLevelValueAfterName($dictionary, 'P');
        return $value === null ? '' : $this->pageLabelTextStringValue($value, $objects) ?? '';
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelNameValueAfterName(string $dictionary, string $name, array $objects): ?string
    {
        $value = $this->pageLabelTopLevelValueAfterName($dictionary, $name);
        return $value === null ? null : $this->pageLabelNameValue($value, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageLabelNameValue(string $value, array $objects, array $seen = []): ?string
    {
        $value = trim($value);
        $reference = $this->pageLabelReferenceOperand($value);
        if ($reference !== null) {
            $objectNumber = $reference['objectNumber'];
            $generation = $reference['generation'];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->pageLabelObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->pageLabelNameValue($body, $objects, $seen);
        }

        if (($value[0] ?? '') !== '/') {
            return null;
        }

        $end = 1;
        while ($end < strlen($value) && !str_contains(" \t\r\n\f[]()<>{}/%", $value[$end])) {
            $end++;
        }

        $name = substr($value, 1, $end - 1);
        if ($name === '') {
            return null;
        }

        $afterOffset = $this->skipPdfWhitespace($value, $end);
        if ($afterOffset < strlen($value)) {
            return null;
        }

        return $this->decodePdfName($name);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelIntegerValueAfterName(string $dictionary, string $name, array $objects): ?int
    {
        $value = $this->pageLabelTopLevelValueAfterName($dictionary, $name);
        return $value === null ? null : $this->pageLabelIntegerValue($value, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageLabelIntegerValue(string $value, array $objects, array $seen = []): ?int
    {
        $value = trim($value);
        $integer = $this->pageLabelIntegerScalarValue($value);
        if ($integer !== null) {
            return $integer;
        }

        $reference = $this->pageLabelReferenceOperand($value);
        if ($reference === null) {
            return null;
        }

        $objectNumber = $reference['objectNumber'];
        $generation = $reference['generation'];
        $objectKey = $objectNumber . ':' . $generation;
        if ($objectNumber <= 0 || isset($seen[$objectKey])) {
            return null;
        }

        $body = $this->pageLabelObjectBodyForReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return null;
        }

        $seen[$objectKey] = true;
        return $this->pageLabelIntegerValue($body, $objects, $seen);
    }

    private function pageLabelIntegerScalarValue(string $value): ?int
    {
        $offset = $this->skipPdfWhitespace($value, 0);
        if (preg_match('/\G[+-]?\d+/s', $value, $match, 0, $offset) !== 1) {
            return null;
        }

        $endOffset = $this->skipPdfWhitespace($value, $offset + strlen($match[0]));
        if ($endOffset < strlen($value)) {
            return null;
        }

        return (int) $match[0];
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageLabelTextStringValue(string $value, array $objects, array $seen = []): ?string
    {
        $value = trim($value);
        if ($value === '') {
            return null;
        }

        $reference = $this->pageLabelReferenceOperand($value);
        if ($reference !== null) {
            $objectNumber = $reference['objectNumber'];
            $generation = $reference['generation'];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $objectBody = $this->pageLabelObjectBodyForReference($objects, $objectNumber, $generation);
            if ($objectBody === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->pageLabelTextStringValue($objectBody, $objects, $seen);
        }

        return $this->pageLabelSingleTextStringValue($value, $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageLabelSingleTextStringValue(string $value, array $objects): ?string
    {
        $offset = $this->skipPdfWhitespace($value, 0);
        if ($offset >= strlen($value)) {
            return null;
        }

        $endOffset = $this->skipPdfValueAt($value, $offset);
        if ($endOffset <= $offset) {
            return null;
        }

        $afterOffset = $this->skipPdfWhitespace($value, $endOffset);
        if ($afterOffset < strlen($value)) {
            return null;
        }

        return $this->pdfTextStringValue(substr($value, $offset, $endOffset - $offset), $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pdfTextStringValue(string $value, array $objects, array $seen = []): ?string
    {
        $value = trim($value);
        if ($value === '') {
            return null;
        }

        if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', $value, $match) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $objectBody = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($objectBody === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->pdfTextStringValue($objectBody, $objects, $seen);
        }

        if ($value[0] === '(') {
            $raw = $this->readPdfLiteralStringAt($value, 0);
            return $raw === null ? null : $this->decodePdfTextStringBytes($this->decodeLiteralString($raw));
        }

        if ($value[0] === '<' && substr($value, 0, 2) !== '<<') {
            $bytes = $this->readPdfHexStringAt($value, 0);
            return $bytes === null ? null : $this->decodePdfTextStringBytes($bytes);
        }

        if ($value[0] === '/') {
            $end = strcspn($value, " \t\r\n\f[]()<>{}/%", 1);
            return $this->decodePdfName(substr($value, 1, $end));
        }

        return null;
    }

    private function decodePdfTextStringBytes(string $bytes): string
    {
        $prefix = strtolower(bin2hex(substr($bytes, 0, 2)));
        if ($prefix === 'feff') {
            $decoded = iconv('UTF-16BE', 'UTF-8//IGNORE', substr($bytes, 2));
            return $decoded === false ? '' : $decoded;
        }
        if ($prefix === 'fffe') {
            $decoded = iconv('UTF-16LE', 'UTF-8//IGNORE', substr($bytes, 2));
            return $decoded === false ? '' : $decoded;
        }

        return $this->decodePdfDocEncoding($bytes);
    }

    private function decodePdfDocEncoding(string $bytes): string
    {
        $decoded = '';
        for ($offset = 0, $length = strlen($bytes); $offset < $length; $offset++) {
            $byte = ord($bytes[$offset]);
            $codepoint = self::PDF_DOC_ENCODING_OVERRIDES[$byte] ?? $byte;
            $char = mb_chr($codepoint, 'UTF-8');
            if ($char !== false) {
                $decoded .= $char;
            }
        }

        return $decoded;
    }

    private function formatPageLabelNumber(int $number, string $style): string
    {
        return match ($style) {
            'R' => $this->romanPageLabel($number),
            'r' => strtolower($this->romanPageLabel($number)),
            'A' => $this->alphabeticPageLabel($number, false),
            'a' => $this->alphabeticPageLabel($number, true),
            default => (string) $number,
        };
    }

    private function romanPageLabel(int $number): string
    {
        if ($number <= 0) {
            return (string) $number;
        }

        $roman = '';
        foreach ([1000 => 'M', 900 => 'CM', 500 => 'D', 400 => 'CD', 100 => 'C', 90 => 'XC', 50 => 'L', 40 => 'XL', 10 => 'X', 9 => 'IX', 5 => 'V', 4 => 'IV', 1 => 'I'] as $value => $glyph) {
            while ($number >= $value) {
                $roman .= $glyph;
                $number -= $value;
            }
        }

        return $roman;
    }

    private function alphabeticPageLabel(int $number, bool $lowercase): string
    {
        if ($number <= 0) {
            return (string) $number;
        }

        $letter = chr(ord($lowercase ? 'a' : 'A') + (($number - 1) % 26));
        return str_repeat($letter, intdiv($number - 1, 26) + 1);
    }

    /**
     * @return list<int>
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     */
    private function pageObjectNumbersFromTree(int $objectNumber, int $generation, array $objects, array $seen = []): array
    {
        $referenceKey = $objectNumber . ':' . $generation;
        if (isset($seen[$referenceKey])) {
            return [];
        }

        $body = $this->objectBodyForPageTreeReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return [];
        }

        $seen[$referenceKey] = true;
        if ($this->isPageObject($body)) {
            return [$objectNumber];
        }

        $kids = $this->pageTreeKidObjectReferences($body, $objects);
        if ($kids === []) {
            return [];
        }

        $pages = [];
        foreach ($kids as $childReference) {
            foreach ($this->pageObjectNumbersFromTree(
                $childReference['objectNumber'],
                $childReference['generation'],
                $objects,
                $seen
            ) as $pageObjectNumber) {
                $pages[] = $pageObjectNumber;
            }
        }

        return $pages;
    }

    /**
     * @return list<array{objectNumber: int, generation: int}>
     * @param array<int, string> $objects
     */
    private function pageTreeKidObjectReferences(string $body, array $objects): array
    {
        $value = $this->topLevelPdfValueAfterName($body, 'Kids');
        if ($value === null) {
            return [];
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);

        return $arrayBody === null ? [] : $this->pageTreeKidReferencesFromArray($arrayBody, $objects);
    }

    /**
     * @return list<array{objectNumber: int, generation: int}>
     * @param array<int, string> $objects
     */
    private function pageTreeKidReferencesFromArray(string $arrayBody, array $objects): array
    {
        $references = [];
        foreach ($this->objectReferencePairs($arrayBody) as $reference) {
            if ($this->objectBodyForPageTreeReference($objects, $reference['objectNumber'], $reference['generation']) === null) {
                continue;
            }

            $references[] = $reference;
        }

        return $references;
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageTreeParentListsChild(string $parentBody, int $childObjectNumber, int $childGeneration, array $objects): bool
    {
        $dictionary = $this->dictionaryObjectBody($parentBody);
        if ($dictionary === null) {
            return false;
        }

        $kidsValue = $this->topLevelPdfValueAfterNameInDictionaryBody($dictionary, 'Kids');
        if ($kidsValue === null) {
            return false;
        }

        $kidsArray = $this->pdfArrayFromValue($kidsValue, $objects);
        if ($kidsArray === null) {
            return false;
        }

        foreach ($this->pageTreeKidReferencesFromArray($kidsArray, $objects) as $reference) {
            if ($reference['objectNumber'] === $childObjectNumber && $reference['generation'] === $childGeneration) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array<int, string> $objects
     */
    private function selectedObjectGeneration(array $objects, int $objectNumber): ?int
    {
        if (!isset($objects[$objectNumber])) {
            return null;
        }

        $owner = $this->currentObjectReferenceOwners[$objectNumber] ?? null;
        if ($owner !== null && $objects[$objectNumber] === $owner['body']) {
            return $owner['generation'];
        }

        foreach ($this->currentDirectObjectBodiesByGeneration[$objectNumber] ?? [] as $generation => $body) {
            if ($objects[$objectNumber] === $body) {
                return (int) $generation;
            }
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function objectBodyForPageTreeReference(array $objects, int $objectNumber, int $generation): ?string
    {
        if ($objectNumber <= 0 || $generation < 0 || !isset($objects[$objectNumber])) {
            return null;
        }

        $owner = $this->currentObjectReferenceOwners[$objectNumber] ?? null;
        if ($owner !== null && $objects[$objectNumber] === $owner['body']) {
            return $owner['generation'] === $generation ? $owner['body'] : null;
        }

        $exactBody = $this->currentDirectObjectBodiesByGeneration[$objectNumber][$generation] ?? null;
        return $exactBody !== null && $objects[$objectNumber] === $exactBody ? $exactBody : null;
    }

    private function isCatalogObject(string $body): bool
    {
        return $this->pdfObjectTypeName($body) === 'Catalog';
    }

    private function isPageObject(string $body): bool
    {
        return $this->pdfObjectTypeName($body) === 'Page';
    }

    private function isPagesObject(string $body): bool
    {
        return $this->pdfObjectTypeName($body) === 'Pages';
    }

    private function pdfObjectTypeName(string $body): ?string
    {
        $value = $this->topLevelPdfValueAfterName($body, 'Type');
        if ($value === null) {
            return null;
        }

        $value = trim($value);
        if (preg_match('/^\/([^\s\[\]()<>{}\/%]+)/', $value, $match) !== 1) {
            return null;
        }

        return $this->decodePdfName($match[1]);
    }

    /**
     * @return list<int>
     */
    private function pageContentObjectNumbers(string $pageBody, array $objects): array
    {
        $value = $this->topLevelPdfValueAfterName($pageBody, 'Contents');
        return $value === null ? [] : $this->pageContentObjectNumbersFromValue($value, $objects, []);
    }

    /**
     * @return list<int>
     * @param array<int, string> $objects
     * @param array<int, true> $seenArrayObjects
     */
    private function pageContentObjectNumbersFromValue(string $value, array $objects, array $seenArrayObjects): array
    {
        $value = trim($value);
        if ($value === '') {
            return [];
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);
        if ($arrayBody !== null) {
            return $this->pageContentObjectNumbersFromArrayBody($arrayBody, $objects, $seenArrayObjects);
        }

        if (preg_match('/^(\d+)\s+\d+\s+R\b/s', $value, $match) !== 1) {
            return [];
        }

        $objectNumber = (int) $match[1];
        if (isset($seenArrayObjects[$objectNumber])) {
            return [];
        }

        if (isset($objects[$objectNumber]) && !isset($seenArrayObjects[$objectNumber])) {
            $nestedArray = $this->pdfArrayAtStart(trim($objects[$objectNumber]));
            if ($nestedArray !== null) {
                $seenArrayObjects[$objectNumber] = true;
                return $this->pageContentObjectNumbersFromArrayBody($nestedArray, $objects, $seenArrayObjects);
            }
        }

        return [$objectNumber];
    }

    /**
     * @return list<int>
     * @param array<int, string> $objects
     * @param array<int, true> $seenArrayObjects
     */
    private function pageContentObjectNumbersFromArrayBody(string $arrayBody, array $objects, array $seenArrayObjects): array
    {
        $objectNumbers = [];
        foreach ($this->pdfArrayItems($arrayBody) as $item) {
            $item = trim($item);
            if ($item === '') {
                continue;
            }

            if (str_starts_with($item, '[')) {
                $nestedArray = $this->pdfArrayAtStart($item);
                if ($nestedArray === null) {
                    continue;
                }
                foreach ($this->pageContentObjectNumbersFromArrayBody($nestedArray, $objects, $seenArrayObjects) as $objectNumber) {
                    $objectNumbers[] = $objectNumber;
                }
                continue;
            }

            if (preg_match('/^(\d+)\s+\d+\s+R\b/s', $item, $match) !== 1) {
                continue;
            }

            $objectNumber = (int) $match[1];
            if (isset($seenArrayObjects[$objectNumber])) {
                continue;
            }

            if (isset($objects[$objectNumber]) && !isset($seenArrayObjects[$objectNumber])) {
                $nestedArray = $this->pdfArrayAtStart(trim($objects[$objectNumber]));
                if ($nestedArray !== null) {
                    $nextSeenArrayObjects = $seenArrayObjects;
                    $nextSeenArrayObjects[$objectNumber] = true;
                    foreach ($this->pageContentObjectNumbersFromArrayBody($nestedArray, $objects, $nextSeenArrayObjects) as $nestedObjectNumber) {
                        $objectNumbers[] = $nestedObjectNumber;
                    }
                    continue;
                }
            }

            $objectNumbers[] = $objectNumber;
        }

        return $objectNumbers;
    }

    /**
     * @return list<int>
     */
    private function objectReferences(string $value): array
    {
        $objectNumbers = [];
        $index = 0;
        $length = strlen($value);

        while ($index < $length) {
            $char = $value[$index];

            if (ctype_space($char)) {
                $index++;
                continue;
            }

            if ($char === '%') {
                $this->skipPdfComment($value, $index);
                continue;
            }

            if ($char === '(') {
                $skipped = $this->skipPdfLiteralStringAt($value, $index);
                $index = $skipped === null ? $index + 1 : $skipped + 1;
                continue;
            }

            if ($char === '<') {
                if (($value[$index + 1] ?? '') === '<') {
                    $index += 2;
                    continue;
                }

                $this->readHexToken($value, $index);
                continue;
            }

            if ($char === '>' && ($value[$index + 1] ?? '') === '>') {
                $index += 2;
                continue;
            }

            if ($char === '/') {
                $this->readNameToken($value, $index);
                continue;
            }

            if (preg_match('/\G(\d+)\s+\d+\s+R\b/s', $value, $match, 0, $index) === 1) {
                $objectNumbers[] = (int) $match[1];
                $index += strlen($match[0]);
                continue;
            }

            $index++;
        }

        return $objectNumbers;
    }

    /**
     * @return list<array{objectNumber: int, generation: int}>
     */
    private function objectReferencePairs(string $value): array
    {
        $references = [];
        $index = 0;
        $length = strlen($value);

        while ($index < $length) {
            $char = $value[$index];

            if (ctype_space($char)) {
                $index++;
                continue;
            }

            if ($char === '%') {
                $this->skipPdfComment($value, $index);
                continue;
            }

            if ($char === '(') {
                $skipped = $this->skipPdfLiteralStringAt($value, $index);
                $index = $skipped === null ? $index + 1 : $skipped + 1;
                continue;
            }

            if ($char === '<') {
                if (($value[$index + 1] ?? '') === '<') {
                    $index += 2;
                    continue;
                }

                $this->readHexToken($value, $index);
                continue;
            }

            if ($char === '>' && ($value[$index + 1] ?? '') === '>') {
                $index += 2;
                continue;
            }

            if ($char === '/') {
                $this->readNameToken($value, $index);
                continue;
            }

            if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $value, $match, 0, $index) === 1) {
                $references[] = [
                    'objectNumber' => (int) $match[1],
                    'generation' => (int) $match[2],
                ];
                $index += strlen($match[0]);
                continue;
            }

            $index++;
        }

        return $references;
    }

    /**
     * @param array<int, string> $objects
     */
    private function decodeStreamObject(
        string $objectBody,
        array $objects,
        bool $ignoreNullFilterDecodeParms = false,
        bool $requireBoundedFilterEndMarkers = false
    ): ?string
    {
        $entry = $this->streamDictionaryAndPayload($objectBody, $objects);
        if ($entry === null) {
            return null;
        }

        if ($this->isImageStreamDictionary($entry['dict'], $objects)) {
            return null;
        }

        return $this->decodeStream(
            $entry['dict'],
            $entry['stream'],
            $objects,
            false,
            $ignoreNullFilterDecodeParms,
            $requireBoundedFilterEndMarkers
        );
    }

    /**
     * @param array<int, string> $objects
     * @return array{dict: string, stream: string}|null
     */
    private function streamDictionaryAndPayload(string $value, array $objects): ?array
    {
        $entry = $this->streamDictionaryAndPayloadWithOffsets($value, $objects);
        if ($entry === null) {
            return null;
        }

        return [
            'dict' => $entry['dict'],
            'stream' => $entry['stream'],
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return array{dict: string, stream: string, streamStart: int, streamEnd: int}|null
     */
    private function streamDictionaryAndPayloadWithOffsets(string $value, array $objects): ?array
    {
        $dictionaryOffset = $this->skipPdfWhitespace($value, 0);
        $dictionaryEndOffset = $dictionaryOffset;
        $dict = $this->readPdfDictionaryTokenAt($value, $dictionaryEndOffset);
        if ($dict === null) {
            return null;
        }

        $streamKeywordOffset = $this->skipPdfWhitespace($value, $dictionaryEndOffset);
        if (!$this->pdfKeywordAt($value, $streamKeywordOffset, 'stream')) {
            return null;
        }

        $streamStart = $streamKeywordOffset + strlen('stream');
        if (substr($value, $streamStart, 2) === "\r\n") {
            $streamStart += 2;
        } elseif (($value[$streamStart] ?? '') === "\n" || ($value[$streamStart] ?? '') === "\r") {
            $streamStart++;
        }

        $stream = $this->streamPayloadAt($value, $streamStart, $dict, $objects);
        if ($stream === null) {
            return null;
        }

        return [
            'dict' => $dict,
            'stream' => $stream,
            'streamStart' => $streamStart,
            'streamEnd' => $streamStart + strlen($stream),
        ];
    }

    /**
     * @param array<int, string> $objects
     */
    private function streamPayloadAt(string $value, int $streamStart, string $dict, array $objects): ?string
    {
        $length = $this->streamLength($dict, $objects);
        if ($length !== null) {
            $declaredEnd = $streamStart + $length;
            if ($length >= 0 && $declaredEnd <= strlen($value)) {
                $declaredTerminator = $this->streamLengthTerminatorOffset($value, $declaredEnd);
                if ($declaredTerminator !== null) {
                    $dctJpegTerminator = $this->dctStreamEndstreamTerminatorOffset(
                        $value,
                        $streamStart,
                        $dict,
                        $objects,
                        $declaredTerminator + 1
                    );
                    if ($dctJpegTerminator !== null && $dctJpegTerminator >= $declaredTerminator) {
                        return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $dctJpegTerminator - $streamStart));
                    }
                    $ccittFaxTerminator = $this->ccittFaxStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects);
                    if ($ccittFaxTerminator !== null && $ccittFaxTerminator >= $declaredTerminator) {
                        return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $ccittFaxTerminator - $streamStart));
                    }

                    $recoveredTerminator = $this->startxrefRecoveredStreamTerminatorOffset(
                        $value,
                        $streamStart,
                        $dict,
                        $objects,
                        $declaredTerminator
                    );
                    if ($recoveredTerminator !== null) {
                        return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $recoveredTerminator - $streamStart));
                    }

                    $filterStackRecoveredTerminator = $this->filterStackRecoveredStreamTerminatorOffset(
                        $value,
                        $streamStart,
                        $dict,
                        $objects,
                        $declaredTerminator
                    );
                    if ($filterStackRecoveredTerminator !== null) {
                        return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $filterStackRecoveredTerminator - $streamStart));
                    }

                    return substr($value, $streamStart, $length);
                }

                $dctJpegTerminator = $this->dctStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects, $declaredEnd + 1);
                if ($dctJpegTerminator !== null) {
                    return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $dctJpegTerminator - $streamStart));
                }
                $overdeclaredDctJpegTerminator = $this->dctStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects);
                if ($overdeclaredDctJpegTerminator !== null && $overdeclaredDctJpegTerminator < $declaredEnd) {
                    return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $overdeclaredDctJpegTerminator - $streamStart));
                }
                $ccittFaxTerminator = $this->ccittFaxStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects);
                if ($ccittFaxTerminator !== null) {
                    return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $ccittFaxTerminator - $streamStart));
                }

                $end = $this->filteredEndstreamTerminatorOffset($value, $streamStart, $dict, $objects, $declaredEnd)
                    ?? $this->contentStreamEndstreamTerminatorOffset($value, $streamStart, $dict)
                    ?? $this->endstreamTerminatorOffset($value, $streamStart, $declaredEnd);
                if ($end === null) {
                    return substr($value, $streamStart, $length);
                }

                return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $end - $streamStart));
            }

            $dctJpegTerminator = $this->dctStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects);
            if ($dctJpegTerminator !== null) {
                return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $dctJpegTerminator - $streamStart));
            }
            $ccittFaxTerminator = $this->ccittFaxStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects);
            if ($ccittFaxTerminator !== null) {
                return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $ccittFaxTerminator - $streamStart));
            }

            $end = $this->contentStreamEndstreamTerminatorOffset($value, $streamStart, $dict)
                ?? $this->endstreamTerminatorOffset($value, $streamStart, null);
            if ($end === null) {
                return null;
            }

            return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $end - $streamStart));
        }

        $end = $this->contentStreamEndstreamTerminatorOffset($value, $streamStart, $dict)
            ?? $this->endstreamTerminatorOffset($value, $streamStart, null);
        $end = $this->dctStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects) ?? $end;
        $end = $this->ccittFaxStreamEndstreamTerminatorOffset($value, $streamStart, $dict, $objects) ?? $end;
        $end = $this->filteredEndstreamTerminatorOffset($value, $streamStart, $dict, $objects) ?? $end;
        if ($end === null) {
            return null;
        }

        return $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $end - $streamStart));
    }

    /**
     * @param array<int, string> $objects
     */
    private function streamLength(string $dict, array $objects): ?int
    {
        $offset = $this->topLevelNameValueOffset($dict, 'Length');
        if ($offset === null) {
            return null;
        }

        return $this->streamLengthValueAt($dict, $offset, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, true> $seen
     */
    private function streamLengthValueAt(string $value, int $offset, array $objects, array $seen = []): ?int
    {
        $offset = $this->skipPdfWhitespace($value, $offset);
        if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $value, $match, 0, $offset) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->streamLengthValueAt(trim($body), 0, $objects, $seen);
        }

        if (preg_match('/\G([+-]?\d+)/s', $value, $match, 0, $offset) === 1) {
            $length = (int) $match[1];
            return $length < 0 ? null : $length;
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function decodeStreamForTerminatorRecovery(
        string $dict,
        string $stream,
        array $objects,
        bool $requireExplicitFilterEndMarkers = false
    ): ?string {
        $decoded = $this->decodeStream($dict, $stream, $objects, $requireExplicitFilterEndMarkers);
        if ($decoded !== null) {
            return $decoded;
        }

        return $this->decodeStream($dict, $stream, $objects, $requireExplicitFilterEndMarkers, true);
    }

    /**
     * @param array<int, string> $objects
     */
    private function startxrefRecoveredStreamTerminatorOffset(
        string $value,
        int $streamStart,
        string $dict,
        array $objects,
        int $declaredTerminator
    ): ?int {
        $filteredTerminator = $this->filteredEndstreamTerminatorOffset($value, $streamStart, $dict, $objects);
        if (
            $filteredTerminator !== null
            && $filteredTerminator > $declaredTerminator
            && $this->streamTerminatorGapContainsStartxref($value, $declaredTerminator, $filteredTerminator)
        ) {
            return $filteredTerminator;
        }

        $contentTerminator = $this->contentStreamEndstreamTerminatorOffset($value, $streamStart, $dict);
        if (
            $contentTerminator !== null
            && $contentTerminator > $declaredTerminator
            && $this->streamTerminatorGapContainsStartxref($value, $declaredTerminator, $contentTerminator)
        ) {
            return $contentTerminator;
        }

        return null;
    }

    private function streamTerminatorGapContainsStartxref(
        string $value,
        int $declaredTerminator,
        int $recoveredTerminator
    ): bool {
        if ($recoveredTerminator <= $declaredTerminator) {
            return false;
        }

        $gapStart = $declaredTerminator + strlen('endstream');
        if ($gapStart >= $recoveredTerminator) {
            return false;
        }

        return preg_match('/\bstartxref\s+\d+\b/s', substr($value, $gapStart, $recoveredTerminator - $gapStart)) === 1;
    }

    /**
     * @param array<int, string> $objects
     */
    private function filterStackRecoveredStreamTerminatorOffset(
        string $value,
        int $streamStart,
        string $dict,
        array $objects,
        int $declaredTerminator
    ): ?int {
        $filters = $this->streamFilters($dict, $objects);
        if ($filters === null || !$this->hasVerifiableStreamFilter($filters)) {
            return null;
        }

        $declaredPayload = $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $declaredTerminator - $streamStart));
        if ($this->decodeStreamForTerminatorRecovery($dict, $declaredPayload, $objects, true) !== null) {
            return null;
        }

        $filteredTerminator = $this->filteredEndstreamTerminatorOffset($value, $streamStart, $dict, $objects);
        return $filteredTerminator !== null && $filteredTerminator > $declaredTerminator
            ? $filteredTerminator
            : null;
    }

    private function streamLengthTerminatorOffset(string $value, int $declaredEnd): ?int
    {
        $offset = $declaredEnd;
        if (substr($value, $offset, 2) === "\r\n") {
            $offset += 2;
        } elseif (($value[$offset] ?? '') === "\n" || ($value[$offset] ?? '') === "\r") {
            $offset++;
        }

        return $this->endstreamKeywordAt($value, $offset) ? $offset : null;
    }

    private function endstreamTerminatorOffset(string $value, int $streamStart, ?int $declaredEnd): ?int
    {
        $fallback = null;
        $beforeDeclaredEnd = null;
        $offset = $streamStart;
        while (($candidate = strpos($value, 'endstream', $offset)) !== false) {
            $fallback ??= $candidate;
            $offset = $candidate + 9;

            if (!$this->endstreamTerminatorAt($value, $candidate, $streamStart)) {
                continue;
            }

            if ($declaredEnd === null) {
                return $candidate;
            }

            if ($candidate >= $declaredEnd) {
                return $candidate;
            }

            $beforeDeclaredEnd = $candidate;
        }

        return $beforeDeclaredEnd ?? $fallback;
    }

    private function endstreamTerminatorAt(string $value, int $offset, int $streamStart): bool
    {
        if (!$this->endstreamKeywordAt($value, $offset)) {
            return false;
        }

        if ($offset <= $streamStart) {
            return true;
        }

        $previous = $value[$offset - 1] ?? '';
        return $previous === "\n" || $previous === "\r";
    }

    private function endstreamKeywordAt(string $value, int $offset): bool
    {
        if (substr($value, $offset, 9) !== 'endstream') {
            return false;
        }

        $after = $offset + 9;
        return $after >= strlen($value) || ctype_space($value[$after]);
    }

    /**
     * @param array<int, string> $objects
     */
    private function filteredEndstreamTerminatorOffset(
        string $value,
        int $streamStart,
        string $dict,
        array $objects,
        ?int $minimumOffset = null
    ): ?int
    {
        $filters = $this->streamFilters($dict, $objects);
        if ($filters === null || !$this->hasVerifiableStreamFilter($filters)) {
            return null;
        }

        $offset = $streamStart;
        while (($candidate = strpos($value, 'endstream', $offset)) !== false) {
            $offset = $candidate + 9;
            if (!$this->endstreamTerminatorAt($value, $candidate, $streamStart)) {
                continue;
            }

            if ($minimumOffset !== null && $candidate < $minimumOffset) {
                continue;
            }

            $payload = $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $candidate - $streamStart));
            if ($this->decodeStreamForTerminatorRecovery($dict, $payload, $objects, true) !== null) {
                return $candidate;
            }
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function dctStreamEndstreamTerminatorOffset(
        string $value,
        int $streamStart,
        string $dict,
        array $objects,
        ?int $minimumTerminatorOffset = null
    ): ?int
    {
        $filters = $this->streamFilters($dict, $objects);
        if ($filters === null || $filters === []) {
            if (!$this->isImageStreamDictionary($dict, $objects)) {
                return null;
            }

            return $this->rawDctPreviewEndstreamTerminatorOffset($value, $streamStart, $minimumTerminatorOffset);
        }

        $firstFilter = null;
        $firstFilterIndex = null;
        foreach ($filters as $index => $filter) {
            if ($filter !== null) {
                $firstFilter = $filter;
                $firstFilterIndex = $index;
                break;
            }
        }

        if ($firstFilter === null || $firstFilterIndex === null) {
            return null;
        }

        if ($firstFilter !== 'DCTDecode' && $firstFilter !== 'DCT') {
            return $this->dctPrefixFilterEndstreamTerminatorOffset(
                $value,
                $streamStart,
                $firstFilter,
                $filters,
                $firstFilterIndex,
                $dict,
                $objects,
                $minimumTerminatorOffset
            );
        }

        return $this->rawDctPreviewEndstreamTerminatorOffset($value, $streamStart, $minimumTerminatorOffset);
    }

    private function rawDctPreviewEndstreamTerminatorOffset(
        string $value,
        int $streamStart,
        ?int $minimumTerminatorOffset = null
    ): ?int
    {
        $jpegStart = $streamStart;
        $length = strlen($value);
        while ($jpegStart < $length && str_contains("\x00\t\n\f\r ", $value[$jpegStart])) {
            $jpegStart++;
        }

        if (substr($value, $jpegStart, 2) !== "\xff\xd8") {
            return null;
        }

        $lastCompleteTerminator = null;
        foreach ($this->dctPreviewEoiEndOffsets($value, $jpegStart) as $eoiEnd) {
            $terminator = $this->skipDctPreviewPadding($value, $eoiEnd);
            if ($minimumTerminatorOffset !== null && $terminator < $minimumTerminatorOffset) {
                continue;
            }

            if ($this->endstreamKeywordAt($value, $terminator)) {
                $lastCompleteTerminator = $terminator;
            }
        }

        return $lastCompleteTerminator;
    }

    private function skipDctPreviewPadding(string $value, int $offset): int
    {
        $length = strlen($value);
        while ($offset < $length && str_contains("\x00\t\n\f\r ", $value[$offset])) {
            $offset++;
        }

        return $offset;
    }

    /**
     * @param list<string|null> $filters
     */
    private function dctPrefixFilterEndstreamTerminatorOffset(
        string $value,
        int $streamStart,
        string $firstFilter,
        array $filters,
        int $firstFilterIndex,
        string $dict,
        array $objects,
        ?int $minimumTerminatorOffset = null
    ): ?int {
        $dctFilterIndex = null;
        for ($index = $firstFilterIndex + 1; $index < count($filters); $index++) {
            $filter = $filters[$index];
            if ($filter === 'DCTDecode' || $filter === 'DCT') {
                $dctFilterIndex = $index;
                break;
            }
        }

        if ($dctFilterIndex === null) {
            return null;
        }

        $payloadMarker = match ($firstFilter) {
            'ASCIIHexDecode', 'AHx' => '>',
            'ASCII85Decode', 'A85' => '~>',
            'RunLengthDecode', 'RL' => chr(128),
            default => null,
        };
        $applyMinimumTerminatorOffset = $this->dctPrefixFilterCanUseRawJpegBoundaryFallback($firstFilter);

        $fallbackTerminator = null;
        if ($payloadMarker !== null) {
            foreach ($this->firstFilterEndstreamTerminatorOffsets($value, $streamStart, $payloadMarker) as $terminator) {
                if ($applyMinimumTerminatorOffset && $minimumTerminatorOffset !== null && $terminator < $minimumTerminatorOffset) {
                    continue;
                }

                $payload = $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $terminator - $streamStart));
                $jpegBytes = $this->decodeStreamBeforeFilter($dict, $payload, $objects, $filters, $dctFilterIndex, true);
                if ($jpegBytes !== null && $this->dctPreviewBytesAreCompleteJpeg($jpegBytes)) {
                    return $terminator;
                }

                $fallbackTerminator = $terminator;
            }
        }

        $offset = $streamStart;
        while (($candidate = strpos($value, 'endstream', $offset)) !== false) {
            $offset = $candidate + strlen('endstream');
            if (!$this->endstreamTerminatorAt($value, $candidate, $streamStart)) {
                continue;
            }

            if ($applyMinimumTerminatorOffset && $minimumTerminatorOffset !== null && $candidate < $minimumTerminatorOffset) {
                continue;
            }

            $payload = $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $candidate - $streamStart));
            $jpegBytes = $this->decodeStreamBeforeFilter($dict, $payload, $objects, $filters, $dctFilterIndex, true);
            if ($jpegBytes !== null && $this->dctPreviewBytesAreCompleteJpeg($jpegBytes)) {
                return $candidate;
            }
        }

        if ($fallbackTerminator !== null) {
            return $fallbackTerminator;
        }

        if ($this->dctPrefixFilterCanUseRawJpegBoundaryFallback($firstFilter)) {
            return $this->rawDctPreviewEndstreamTerminatorOffset($value, $streamStart, $minimumTerminatorOffset);
        }

        return null;
    }

    private function dctPrefixFilterCanUseRawJpegBoundaryFallback(string $firstFilter): bool
    {
        return !in_array($firstFilter, [
            'ASCIIHexDecode',
            'AHx',
            'ASCII85Decode',
            'A85',
            'RunLengthDecode',
            'RL',
            'LZWDecode',
            'LZW',
            'FlateDecode',
            'Fl',
        ], true);
    }

    /**
     * CCITTFaxDecode is preview-only here, but earlier filters in the stack are
     * still native and can prove where the encoded fax payload ends.
     *
     * @param array<int, string> $objects
     */
    private function ccittFaxStreamEndstreamTerminatorOffset(string $value, int $streamStart, string $dict, array $objects): ?int
    {
        $filters = $this->streamFilters($dict, $objects);
        if ($filters === null || $filters === []) {
            return null;
        }

        $firstFilter = null;
        $firstFilterIndex = null;
        foreach ($filters as $index => $filter) {
            if ($filter !== null) {
                $firstFilter = $filter;
                $firstFilterIndex = $index;
                break;
            }
        }

        if ($firstFilter === null || $firstFilterIndex === null) {
            return null;
        }

        $ccittFilterIndex = null;
        for ($index = $firstFilterIndex; $index < count($filters); $index++) {
            $filter = $filters[$index];
            if ($filter === 'CCITTFaxDecode' || $filter === 'CCF') {
                $ccittFilterIndex = $index;
                break;
            }
        }

        if ($ccittFilterIndex === null) {
            return null;
        }

        if ($ccittFilterIndex === $firstFilterIndex) {
            return $this->directCcittFaxEndstreamTerminatorOffset(
                $value,
                $streamStart,
                $dict,
                $objects,
                $filters,
                $ccittFilterIndex
            );
        }

        $payloadEnd = match ($firstFilter) {
            'ASCIIHexDecode', 'AHx' => $this->firstFilterEndMarkerOffset($value, $streamStart, '>'),
            'ASCII85Decode', 'A85' => $this->firstFilterEndMarkerOffset($value, $streamStart, '~>'),
            'RunLengthDecode', 'RL' => $this->firstFilterEndMarkerOffset($value, $streamStart, chr(128)),
            default => null,
        };

        if ($payloadEnd !== null) {
            $terminator = $this->skipPdfWhitespace($value, $payloadEnd);
            if ($this->endstreamKeywordAt($value, $terminator)) {
                return $terminator;
            }
        }

        $offset = $streamStart;
        while (($candidate = strpos($value, 'endstream', $offset)) !== false) {
            $offset = $candidate + strlen('endstream');
            if (!$this->endstreamTerminatorAt($value, $candidate, $streamStart)) {
                continue;
            }

            $payload = $this->stripStreamTerminatingLineEnding(substr($value, $streamStart, $candidate - $streamStart));
            $faxBytes = $this->decodeStreamBeforeFilter($dict, $payload, $objects, $filters, $ccittFilterIndex);
            if (
                $faxBytes !== null
                && $faxBytes !== ''
                && $this->ccittFaxDecodedBytesReachBoundary($faxBytes, $dict, $objects, $filters, $ccittFilterIndex)
            ) {
                return $candidate;
            }
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     * @param list<string|null> $filters
     */
    private function directCcittFaxEndstreamTerminatorOffset(
        string $value,
        int $streamStart,
        string $dict,
        array $objects,
        array $filters,
        int $ccittFilterIndex
    ): ?int {
        $decodeParms = $this->streamDecodeParms($dict, $objects);
        if ($decodeParms === null) {
            return null;
        }

        $filterDecodeParms = $this->decodeParmsForFilterIndex($filters, $decodeParms, $ccittFilterIndex);
        $markers = $this->ccittFaxEndOfBlockMarkersForOwnership($filterDecodeParms, $objects);
        if ($markers === []) {
            return null;
        }

        foreach ($markers as $marker) {
            $offset = $streamStart;
            while (($markerOffset = strpos($value, $marker, $offset)) !== false) {
                $afterMarker = $markerOffset + strlen($marker);
                $terminator = $this->skipPdfWhitespace($value, $afterMarker);
                if ($this->endstreamKeywordAt($value, $terminator)) {
                    return $terminator;
                }

                $offset = $markerOffset + 1;
            }
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function ccittFaxDecodeParmsUsesEndOfBlock(?string $decodeParms, array $objects): bool
    {
        if ($decodeParms === null || trim($decodeParms) === '') {
            return true;
        }

        if ($this->decodeParmsHasName($decodeParms, 'EndOfBlock')) {
            $endOfBlock = $this->decodeParmsBool($decodeParms, 'EndOfBlock', $objects);
            if ($endOfBlock === null) {
                return false;
            }

            if (!$endOfBlock) {
                return false;
            }
        }

        if ($this->decodeParmsHasName($decodeParms, 'K') && $this->decodeParmsInt($decodeParms, 'K', $objects) === null) {
            return false;
        }

        return true;
    }

    /**
     * @param array<int, string> $objects
     * @param list<string|null> $filters
     */
    private function ccittFaxDecodedBytesReachBoundary(
        string $faxBytes,
        string $dict,
        array $objects,
        array $filters,
        int $ccittFilterIndex
    ): bool {
        $decodeParms = $this->streamDecodeParms($dict, $objects);
        $filterDecodeParms = $decodeParms === null
            ? null
            : $this->decodeParmsForFilterIndex($filters, $decodeParms, $ccittFilterIndex);

        $markers = $this->ccittFaxEndOfBlockMarkersForOwnership($filterDecodeParms, $objects);
        if ($markers === []) {
            return true;
        }

        $bytes = rtrim($faxBytes, "\x00\t\n\f\r ");
        foreach ($markers as $marker) {
            if (str_ends_with($bytes, $marker)) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array<int, string> $objects
     * @return list<string>
     */
    private function ccittFaxEndOfBlockMarkers(?string $decodeParms, array $objects): array
    {
        $k = $this->decodeParmsInt($decodeParms, 'K', $objects) ?? 0;
        $eolPair = "\x00\x10\x01";

        if ($k < 0) {
            return [$eolPair];
        }

        return [$eolPair . $eolPair . $eolPair];
    }

    /**
     * @param array<int, string> $objects
     * @return list<string>
     */
    private function ccittFaxEndOfBlockMarkersForOwnership(?string $decodeParms, array $objects): array
    {
        if ($decodeParms !== null && $this->decodeParmsHasName($decodeParms, 'EndOfBlock')) {
            $endOfBlock = $this->decodeParmsBool($decodeParms, 'EndOfBlock', $objects);
            if ($endOfBlock === false) {
                return $this->ccittFaxEndOfLineMarkersForOwnership($decodeParms, $objects);
            }
        }

        if ($this->ccittFaxDecodeParmsUsesEndOfBlock($decodeParms, $objects)) {
            return $this->ccittFaxEndOfBlockMarkers($decodeParms, $objects);
        }

        $eolPair = "\x00\x10\x01";
        return [$eolPair, $eolPair . $eolPair . $eolPair];
    }

    /**
     * @param array<int, string> $objects
     * @return list<string>
     */
    private function ccittFaxEndOfLineMarkersForOwnership(?string $decodeParms, array $objects): array
    {
        if ($decodeParms === null || !$this->decodeParmsHasName($decodeParms, 'EndOfLine')) {
            return [];
        }

        $endOfLine = $this->decodeParmsBool($decodeParms, 'EndOfLine', $objects);
        if ($endOfLine !== true) {
            return [];
        }

        $k = $this->decodeParmsInt($decodeParms, 'K', $objects) ?? 0;
        if ($k < 0) {
            return [];
        }

        if ($this->decodeParmsHasName($decodeParms, 'Rows')) {
            $rows = $this->decodeParmsInt($decodeParms, 'Rows', $objects);
            if ($rows === null || $rows <= 0) {
                return [];
            }
        }

        return ["\x00\x10\x01"];
    }

    private function firstFilterEndMarkerOffset(string $value, int $streamStart, string $marker): ?int
    {
        $offset = strpos($value, $marker, $streamStart);
        return $offset === false ? null : $offset + strlen($marker);
    }

    /**
     * @return list<int>
     */
    private function firstFilterEndstreamTerminatorOffsets(string $value, int $streamStart, string $marker): array
    {
        $terminators = [];
        $offset = $streamStart;
        while (($markerOffset = strpos($value, $marker, $offset)) !== false) {
            $payloadEnd = $markerOffset + strlen($marker);
            $terminator = $this->skipPdfWhitespace($value, $payloadEnd);
            if ($this->endstreamKeywordAt($value, $terminator)) {
                $terminators[] = $terminator;
            }

            $offset = $markerOffset + 1;
        }

        return $terminators;
    }

    /**
     * @param array<int, string> $objects
     * @param list<string|null> $filters
     */
    private function decodeStreamBeforeFilter(
        string $dict,
        string $stream,
        array $objects,
        array $filters,
        int $stopBeforeIndex,
        bool $ignoreNullFilterDecodeParms = false
    ): ?string {
        $decodeParms = $ignoreNullFilterDecodeParms
            ? $this->streamDecodeParmsForFilters($dict, $objects, $filters)
            : $this->streamDecodeParms($dict, $objects);
        if ($decodeParms === null) {
            return null;
        }

        for ($index = 0; $index < $stopBeforeIndex; $index++) {
            $filter = $filters[$index] ?? null;
            if ($filter === null) {
                continue;
            }

            $filterDecodeParms = $this->decodeParmsForFilterIndex($filters, $decodeParms, $index);
            if (!$this->canApplyDecodeParms($filter, $filterDecodeParms, $objects)) {
                return null;
            }

            if (!$this->streamFilterInputHasExplicitEndMarker($filter, $stream)) {
                return null;
            }

            $decoded = match ($filter) {
                'ASCIIHexDecode', 'AHx' => $this->decodeAsciiHexStream($stream),
                'ASCII85Decode', 'A85' => $this->decodeAscii85Stream($stream),
                'RunLengthDecode', 'RL' => $this->decodeRunLengthStream($stream),
                'LZWDecode', 'LZW' => $this->decodeLzwStream($stream, $filterDecodeParms, $objects),
                'FlateDecode', 'Fl' => $this->decodeFlateStream($stream, $filterDecodeParms, $objects),
                'Crypt' => $this->decodeCryptIdentityStream($stream, $filterDecodeParms, $objects),
                default => null,
            };

            if ($decoded === null) {
                return null;
            }

            $stream = $decoded;
        }

        return $stream;
    }

    private function dctPreviewBytesAreCompleteJpeg(string $bytes): bool
    {
        $length = strlen($bytes);
        $start = 0;
        while ($start < $length && str_contains("\x00\t\n\f\r ", $bytes[$start])) {
            $start++;
        }

        if (substr($bytes, $start, 2) !== "\xff\xd8") {
            return false;
        }

        foreach ($this->dctPreviewEoiEndOffsets($bytes, $start) as $eoiEnd) {
            if ($this->skipDctPreviewPadding($bytes, $eoiEnd) === $length) {
                return true;
            }
        }

        return false;
    }

    /**
     * @return list<int>
     */
    private function dctPreviewEoiEndOffsets(string $bytes, int $startOffset = 0, ?int $limitOffset = null): array
    {
        $limit = min($limitOffset ?? strlen($bytes), strlen($bytes));
        $start = $startOffset;
        while ($start < $limit && str_contains("\x00\t\n\f\r ", $bytes[$start])) {
            $start++;
        }

        if ($start + 2 > $limit || substr($bytes, $start, 2) !== "\xff\xd8") {
            return [];
        }

        $offset = $start + 2;
        while ($offset < $limit) {
            $markerStart = strpos($bytes, "\xff", $offset);
            if ($markerStart === false || $markerStart + 1 >= $limit) {
                return [];
            }

            $markerOffset = $markerStart + 1;
            while ($markerOffset < $limit && $bytes[$markerOffset] === "\xff") {
                $markerOffset++;
            }
            if ($markerOffset >= $limit) {
                return [];
            }

            $marker = ord($bytes[$markerOffset]);
            if ($marker === 0x00) {
                $offset = $markerOffset + 1;
                continue;
            }
            if ($marker === 0xd9) {
                return [$markerOffset + 1];
            }
            if ($marker === 0xd8 || $marker === 0x01 || ($marker >= 0xd0 && $marker <= 0xd7)) {
                $offset = $markerOffset + 1;
                continue;
            }

            $lengthOffset = $markerOffset + 1;
            if ($lengthOffset + 2 > $limit) {
                return [];
            }

            $segmentLength = (ord($bytes[$lengthOffset]) << 8) | ord($bytes[$lengthOffset + 1]);
            if ($segmentLength < 2) {
                return $this->dctPreviewLenientEoiEndOffsets($bytes, $markerOffset + 1, $limit);
            }

            $segmentEnd = $lengthOffset + 2 + ($segmentLength - 2);
            if ($segmentEnd > $limit) {
                if (ord($bytes[$lengthOffset]) <= 0x0f) {
                    return [];
                }

                return $this->dctPreviewLenientEoiEndOffsets($bytes, $markerOffset + 1, $limit);
            }

            $offset = $segmentEnd;
        }

        return [];
    }

    /**
     * @return list<int>
     */
    private function dctPreviewLenientEoiEndOffsets(string $bytes, int $offset, int $limit): array
    {
        $bounded = substr($bytes, 0, $limit);
        $offsets = [];
        while (($eoi = strpos($bounded, "\xff\xd9", $offset)) !== false) {
            $offsets[] = $eoi + 2;
            $offset = $eoi + 2;
        }

        return $offsets;
    }

    private function contentStreamEndstreamTerminatorOffset(string $value, int $streamStart, string $dict): ?int
    {
        if (!$this->canScanContentStreamForInlineImages($dict)) {
            return null;
        }

        $index = $streamStart;
        $length = strlen($value);
        while ($index < $length) {
            $char = $value[$index];
            if (ctype_space($char)) {
                $index++;
                continue;
            }

            if ($char === '%') {
                $this->skipPdfComment($value, $index);
                continue;
            }

            if ($char === '(') {
                $this->readLiteralToken($value, $index);
                continue;
            }

            if ($char === '<') {
                if ($index + 1 < $length && $value[$index + 1] === '<') {
                    $this->readDictionaryToken($value, $index);
                    continue;
                }

                $this->readHexToken($value, $index);
                continue;
            }

            if ($char === '[') {
                $this->readArrayToken($value, $index);
                continue;
            }

            if (
                $this->pdfKeywordAt($value, $index, 'endstream')
                && $this->endstreamTerminatorAt($value, $index, $streamStart)
            ) {
                return $index;
            }

            $start = $index;
            while ($index < $length && !$this->isBareTokenDelimiter($value[$index])) {
                $index++;
            }

            if ($index === $start) {
                $index++;
                continue;
            }

            if (substr($value, $start, $index - $start) === 'BI') {
                $inlineImageEnd = $index;
                if ($this->skipInlineImage($value, $inlineImageEnd)) {
                    $index = $inlineImageEnd;
                }
            }
        }

        return null;
    }

    private function canScanContentStreamForInlineImages(string $dict): bool
    {
        $filters = $this->streamFilters($dict, []);
        if ($filters !== []) {
            return false;
        }

        return !$this->streamDictionaryHasAnyTypeOrSubtypeName(
            $dict,
            ['ObjStm', 'XRef', 'Image', 'Metadata', 'EmbeddedFile', 'XML']
        );
    }

    /**
     * @param list<string|null> $filters
     */
    private function hasVerifiableStreamFilter(array $filters): bool
    {
        foreach ($filters as $filter) {
            if (in_array($filter, [
                'ASCII85Decode',
                'A85',
                'ASCIIHexDecode',
                'AHx',
                'FlateDecode',
                'Fl',
                'LZWDecode',
                'LZW',
                'RunLengthDecode',
                'RL',
            ], true)) {
                return true;
            }
        }

        return false;
    }

    private function stripStreamTerminatingLineEnding(string $stream): string
    {
        if (str_ends_with($stream, "\r\n")) {
            return substr($stream, 0, -2);
        }

        if (str_ends_with($stream, "\n") || str_ends_with($stream, "\r")) {
            return substr($stream, 0, -1);
        }

        return $stream;
    }

    private function isEmbeddedFileStreamDictionary(string $dict): bool
    {
        return $this->streamDictionaryHasName($dict, 'Type', 'EmbeddedFile');
    }

    /**
     * @param array<int, string> $objects
     */
    private function isObjectStreamDictionary(string $dict, array $objects): bool
    {
        return $this->streamDictionaryHasName($dict, 'Type', 'ObjStm', $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function isXrefStreamDictionary(string $dict, array $objects): bool
    {
        return $this->streamDictionaryHasName($dict, 'Type', 'XRef', $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function objectBodyHasTypeName(string $body, string $expectedType, array $objects = []): bool
    {
        $dict = $this->dictionaryObjectBody($body) ?? $body;

        return $this->streamDictionaryHasName($dict, 'Type', $expectedType, $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function streamDictionaryHasName(string $dict, string $key, string $expectedValue, array $objects = []): bool
    {
        $offset = $this->topLevelNameValueOffset($dict, $key);
        if ($offset === null) {
            return false;
        }

        return $this->pdfNameValueAt($dict, $offset, $objects) === $expectedValue;
    }

    /**
     * @param list<string> $names
     */
    private function streamDictionaryHasAnyTypeOrSubtypeName(string $dict, array $names): bool
    {
        foreach (['Type', 'Subtype'] as $key) {
            $offset = $this->topLevelNameValueOffset($dict, $key);
            if ($offset === null) {
                continue;
            }

            $value = $this->pdfNameValueAt($dict, $offset, []);
            if (is_string($value) && in_array($value, $names, true)) {
                return true;
            }
        }

        return false;
    }

    /**
     * @param array<int, string> $objects
     */
    private function decodeStream(
        string $dict,
        string $stream,
        array $objects = [],
        bool $requireExplicitFilterEndMarkers = false,
        bool $ignoreNullFilterDecodeParms = false,
        bool $requireBoundedExplicitFilterEndMarkers = false
    ): ?string
    {
        $filters = $this->streamFilters($dict, $objects);
        if ($filters === null) {
            return null;
        }

        if ($filters === []) {
            return $stream;
        }

        $decodeParms = $ignoreNullFilterDecodeParms
            ? $this->streamDecodeParmsForFilters($dict, $objects, $filters)
            : $this->streamDecodeParms($dict, $objects);
        if ($decodeParms === null) {
            return null;
        }
        if ($this->invalidUnappliedDecodeParmsParameterCount($filters, $decodeParms, $objects) > 0) {
            return null;
        }
        foreach ($filters as $index => $filter) {
            if ($filter === null) {
                continue;
            }

            $filterDecodeParms = $this->decodeParmsForFilterIndex($filters, $decodeParms, $index);
            if (!$this->canApplyDecodeParms($filter, $filterDecodeParms, $objects)) {
                return null;
            }

            if (
                $requireExplicitFilterEndMarkers
                && !$this->streamFilterInputHasExplicitEndMarker($filter, $stream)
            ) {
                return null;
            }
            if (
                $requireBoundedExplicitFilterEndMarkers
                && !$this->streamFilterInputHasBoundedEndMarker(
                    $filter,
                    $stream,
                    $filterDecodeParms,
                    $objects,
                    !$requireExplicitFilterEndMarkers
                )
            ) {
                return null;
            }

            $decoded = match ($filter) {
                'ASCIIHexDecode', 'AHx' => $this->decodeAsciiHexStream($stream),
                'ASCII85Decode', 'A85' => $this->decodeAscii85Stream($stream),
                'RunLengthDecode', 'RL' => $this->decodeRunLengthStream($stream),
                'LZWDecode', 'LZW' => $this->decodeLzwStream($stream, $filterDecodeParms, $objects),
                'FlateDecode', 'Fl' => $this->decodeFlateStream($stream, $filterDecodeParms, $objects),
                'Crypt' => $this->decodeCryptIdentityStream($stream, $filterDecodeParms, $objects),
                'DCTDecode', 'DCT' => null,
                'CCITTFaxDecode', 'CCF' => null,
                'JPXDecode', 'JBIG2Decode' => null,
                default => null,
            };

            if ($decoded === null) {
                return null;
            }
            $stream = $decoded;
        }

        return $stream;
    }

    private function streamFilterInputHasExplicitEndMarker(string $filter, string $stream): bool
    {
        return match ($filter) {
            'ASCIIHexDecode', 'AHx' => strpos($stream, '>') !== false,
            'ASCII85Decode', 'A85' => strpos($stream, '~>') !== false,
            'RunLengthDecode', 'RL' => strpos($stream, chr(128)) !== false,
            default => true,
        };
    }

    private function streamFilterRequiresExplicitEndMarker(string $filter): bool
    {
        return in_array($filter, [
            'ASCIIHexDecode',
            'AHx',
            'ASCII85Decode',
            'A85',
            'RunLengthDecode',
            'RL',
        ], true);
    }

    /**
     * @param array<int, string> $objects
     */
    private function streamFilterInputHasBoundedEndMarker(
        string $filter,
        string $stream,
        ?string $decodeParms = null,
        array $objects = [],
        bool $allowMissingExplicitEndMarker = false
    ): bool
    {
        $offset = $this->streamFilterInputEndByteOffset($filter, $stream, $decodeParms, $objects);
        if ($offset === null) {
            if ($allowMissingExplicitEndMarker && $this->streamFilterRequiresExplicitEndMarker($filter)) {
                return true;
            }

            return !in_array($filter, [
                'ASCIIHexDecode',
                'AHx',
                'ASCII85Decode',
                'A85',
                'RunLengthDecode',
                'RL',
                'FlateDecode',
                'Fl',
                'LZWDecode',
                'LZW',
            ], true);
        }

        return $this->streamHasOnlyWhitespaceAfterOffset($stream, $offset);
    }

    /**
     * @param array<int, string> $objects
     */
    private function streamFilterInputEndByteOffset(
        string $filter,
        string $stream,
        ?string $decodeParms = null,
        array $objects = []
    ): ?int {
        return match ($filter) {
            'ASCIIHexDecode', 'AHx' => (($offset = strpos($stream, '>')) !== false) ? $offset + 1 : null,
            'ASCII85Decode', 'A85' => (($offset = strpos($stream, '~>')) !== false) ? $offset + 2 : null,
            'RunLengthDecode', 'RL' => (($offset = $this->runLengthExplicitEndOffset($stream)) !== null) ? $offset + 1 : null,
            'FlateDecode', 'Fl' => $this->flateExplicitEndByteOffset($stream),
            'LZWDecode', 'LZW' => $this->lzwExplicitEndByteOffset($stream, $decodeParms, $objects),
            default => null,
        };
    }

    private function streamHasOnlyWhitespaceAfterOffset(string $stream, int $offset): bool
    {
        $length = strlen($stream);
        for ($index = $offset; $index < $length; $index++) {
            if (!ctype_space($stream[$index])) {
                return false;
            }
        }

        return true;
    }

    private function runLengthExplicitEndOffset(string $stream): ?int
    {
        $length = strlen($stream);
        for ($offset = 0; $offset < $length; $offset++) {
            $control = ord($stream[$offset]);
            if ($control === 128) {
                return $offset;
            }
            if ($control <= 127) {
                $literalLength = $control + 1;
                if ($offset + $literalLength >= $length) {
                    return null;
                }
                $offset += $literalLength;
                continue;
            }
            if ($offset + 1 >= $length) {
                return null;
            }
            $offset++;
        }

        return null;
    }

    private function flateExplicitEndByteOffset(string $stream): ?int
    {
        if (
            !function_exists('inflate_init')
            || !function_exists('inflate_add')
            || !function_exists('inflate_get_status')
            || !function_exists('inflate_get_read_len')
        ) {
            return null;
        }

        $encodings = [];
        foreach (['ZLIB_ENCODING_DEFLATE', 'ZLIB_ENCODING_RAW', 'ZLIB_ENCODING_GZIP'] as $constant) {
            if (defined($constant)) {
                $encodings[] = constant($constant);
            }
        }

        $finish = defined('ZLIB_FINISH') ? constant('ZLIB_FINISH') : 4;
        $streamEnd = defined('ZLIB_STREAM_END') ? constant('ZLIB_STREAM_END') : 1;
        foreach (array_unique($encodings) as $encoding) {
            $context = @inflate_init($encoding);
            if ($context === false) {
                continue;
            }

            $decoded = @inflate_add($context, $stream, $finish);
            if ($decoded === false || @inflate_get_status($context) !== $streamEnd) {
                continue;
            }

            $readLength = @inflate_get_read_len($context);
            if (is_int($readLength) && $readLength > 0) {
                return $readLength;
            }
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function lzwExplicitEndByteOffset(string $stream, ?string $decodeParms = null, array $objects = []): ?int
    {
        $earlyChange = ($this->decodeParmsInt($decodeParms, 'EarlyChange', $objects) ?? 1) === 0 ? 0 : 1;
        $bitOffset = 0;
        $dictionary = [];
        $nextCode = 258;
        $codeSize = 9;

        $resetDictionary = static function () use (&$dictionary, &$nextCode, &$codeSize): void {
            $dictionary = [];
            for ($code = 0; $code < 256; $code++) {
                $dictionary[$code] = chr($code);
            }
            $nextCode = 258;
            $codeSize = 9;
        };
        $resetDictionary();

        $previous = null;
        while (($code = $this->readLzwCode($stream, $bitOffset, $codeSize)) !== null) {
            if ($code === 256) {
                $resetDictionary();
                $previous = null;
                continue;
            }

            if ($code === 257) {
                return intdiv($bitOffset + 7, 8);
            }

            if (isset($dictionary[$code])) {
                $entry = $dictionary[$code];
            } elseif ($code === $nextCode && $previous !== null) {
                $entry = $previous . $previous[0];
            } else {
                return null;
            }

            if ($previous !== null && $nextCode < 4096) {
                $dictionary[$nextCode] = $previous . $entry[0];
                $nextCode++;
                if ($codeSize < 12 && $nextCode + $earlyChange >= (1 << $codeSize)) {
                    $codeSize++;
                }
            }
            $previous = $entry;
        }

        return null;
    }

    /**
     * @param list<string|null> $filters
     * @param list<string|null> $decodeParms
     */
    private function decodeParmsForFilterIndex(array $filters, array $decodeParms, int $index): ?string
    {
        $decodeParmsIndex = $this->decodeParmsIndexForFilterIndex($filters, $decodeParms, $index);
        if ($decodeParmsIndex === null) {
            return null;
        }

        return $decodeParms[$decodeParmsIndex] ?? null;
    }

    /**
     * @param list<string|null> $filters
     * @param list<string|null> $decodeParms
     */
    private function decodeParmsIndexForFilterIndex(array $filters, array $decodeParms, int $index): ?int
    {
        $nonNullFilterIndexes = [];
        foreach ($filters as $filterIndex => $filter) {
            if (is_string($filter)) {
                $nonNullFilterIndexes[] = $filterIndex;
            }
        }

        if ($this->decodeParmsUseCompactNonNullFilterIndexes($filters, count($decodeParms), $nonNullFilterIndexes)) {
            $compactPosition = array_search($index, $nonNullFilterIndexes, true);
            if ($compactPosition !== false) {
                $decodeParmsIndexes = array_keys($decodeParms);
                $decodeParmsIndex = $decodeParmsIndexes[$compactPosition] ?? null;
                return is_int($decodeParmsIndex) ? $decodeParmsIndex : null;
            }
        }

        if (array_key_exists($index, $decodeParms)) {
            return $index;
        }

        if (count($decodeParms) !== 1) {
            return null;
        }

        if ($nonNullFilterIndexes !== [$index]) {
            return null;
        }

        $decodeParmsIndex = array_key_first($decodeParms);
        return is_int($decodeParmsIndex) ? $decodeParmsIndex : null;
    }

    /**
     * @return list<string|null>|null
     * @param array<int, string> $objects
     */
    private function streamFilters(string $dict, array $objects = []): ?array
    {
        $offset = $this->topLevelNameValueOffset($dict, 'Filter');
        if ($offset === null) {
            return [];
        }

        if ($offset >= strlen($dict)) {
            return null;
        }

        if ($dict[$offset] === '[') {
            $arrayBody = $this->readPdfArrayAt($dict, $offset);
            $filters = $arrayBody === null ? null : $this->filterNamesFromValue($arrayBody, $objects, [], false);
            return $filters === null ? null : $this->normalizeStreamFilterStack($filters);
        }

        if ($dict[$offset] === '/') {
            $end = $offset + 1;
            while ($end < strlen($dict) && !str_contains(" \t\r\n\f[]()<>{}/%", $dict[$end])) {
                $end++;
            }

            return [$this->decodePdfName(substr($dict, $offset + 1, $end - $offset - 1))];
        }

        if (preg_match('/\Gnull\b/s', $dict, $match, 0, $offset) === 1) {
            return [];
        }

        $reference = $this->pdfIndirectReferenceTokenAt($dict, $offset);
        if ($reference !== null) {
            $objectNumber = $reference['objectNumber'];
            $generation = $reference['generation'];
            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            $filters = $body === null
                ? null
                : $this->filterNamesFromValue(trim($body), $objects, [$objectNumber . ':' . $generation => true]);
            return $filters === null ? null : $this->normalizeStreamFilterStack($filters);
        }

        return null;
    }

    /**
     * @param list<string|null> $filters
     * @param list<int>|null $nonNullFilterIndexes
     */
    private function decodeParmsUseCompactNonNullFilterIndexes(
        array $filters,
        int $decodeParmsCount,
        ?array $nonNullFilterIndexes = null
    ): bool {
        if ($nonNullFilterIndexes === null) {
            $nonNullFilterIndexes = [];
            foreach ($filters as $filterIndex => $filter) {
                if (is_string($filter)) {
                    $nonNullFilterIndexes[] = $filterIndex;
                }
            }
        }

        return $decodeParmsCount === count($nonNullFilterIndexes)
            && count($filters) !== $decodeParmsCount;
    }

    /**
     * @param list<string|null> $filters
     */
    private function decodeParmsIndexIsAlignedToNullFilter(array $filters, int $decodeParmsIndex, int $decodeParmsCount): bool
    {
        if ($this->decodeParmsUseCompactNonNullFilterIndexes($filters, $decodeParmsCount)) {
            return false;
        }

        return array_key_exists($decodeParmsIndex, $filters) && $filters[$decodeParmsIndex] === null;
    }

    /**
     * @param list<string|null> $filters
     * @return list<string|null>
     */
    private function normalizeStreamFilterStack(array $filters): array
    {
        foreach ($filters as $filter) {
            if (is_string($filter)) {
                return $filters;
            }
        }

        return [];
    }

    /**
     * @return list<string|null>|null
     * @param array<int, string> $objects
     * @param array<int, true> $seenObjects
     */
    private function filterNamesFromValue(
        string $value,
        array $objects,
        array $seenObjects = [],
        bool $allowArrayValue = true
    ): ?array
    {
        $filters = [];
        $offset = 0;
        $length = strlen($value);
        while ($offset < $length) {
            $offset = $this->skipPdfWhitespace($value, $offset);
            if ($offset >= $length) {
                break;
            }

            if ($value[$offset] === '%') {
                $this->skipPdfComment($value, $offset);
                continue;
            }

            if ($value[$offset] === '[') {
                if (!$allowArrayValue || $filters !== []) {
                    return null;
                }

                $arrayBody = $this->readPdfArrayAt($value, $offset);
                if ($arrayBody === null) {
                    return null;
                }

                $nested = $this->filterNamesFromValue($arrayBody, $objects, $seenObjects, false);
                if ($nested === null) {
                    return null;
                }

                foreach ($nested as $filter) {
                    $filters[] = $filter;
                }
                $offset += strlen($arrayBody) + 2;
                continue;
            }

            if ($value[$offset] === '/') {
                $end = $offset + 1;
                while ($end < $length && !str_contains(" \t\r\n\f[]()<>{}/%", $value[$end])) {
                    $end++;
                }

                $filters[] = $this->decodePdfName(substr($value, $offset + 1, $end - $offset - 1));
                $offset = $end;
                continue;
            }

            if (preg_match('/\Gnull\b/s', $value, $match, 0, $offset) === 1) {
                $filters[] = null;
                $offset += strlen($match[0]);
                continue;
            }

            $reference = $this->pdfIndirectReferenceTokenAt($value, $offset);
            if ($reference !== null) {
                $objectNumber = $reference['objectNumber'];
                $generation = $reference['generation'];
                $objectKey = $objectNumber . ':' . $generation;
                if ($objectNumber <= 0 || isset($seenObjects[$objectKey])) {
                    return null;
                }

                $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
                if ($body === null) {
                    return null;
                }

                $nextSeen = $seenObjects;
                $nextSeen[$objectKey] = true;
                $nested = $this->filterNamesFromValue(trim($body), $objects, $nextSeen, $allowArrayValue && $filters === []);
                if ($nested === null) {
                    return null;
                }

                foreach ($nested as $filter) {
                    $filters[] = $filter;
                }
                $offset = $reference['endOffset'];
                continue;
            }

            return null;
        }

        return $filters;
    }

    /**
     * @return list<string|null>|null
     * @param array<int, string> $objects
     */
    private function streamDecodeParms(string $dict, array $objects): ?array
    {
        $offset = $this->topLevelNameValueOffset($dict, 'DecodeParms');
        if ($offset === null) {
            return [];
        }

        return $this->decodeParmsValueList($dict, $offset, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param list<string|null> $filters
     * @return list<string|null>|null
     */
    private function streamDecodeParmsForFilters(string $dict, array $objects, array $filters): ?array
    {
        if ($filters === []) {
            return [];
        }

        $offset = $this->topLevelNameValueOffset($dict, 'DecodeParms');
        if ($offset === null) {
            return [];
        }

        $offset = $this->skipPdfWhitespace($dict, $offset);
        if ($offset >= strlen($dict)) {
            return null;
        }

        return $this->decodeParmsValueListForFilters($dict, $offset, $objects, $filters);
    }

    /**
     * @param array<int, string> $objects
     * @param list<string|null> $filters
     * @param array<int, true> $seen
     * @return list<string|null>|null
     */
    private function decodeParmsValueListForFilters(
        string $value,
        int $offset,
        array $objects,
        array $filters,
        array $seen = []
    ): ?array {
        $offset = $this->skipPdfWhitespace($value, $offset);
        if ($offset >= strlen($value)) {
            return null;
        }

        $reference = $this->pdfIndirectReferenceTokenAt($value, $offset);
        if ($reference !== null) {
            $objectNumber = $reference['objectNumber'];
            $generation = $reference['generation'];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->decodeParmsValueListForFilters(trim($body), 0, $objects, $filters, $seen);
        }

        if ($value[$offset] !== '[') {
            return $this->decodeParmsValueList($value, $offset, $objects, $seen);
        }

        $arrayBody = $this->readPdfArrayAt($value, $offset);
        if ($arrayBody === null) {
            return null;
        }

        return $this->decodeParmsArrayItemsForFilters($arrayBody, $objects, $filters);
    }

    /**
     * @param array<int, string> $objects
     * @param list<string|null> $filters
     * @return list<string|null>|null
     */
    private function decodeParmsArrayItemsForFilters(string $arrayBody, array $objects, array $filters): ?array
    {
        $rawItems = $this->decodeParmsArrayRawItems($arrayBody);
        if ($rawItems === null) {
            return null;
        }

        $nonNullFilterIndexes = [];
        foreach ($filters as $filterIndex => $filter) {
            if (is_string($filter)) {
                $nonNullFilterIndexes[] = $filterIndex;
            }
        }

        $compactArray = $this->decodeParmsUseCompactNonNullFilterIndexes($filters, count($rawItems), $nonNullFilterIndexes);
        $items = [];
        foreach ($rawItems as $itemIndex => $rawItem) {
            $filterIndex = $compactArray ? ($nonNullFilterIndexes[$itemIndex] ?? null) : $itemIndex;
            if ($filterIndex !== null && array_key_exists($filterIndex, $filters) && $filters[$filterIndex] === null) {
                $items[] = null;
                continue;
            }

            if ($rawItem === null) {
                $items[] = null;
                continue;
            }

            $resolved = $this->decodeParmsValueList($rawItem, 0, $objects);
            if ($resolved === null || count($resolved) !== 1) {
                return null;
            }

            $items[] = $resolved[0];
        }

        return $items;
    }

    /**
     * @return list<string|null>|null
     */
    private function decodeParmsArrayRawItems(string $arrayBody): ?array
    {
        $items = [];
        $offset = 0;
        $length = strlen($arrayBody);
        while ($offset < $length) {
            $offset = $this->skipPdfWhitespace($arrayBody, $offset);
            if ($offset >= $length) {
                break;
            }

            if ($arrayBody[$offset] === '%') {
                $this->skipPdfComment($arrayBody, $offset);
                continue;
            }

            if (preg_match('/\Gnull\b/s', $arrayBody, $match, 0, $offset) === 1) {
                $items[] = null;
                $offset += strlen($match[0]);
                continue;
            }

            if (substr($arrayBody, $offset, 2) === '<<') {
                $dictionaryOffset = $offset;
                $dictionary = $this->readPdfDictionaryTokenAt($arrayBody, $dictionaryOffset);
                if ($dictionary === null) {
                    return null;
                }

                $items[] = '<<' . $dictionary . '>>';
                $offset = $dictionaryOffset;
                continue;
            }

            if ($arrayBody[$offset] === '[') {
                $body = $this->readPdfArrayAt($arrayBody, $offset);
                if ($body === null) {
                    return null;
                }

                $items[] = '[' . $body . ']';
                $offset += strlen($body) + 2;
                continue;
            }

            if ($arrayBody[$offset] === '(') {
                $start = $offset;
                $this->readLiteralToken($arrayBody, $offset);
                $items[] = substr($arrayBody, $start, $offset - $start);
                continue;
            }

            if ($arrayBody[$offset] === '<') {
                $start = $offset;
                $this->readHexToken($arrayBody, $offset);
                $items[] = substr($arrayBody, $start, $offset - $start);
                continue;
            }

            if ($arrayBody[$offset] === '/') {
                $start = $offset;
                $this->readNameToken($arrayBody, $offset);
                $items[] = substr($arrayBody, $start, $offset - $start);
                continue;
            }

            $reference = $this->pdfIndirectReferenceTokenAt($arrayBody, $offset);
            if ($reference !== null) {
                $items[] = $reference['token'];
                $offset = $reference['endOffset'];
                continue;
            }

            $start = $offset;
            while ($offset < $length && !$this->isBareTokenDelimiter($arrayBody[$offset])) {
                $offset++;
            }
            if ($offset === $start) {
                return null;
            }

            $items[] = substr($arrayBody, $start, $offset - $start);
        }

        return $items;
    }

    /**
     * @return list<string|null>|null
     * @param array<int, string> $objects
     * @param array<int, true> $seen
     */
    private function decodeParmsValueList(string $value, int $offset, array $objects, array $seen = []): ?array
    {
        $offset = $this->skipPdfWhitespace($value, $offset);
        if ($offset >= strlen($value)) {
            return null;
        }

        if ($value[$offset] === '[') {
            $arrayBody = $this->readPdfArrayAt($value, $offset);
            return $arrayBody === null ? null : $this->decodeParmsArrayItems($arrayBody, $objects, $seen);
        }

        if (substr($value, $offset, 2) === '<<') {
            $dictionary = $this->readPdfDictionaryTokenAt($value, $offset);
            return $dictionary === null ? null : [$dictionary];
        }

        if (preg_match('/\Gnull\b/s', $value, $match, 0, $offset) === 1) {
            return [null];
        }

        $reference = $this->pdfIndirectReferenceTokenAt($value, $offset);
        if ($reference !== null) {
            $objectNumber = $reference['objectNumber'];
            $generation = $reference['generation'];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->decodeParmsValueList(trim($body), 0, $objects, $seen);
        }

        return null;
    }

    /**
     * @return list<string|null>|null
     * @param array<int, string> $objects
     * @param array<int, true> $seen
     */
    private function decodeParmsArrayItems(string $arrayBody, array $objects, array $seen): ?array
    {
        $items = [];
        $offset = 0;
        $length = strlen($arrayBody);
        while ($offset < $length) {
            $offset = $this->skipPdfWhitespace($arrayBody, $offset);
            if ($offset >= $length) {
                break;
            }

            if ($arrayBody[$offset] === '%') {
                $this->skipPdfComment($arrayBody, $offset);
                continue;
            }

            if (preg_match('/\Gnull\b/s', $arrayBody, $match, 0, $offset) === 1) {
                $items[] = null;
                $offset += strlen($match[0]);
                continue;
            }

            if (substr($arrayBody, $offset, 2) === '<<') {
                $dictionary = $this->readPdfDictionaryTokenAt($arrayBody, $offset);
                if ($dictionary !== null) {
                    $items[] = $dictionary;
                    continue;
                }

                return null;
            }

            $reference = $this->pdfIndirectReferenceTokenAt($arrayBody, $offset);
            if ($reference !== null) {
                $objectNumber = $reference['objectNumber'];
                $generation = $reference['generation'];
                $objectKey = $objectNumber . ':' . $generation;
                if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                    return null;
                }

                $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
                if ($body === null) {
                    return null;
                }

                $nextSeen = $seen;
                $nextSeen[$objectKey] = true;
                $resolved = $this->decodeParmsValueList(trim($body), 0, $objects, $nextSeen);
                if ($resolved === null || count($resolved) !== 1) {
                    return null;
                }

                $items[] = $resolved[0];
                $offset = $reference['endOffset'];
                continue;
            }

            return null;
        }

        return $items;
    }

    /**
     * @param array<int, string> $objects
     */
    private function canApplyDecodeParms(string $filter, ?string $decodeParms, array $objects): bool
    {
        if ($decodeParms === null || trim($decodeParms) === '') {
            return true;
        }

        foreach (['Predictor', 'Columns', 'Colors', 'BitsPerComponent', 'EarlyChange'] as $name) {
            if (
                $this->decodeParmsHasName($decodeParms, $name)
                && $this->decodeParmsInt($decodeParms, $name, $objects) === null
            ) {
                return false;
            }
        }

        $predictor = $this->decodeParmsInt($decodeParms, 'Predictor', $objects);
        if (
            $predictor !== null
            && $predictor !== 1
            && !in_array($filter, ['FlateDecode', 'Fl', 'LZWDecode', 'LZW'], true)
        ) {
            return false;
        }

        foreach (['Columns', 'Colors', 'BitsPerComponent'] as $name) {
            $value = $this->decodeParmsInt($decodeParms, $name, $objects);
            if ($value !== null && $value < 1) {
                return false;
            }
        }

        $earlyChange = $this->decodeParmsInt($decodeParms, 'EarlyChange', $objects);
        if (
            in_array($filter, ['LZWDecode', 'LZW'], true)
            && $earlyChange !== null
            && !in_array($earlyChange, [0, 1], true)
        ) {
            return false;
        }

        return true;
    }

    private function decodeParmsHasName(?string $decodeParms, string $name): bool
    {
        return $decodeParms !== null && $this->topLevelNameValueOffset($decodeParms, $name) !== null;
    }

    private function decodeAsciiHexStream(string $stream): ?string
    {
        $body = strstr($stream, '>', true);
        if ($body === false) {
            $body = $stream;
        }

        $hex = preg_replace('/\s+/', '', $body);
        if ($hex === null || preg_match('/^[\da-fA-F]*$/', $hex) !== 1) {
            return null;
        }

        if (strlen($hex) % 2 === 1) {
            $hex .= '0';
        }

        $decoded = hex2bin($hex);
        return $decoded === false ? null : $decoded;
    }

    private function decodeAscii85Stream(string $stream): ?string
    {
        $body = trim($stream);
        if (str_starts_with($body, '<~')) {
            $body = substr($body, 2);
        }

        $terminator = strpos($body, '~>');
        if ($terminator !== false) {
            $body = substr($body, 0, $terminator);
        }

        $out = '';
        $group = [];
        $length = strlen($body);
        for ($index = 0; $index < $length; $index++) {
            $char = $body[$index];
            if (ctype_space($char)) {
                continue;
            }

            if ($char === 'z') {
                if ($group !== []) {
                    return null;
                }
                $out .= "\0\0\0\0";
                continue;
            }

            $ord = ord($char);
            if ($ord < 33 || $ord > 117) {
                return null;
            }

            $group[] = $ord - 33;
            if (count($group) === 5) {
                $out .= $this->decodeAscii85Group($group, 4);
                $group = [];
            }
        }

        if ($group !== []) {
            $groupLength = count($group);
            if ($groupLength === 1) {
                return null;
            }
            while (count($group) < 5) {
                $group[] = 84;
            }
            $out .= $this->decodeAscii85Group($group, $groupLength - 1);
        }

        return $out;
    }

    /**
     * @param list<int> $group
     */
    private function decodeAscii85Group(array $group, int $bytesToReturn): string
    {
        $value = 0;
        foreach ($group as $digit) {
            $value = ($value * 85) + $digit;
        }

        $bytes = '';
        for ($shift = 24; $shift >= 0; $shift -= 8) {
            $bytes .= chr(($value >> $shift) & 0xff);
        }

        return substr($bytes, 0, $bytesToReturn);
    }

    /**
     * @param array<int, string> $objects
     */
    private function decodeFlateStream(string $stream, ?string $decodeParms = null, array $objects = []): ?string
    {
        $inflated = @gzuncompress($stream);
        if ($inflated === false) {
            $inflated = @gzinflate($stream);
        }
        if ($inflated === false) {
            $inflated = @gzdecode($stream);
        }

        if ($inflated === false) {
            return null;
        }

        return $this->applyDecodeParmsPredictor($inflated, $decodeParms, $objects);
    }

    private function decodeCryptIdentityStream(string $stream, ?string $decodeParms, array $objects = []): ?string
    {
        if ($decodeParms === null || trim($decodeParms) === '') {
            return $stream;
        }

        $nameOffset = $this->topLevelNameValueOffset($decodeParms, 'Name');
        if ($nameOffset === null) {
            return $stream;
        }

        return $this->pdfNameValueAt($decodeParms, $nameOffset, $objects) === 'Identity' ? $stream : null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function decodeLzwStream(string $stream, ?string $decodeParms = null, array $objects = []): ?string
    {
        $earlyChange = ($this->decodeParmsInt($decodeParms, 'EarlyChange', $objects) ?? 1) === 0 ? 0 : 1;
        $bitOffset = 0;
        $dictionary = [];
        $nextCode = 258;
        $codeSize = 9;

        $resetDictionary = static function () use (&$dictionary, &$nextCode, &$codeSize): void {
            $dictionary = [];
            for ($code = 0; $code < 256; $code++) {
                $dictionary[$code] = chr($code);
            }
            $nextCode = 258;
            $codeSize = 9;
        };
        $resetDictionary();

        $out = '';
        $previous = null;
        while (($code = $this->readLzwCode($stream, $bitOffset, $codeSize)) !== null) {
            if ($code === 256) {
                $resetDictionary();
                $previous = null;
                continue;
            }

            if ($code === 257) {
                return $this->applyDecodeParmsPredictor($out, $decodeParms, $objects);
            }

            if (isset($dictionary[$code])) {
                $entry = $dictionary[$code];
            } elseif ($code === $nextCode && $previous !== null) {
                $entry = $previous . $previous[0];
            } else {
                return null;
            }

            $out .= $entry;
            if ($previous !== null && $nextCode < 4096) {
                $dictionary[$nextCode] = $previous . $entry[0];
                $nextCode++;
                if ($codeSize < 12 && $nextCode + $earlyChange >= (1 << $codeSize)) {
                    $codeSize++;
                }
            }
            $previous = $entry;
        }

        return null;
    }

    private function readLzwCode(string $bytes, int &$bitOffset, int $codeSize): ?int
    {
        $totalBits = strlen($bytes) * 8;
        if ($bitOffset + $codeSize > $totalBits) {
            return null;
        }

        $code = 0;
        for ($index = 0; $index < $codeSize; $index++) {
            $absoluteBit = $bitOffset + $index;
            $byte = ord($bytes[intdiv($absoluteBit, 8)]);
            $shift = 7 - ($absoluteBit % 8);
            $code = ($code << 1) | (($byte >> $shift) & 1);
        }
        $bitOffset += $codeSize;

        return $code;
    }

    /**
     * @param array<int, string> $objects
     */
    private function applyDecodeParmsPredictor(string $bytes, ?string $decodeParms, array $objects = []): ?string
    {
        $predictor = $this->decodeParmsInt($decodeParms, 'Predictor', $objects) ?? 1;
        if ($predictor === 1) {
            return $bytes;
        }

        $colors = max(1, $this->decodeParmsInt($decodeParms, 'Colors', $objects) ?? 1);
        $bitsPerComponent = max(1, $this->decodeParmsInt($decodeParms, 'BitsPerComponent', $objects) ?? 8);
        $columns = max(1, $this->decodeParmsInt($decodeParms, 'Columns', $objects) ?? 1);
        $rowLength = intdiv(($colors * $columns * $bitsPerComponent) + 7, 8);
        $bytesPerPixel = max(1, intdiv(($colors * $bitsPerComponent) + 7, 8));

        if ($predictor === 2) {
            return $this->applyTiffPredictor($bytes, $rowLength, $bytesPerPixel);
        }

        if ($predictor < 10 || $predictor > 15) {
            return null;
        }

        return $this->applyPngPredictor($bytes, $rowLength, $bytesPerPixel);
    }

    /**
     * @param array<int, string> $objects
     */
    private function decodeParmsInt(?string $decodeParms, string $name, array $objects = []): ?int
    {
        if ($decodeParms === null) {
            return null;
        }

        $offset = $this->topLevelNameValueOffset($decodeParms, $name);
        return $offset === null ? null : $this->decodeParmsIntegerTokenAt($decodeParms, $offset, $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function decodeParmsBool(?string $decodeParms, string $name, array $objects = []): ?bool
    {
        if ($decodeParms === null) {
            return null;
        }

        $offset = $this->topLevelNameValueOffset($decodeParms, $name);
        return $offset === null ? null : $this->decodeParmsBooleanTokenAt($decodeParms, $offset, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, true> $seen
     */
    private function decodeParmsIntegerTokenAt(string $value, int $offset, array $objects, array $seen = []): ?int
    {
        $offset = $this->skipPdfWhitespace($value, $offset);
        $reference = $this->pdfIndirectReferenceTokenAt($value, $offset);
        if ($reference !== null) {
            $objectNumber = $reference['objectNumber'];
            $generation = $reference['generation'];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->decodeParmsIntegerTokenAt(trim($body), 0, $objects, $seen);
        }

        if (preg_match('/\G([+-]?\d+)/s', $value, $match, 0, $offset) === 1) {
            return (int) $match[1];
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, true> $seen
     */
    private function decodeParmsBooleanTokenAt(string $value, int $offset, array $objects, array $seen = []): ?bool
    {
        $offset = $this->skipPdfWhitespace($value, $offset);
        $reference = $this->pdfIndirectReferenceTokenAt($value, $offset);
        if ($reference !== null) {
            $objectNumber = $reference['objectNumber'];
            $generation = $reference['generation'];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->decodeParmsBooleanTokenAt(trim($body), 0, $objects, $seen);
        }

        if (preg_match('/\Gtrue\b/s', $value, $match, 0, $offset) === 1) {
            return true;
        }

        if (preg_match('/\Gfalse\b/s', $value, $match, 0, $offset) === 1) {
            return false;
        }

        return null;
    }

    private function applyTiffPredictor(string $bytes, int $rowLength, int $bytesPerPixel): ?string
    {
        if ($rowLength < 1 || strlen($bytes) % $rowLength !== 0) {
            return null;
        }

        $out = '';
        for ($offset = 0, $length = strlen($bytes); $offset < $length; $offset += $rowLength) {
            $row = substr($bytes, $offset, $rowLength);
            for ($index = $bytesPerPixel; $index < $rowLength; $index++) {
                $row[$index] = chr((ord($row[$index]) + ord($row[$index - $bytesPerPixel])) & 0xff);
            }
            $out .= $row;
        }

        return $out;
    }

    private function applyPngPredictor(string $bytes, int $rowLength, int $bytesPerPixel): ?string
    {
        $stride = $rowLength + 1;
        if ($rowLength < 1 || strlen($bytes) % $stride !== 0) {
            return null;
        }

        $out = '';
        $previous = str_repeat("\0", $rowLength);
        for ($offset = 0, $length = strlen($bytes); $offset < $length; $offset += $stride) {
            $filter = ord($bytes[$offset]);
            $row = substr($bytes, $offset + 1, $rowLength);
            if ($filter > 4) {
                return null;
            }

            for ($index = 0; $index < $rowLength; $index++) {
                $left = $index >= $bytesPerPixel ? ord($row[$index - $bytesPerPixel]) : 0;
                $up = ord($previous[$index]);
                $upperLeft = $index >= $bytesPerPixel ? ord($previous[$index - $bytesPerPixel]) : 0;
                $encoded = ord($row[$index]);
                $row[$index] = chr(($encoded + $this->pngPredictorValue($filter, $left, $up, $upperLeft)) & 0xff);
            }

            $out .= $row;
            $previous = $row;
        }

        return $out;
    }

    private function pngPredictorValue(int $filter, int $left, int $up, int $upperLeft): int
    {
        return match ($filter) {
            0 => 0,
            1 => $left,
            2 => $up,
            3 => intdiv($left + $up, 2),
            4 => $this->paethPredictor($left, $up, $upperLeft),
        };
    }

    private function paethPredictor(int $left, int $up, int $upperLeft): int
    {
        $estimate = $left + $up - $upperLeft;
        $leftDistance = abs($estimate - $left);
        $upDistance = abs($estimate - $up);
        $upperLeftDistance = abs($estimate - $upperLeft);

        if ($leftDistance <= $upDistance && $leftDistance <= $upperLeftDistance) {
            return $left;
        }
        if ($upDistance <= $upperLeftDistance) {
            return $up;
        }

        return $upperLeft;
    }

    private function decodeRunLengthStream(string $stream): ?string
    {
        $out = '';
        $length = strlen($stream);
        for ($offset = 0; $offset < $length; $offset++) {
            $control = ord($stream[$offset]);
            if ($control === 128) {
                return $out;
            }

            if ($control <= 127) {
                $copyLength = $control + 1;
                if ($offset + $copyLength >= $length) {
                    return null;
                }
                $out .= substr($stream, $offset + 1, $copyLength);
                $offset += $copyLength;
                continue;
            }

            if ($offset + 1 >= $length) {
                return null;
            }
            $out .= str_repeat($stream[$offset + 1], 257 - $control);
            $offset++;
        }

        return null;
    }

    /**
     * @return array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}>
     */
    private function fontToUnicodeMaps(string $pdfBytes): array
    {
        $objects = $this->pdfObjects($pdfBytes);
        $fontObjectMaps = $this->fontObjectMaps($objects);
        if ($fontObjectMaps === []) {
            return [];
        }

        $resourceMaps = [];
        foreach ($objects as $body) {
            $resourceDictionary = $this->resourceDictionaryBody($body, $objects);
            if ($resourceDictionary === null) {
                continue;
            }

            foreach ($this->fontResourceMapsFromResourceDictionary($resourceDictionary, $objects, $fontObjectMaps) as $name => $map) {
                $resourceMaps[$name] = $map;
            }
        }

        if ($resourceMaps !== []) {
            return $resourceMaps;
        }

        if (count($fontObjectMaps) === 1) {
            $onlyMap = reset($fontObjectMaps);
            return is_array($onlyMap) ? ['' => $onlyMap] : [];
        }

        return [];
    }

    /**
     * @return array<int, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}>
     * @param array<int, string> $objects
     */
    private function fontObjectMaps(array $objects): array
    {
        $namedCMapBodies = $this->namedCMapBodies($objects);
        $fontObjectMaps = [];

        foreach ($objects as $objectNumber => $body) {
            if (!$this->bodyMayContainFontDictionary($body)) {
                continue;
            }

            $map = $this->fontMapFromFontBody($body, $objects, $namedCMapBodies);
            if ($map !== null) {
                $fontObjectMaps[$objectNumber] = $map;
            }
        }

        return $fontObjectMaps;
    }

    private function bodyMayContainFontDictionary(string $body): bool
    {
        return str_contains($body, '/Type /Font') || str_contains($body, '/Type/Font');
    }

    /**
     * @return array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}|null
     * @param array<int, string> $objects
     * @param array<string, string> $namedCMapBodies
     */
    private function fontMapFromFontBody(string $body, array $objects, array $namedCMapBodies): ?array
    {
        $isSimpleFont = $this->isSimpleFontBody($body);
        $encodingFallback = $this->fontEncodingMap($body, $objects);
        $cidEncodingMap = $this->fontCidEncodingMap($body, $objects, $namedCMapBodies);
        $cMapWordSpacing = $cidEncodingMap !== null
            && $cidEncodingMap['cidMap'] !== [];
        $widthMetrics = $this->fontWidthMetrics($body, $objects);
        $descriptorInfo = $this->fontDescriptorInfo($body, $objects);
        $type3CharProcMap = $this->type3CharProcUnicodeMap($body, $objects, $cidEncodingMap);
        $cmap = null;
        if (preg_match('/\/ToUnicode\s+(\d+)\s+\d+\s+R\b/', $body, $match)) {
            $cmapObjectNumber = (int) $match[1];
            if (isset($objects[$cmapObjectNumber])) {
                $cmap = $this->toUnicodeMapFromObject($objects[$cmapObjectNumber], $objects, $namedCMapBodies);
            }
        }

        if (($cmap === null || ($cmap['map'] === [] && $cmap['codeSpaceRanges'] === [])) && $type3CharProcMap !== null) {
            $cmap = $type3CharProcMap;
        }

        if (($cmap === null || ($cmap['map'] === [] && $cmap['codeSpaceRanges'] === [])) && $encodingFallback !== null) {
            $cmap = $encodingFallback;
        }

        if ($cmap === null && $cidEncodingMap !== null && ($cidEncodingMap['cidMap'] !== [] || $cidEncodingMap['codeSpaceRanges'] !== [])) {
            $cmap = [
                'map' => [],
                'codeSpaceRanges' => $cidEncodingMap['codeSpaceRanges'],
            ];
            if (isset($cidEncodingMap['writingMode'])) {
                $cmap['writingMode'] = (int) $cidEncodingMap['writingMode'] === 1 ? 1 : 0;
            }
        }

        if ($cmap === null && $widthMetrics['widths'] !== [] && $this->isSimpleFontBody($body)) {
            $cmap = [
                'map' => [],
                'codeSpaceRanges' => [
                    ['start' => 0, 'end' => 255, 'width' => 2],
                ],
            ];
        }

        if ($cmap === null && ($descriptorInfo['name'] !== null || $descriptorInfo['flags'] !== null)) {
            $cmap = [
                'map' => [],
                'codeSpaceRanges' => [],
            ];
        }

        if ($cmap === null || ($cmap['map'] === [] && $cmap['codeSpaceRanges'] === [] && $descriptorInfo['name'] === null && $descriptorInfo['flags'] === null)) {
            return null;
        }

        $cmap = $this->withFontCidEncodingMap($cmap, $cidEncodingMap);
        if ($cMapWordSpacing) {
            $cmap['wordSpacingUsesCidMap'] = true;
        }
        $cmap = $this->withFontWidthMetrics($cmap, $widthMetrics, $this->fontWritingMode($body, $cmap, $cidEncodingMap, $objects));
        $cmap = $this->withFontDescriptorInfo($cmap, $descriptorInfo);
        $cmap['simpleFont'] = $isSimpleFont;

        return $cmap;
    }

    /**
     * @return array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}>
     * @param array<int, string> $objects
     * @param array<int, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}> $fontObjectMaps
     */
    private function pageFontToUnicodeMaps(int $pageObjectNumber, array $objects, array $fontObjectMaps): array
    {
        $resourceDictionary = $this->pageResourceDictionaryBody($pageObjectNumber, $objects);
        if ($resourceDictionary !== null) {
            return $this->fontResourceMapsFromResourceDictionary($resourceDictionary, $objects, $fontObjectMaps);
        }

        if ($this->pageResourceDictionaryBlocksFallback($pageObjectNumber, $objects)) {
            return [];
        }

        if (count($fontObjectMaps) === 1) {
            $onlyMap = reset($fontObjectMaps);
            return is_array($onlyMap) ? ['' => $onlyMap] : [];
        }

        return [];
    }

    /**
     * @return list<int>
     * @param array<int, string> $objects
     */
    private function pageObjectLineage(int $pageObjectNumber, array $objects): array
    {
        return $this->pageObjectLineageResolution($pageObjectNumber, $objects)['lineage'];
    }

    /**
     * @return array{lineage: list<int>, blocked: bool}
     * @param array<int, string> $objects
     */
    private function pageObjectLineageResolution(int $pageObjectNumber, array $objects): array
    {
        $lineage = [];
        $seen = [];
        $objectNumber = $pageObjectNumber;
        $blocked = false;

        while (isset($objects[$objectNumber]) && !isset($seen[$objectNumber])) {
            $seen[$objectNumber] = true;
            $lineage[] = $objectNumber;

            $dictionary = $this->dictionaryObjectBody($objects[$objectNumber]);
            if ($dictionary === null) {
                break;
            }

            $parentValue = $this->topLevelPdfValueAfterNameInDictionaryBody($dictionary, 'Parent');
            if ($parentValue === null) {
                $catalogLineage = $this->pageObjectLineageFromCatalogPath($pageObjectNumber, $objects);
                if ($this->pageObjectLineageIsPrefix($lineage, $catalogLineage)) {
                    return [
                        'lineage' => $catalogLineage,
                        'blocked' => false,
                    ];
                }

                break;
            }

            if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', trim($parentValue), $match) !== 1) {
                break;
            }

            $parentObjectNumber = (int) $match[1];
            $parentGeneration = (int) $match[2];
            $parentBody = $this->objectBodyForExactReference($objects, $parentObjectNumber, $parentGeneration);
            if (
                $parentBody === null
                || !isset($objects[$parentObjectNumber])
                || $objects[$parentObjectNumber] !== $parentBody
                || !$this->isPagesObject($parentBody)
            ) {
                $blocked = true;
                break;
            }

            $childGeneration = $this->selectedObjectGeneration($objects, $objectNumber);
            if (
                $childGeneration === null
                || !$this->pageTreeParentListsChild($parentBody, $objectNumber, $childGeneration, $objects)
            ) {
                $blocked = true;
                break;
            }

            $objectNumber = $parentObjectNumber;
        }

        return [
            'lineage' => $lineage,
            'blocked' => $blocked,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return list<int>
     */
    private function pageObjectLineageFromCatalogPath(int $pageObjectNumber, array $objects): array
    {
        $catalog = $this->catalogObjectBody($objects);
        if ($catalog === null) {
            return [];
        }

        $pagesReference = $this->objectReferenceAfterName($catalog, 'Pages');
        if ($pagesReference === null) {
            return [];
        }

        return $this->pageObjectLineageFromTreeReference(
            $pagesReference['objectNumber'],
            $pagesReference['generation'],
            $pageObjectNumber,
            $objects
        ) ?? [];
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     * @return list<int>|null
     */
    private function pageObjectLineageFromTreeReference(
        int $objectNumber,
        int $generation,
        int $targetPageObjectNumber,
        array $objects,
        array $seen = []
    ): ?array {
        $referenceKey = $objectNumber . ':' . $generation;
        if (isset($seen[$referenceKey])) {
            return null;
        }

        $body = $this->objectBodyForPageTreeReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return null;
        }

        $seen[$referenceKey] = true;
        if ($this->isPageObject($body)) {
            return $objectNumber === $targetPageObjectNumber ? [$objectNumber] : null;
        }

        if (!$this->isPagesObject($body)) {
            return null;
        }

        foreach ($this->pageTreeKidObjectReferences($body, $objects) as $childReference) {
            $lineage = $this->pageObjectLineageFromTreeReference(
                $childReference['objectNumber'],
                $childReference['generation'],
                $targetPageObjectNumber,
                $objects,
                $seen
            );
            if ($lineage !== null) {
                $lineage[] = $objectNumber;
                return $lineage;
            }
        }

        return null;
    }

    /**
     * @param list<int> $lineage
     * @param list<int> $catalogLineage
     */
    private function pageObjectLineageIsPrefix(array $lineage, array $catalogLineage): bool
    {
        if ($lineage === [] || count($lineage) > count($catalogLineage)) {
            return false;
        }

        foreach ($lineage as $index => $objectNumber) {
            if (($catalogLineage[$index] ?? null) !== $objectNumber) {
                return false;
            }
        }

        return true;
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageResourceDictionaryBody(int $pageObjectNumber, array $objects): ?string
    {
        foreach ($this->pageObjectLineage($pageObjectNumber, $objects) as $objectNumber) {
            $resolution = $this->pageResourceDictionaryResolution($objects[$objectNumber], $objects);
            if ($resolution['state'] === 'resolved') {
                return $resolution['body'];
            }

            if ($resolution['state'] === 'blocked') {
                return null;
            }
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     * @return array{body: string, metadata: array{owner_object: int, inherited: bool, resource_object: int|null, resource_generation: int|null}}|null
     */
    private function pageResourceDictionaryReview(int $pageObjectNumber, array $objects): ?array
    {
        foreach ($this->pageObjectLineage($pageObjectNumber, $objects) as $objectNumber) {
            $resolution = $this->pageResourceDictionaryResolution($objects[$objectNumber], $objects);
            if ($resolution['state'] === 'resolved') {
                return [
                    'body' => $resolution['body'],
                    'metadata' => [
                        'owner_object' => $objectNumber,
                        'inherited' => $objectNumber !== $pageObjectNumber,
                        'resource_object' => $resolution['object'],
                        'resource_generation' => $resolution['generation'],
                    ],
                ];
            }

            if ($resolution['state'] === 'blocked') {
                return null;
            }
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     * @return array{bbox: list<float>, source: string, media_box: list<float>, media_box_source: string, crop_box: list<float>, crop_box_source: string, crop_box_clipped_to_media: bool, crop_box_intersects_media: bool, review_only: true}|null
     */
    private function pageImageXObjectBoundaryClipReview(int $pageObjectNumber, array $objects): ?array
    {
        $mediaBox = null;
        $mediaBoxSource = 'default';
        $cropBox = null;
        $cropBoxSource = 'media_box';
        $rotation = 0;
        $rotationSource = 'default';
        $userUnit = 1.0;
        $userUnitSource = 'default';
        $hasExplicitPageGeometry = false;

        foreach (array_reverse($this->pageObjectLineage($pageObjectNumber, $objects)) as $objectNumber) {
            $objectBody = $objects[$objectNumber] ?? null;
            if ($objectBody === null) {
                continue;
            }

            $source = $objectNumber === $pageObjectNumber ? 'page' : 'pages';
            $candidateMediaBox = $this->topLevelPdfRectangleValueAfterName($objectBody, 'MediaBox', $objects);
            if ($candidateMediaBox !== null) {
                $mediaBox = $candidateMediaBox;
                $mediaBoxSource = $source;
                $hasExplicitPageGeometry = true;
            }

            $candidateCropBox = $this->topLevelPdfRectangleValueAfterName($objectBody, 'CropBox', $objects);
            if ($candidateCropBox !== null) {
                $cropBox = $candidateCropBox;
                $cropBoxSource = $source;
                $hasExplicitPageGeometry = true;
            }

            $candidateRotation = $this->topLevelPdfNumberValueAfterName($objectBody, 'Rotate', $objects);
            if ($candidateRotation !== null) {
                $rotation = $this->normalizedPageRotation((int) round($candidateRotation));
                $rotationSource = $source;
                $hasExplicitPageGeometry = true;
            }

            if ($objectNumber === $pageObjectNumber) {
                $candidateUserUnit = $this->topLevelPdfNumberValueAfterName($objectBody, 'UserUnit', $objects);
                if ($candidateUserUnit !== null && $candidateUserUnit > 0.0) {
                    $userUnit = (float) $candidateUserUnit;
                    $userUnitSource = $source;
                    $hasExplicitPageGeometry = true;
                }
            }
        }

        if (!$hasExplicitPageGeometry) {
            return null;
        }

        if ($mediaBox === null) {
            $mediaBox = [0.0, 0.0, 612.0, 792.0];
            $mediaBoxSource = 'default';
        }

        if ($cropBox === null) {
            $cropBox = $mediaBox;
            $cropBoxSource = 'media_box';
        }

        $clipBox = $this->pdfPageBoundaryIntersection($mediaBox, $cropBox);
        $cropBoxClippedToMedia = !$this->pdfRectanglesEqual($cropBox, $clipBox);

        return [
            'bbox' => $clipBox,
            'source' => $cropBoxClippedToMedia
                ? 'crop_box_clipped_to_media_box'
                : ($cropBoxSource === 'media_box' ? $mediaBoxSource : 'crop_box'),
            'media_box' => $this->normalizedPdfReviewNumbers($mediaBox),
            'media_box_source' => $mediaBoxSource,
            'crop_box' => $this->normalizedPdfReviewNumbers($cropBox),
            'crop_box_source' => $cropBoxSource,
            'crop_box_clipped_to_media' => $cropBoxClippedToMedia,
            'crop_box_intersects_media' => $this->pdfRectanglesHavePositiveIntersection($mediaBox, $cropBox),
            'rotation' => $rotation,
            'rotation_source' => $rotationSource,
            'user_unit' => $userUnit,
            'user_unit_source' => $userUnitSource,
            'rotation_swaps_axes' => in_array($rotation, [90, 270], true),
            'user_unit_applied_to_display' => abs($userUnit - 1.0) > 0.000001,
            'display_page_size' => $this->imageXObjectPageDisplaySize($clipBox, $rotation, $userUnit),
            'review_only' => true,
        ];
    }

    /**
     * @param array<int, string> $objects
     */
    private function topLevelPdfNumberValueAfterName(string $objectBody, string $name, array $objects): ?float
    {
        $value = $this->topLevelPdfValueAfterName($objectBody, $name);
        if ($value === null) {
            return null;
        }

        return $this->pdfNumberValueAt($value, 0, $objects);
    }

    private function normalizedPageRotation(int $rotation): int
    {
        $rotation %= 360;
        if ($rotation < 0) {
            $rotation += 360;
        }

        return in_array($rotation, [0, 90, 180, 270], true) ? $rotation : 0;
    }

    /**
     * @param list<float> $pageBbox
     * @return array{width: float, height: float}
     */
    private function imageXObjectPageDisplaySize(array $pageBbox, int $rotation, float $userUnit): array
    {
        $width = max(0.0, $pageBbox[2] - $pageBbox[0]) * $userUnit;
        $height = max(0.0, $pageBbox[3] - $pageBbox[1]) * $userUnit;
        if (in_array($this->normalizedPageRotation($rotation), [90, 270], true)) {
            [$width, $height] = [$height, $width];
        }

        return [
            'width' => $this->normalizedPdfReviewNumbers([$width])[0],
            'height' => $this->normalizedPdfReviewNumbers([$height])[0],
        ];
    }

    /**
     * @param list<list<float>> $bboxes
     * @param list<float> $pageBbox
     * @return list<list<float>>
     */
    private function imageXObjectDisplayBboxes(array $bboxes, array $pageBbox, int $rotation, float $userUnit): array
    {
        $displayBboxes = [];
        foreach ($bboxes as $bbox) {
            $displayBboxes[] = $this->imageXObjectDisplayBbox($bbox, $pageBbox, $rotation, $userUnit);
        }

        return $displayBboxes;
    }

    /**
     * @param list<float> $bbox
     * @param list<float> $pageBbox
     * @return list<float>
     */
    private function imageXObjectDisplayBbox(array $bbox, array $pageBbox, int $rotation, float $userUnit): array
    {
        $points = [
            [$bbox[0], $bbox[1]],
            [$bbox[2], $bbox[1]],
            [$bbox[0], $bbox[3]],
            [$bbox[2], $bbox[3]],
        ];
        $mapped = array_map(
            fn (array $point): array => $this->imageXObjectDisplayPoint(
                (float) $point[0],
                (float) $point[1],
                $pageBbox,
                $rotation,
                $userUnit
            ),
            $points
        );
        $xs = array_column($mapped, 0);
        $ys = array_column($mapped, 1);

        return $this->normalizedPdfReviewNumbers([
            min($xs),
            min($ys),
            max($xs),
            max($ys),
        ]);
    }

    /**
     * @param list<float> $pageBbox
     * @return array{0: float, 1: float}
     */
    private function imageXObjectDisplayPoint(
        float $x,
        float $y,
        array $pageBbox,
        int $rotation,
        float $userUnit
    ): array {
        $width = max(0.0, $pageBbox[2] - $pageBbox[0]);
        $height = max(0.0, $pageBbox[3] - $pageBbox[1]);
        $x -= $pageBbox[0];
        $y -= $pageBbox[1];

        $mapped = match ($this->normalizedPageRotation($rotation)) {
            90 => [$y, $x],
            180 => [$width - $x, $y],
            270 => [$height - $y, $width - $x],
            default => [$x, $height - $y],
        };

        return [
            $mapped[0] * $userUnit,
            $mapped[1] * $userUnit,
        ];
    }

    /**
     * @param array<int, string> $objects
     * @return list<float>|null
     */
    private function topLevelPdfRectangleValueAfterName(string $objectBody, string $name, array $objects): ?array
    {
        $value = $this->topLevelPdfValueAfterName($objectBody, $name);
        if ($value === null) {
            return null;
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);
        if ($arrayBody === null) {
            return null;
        }

        $numbers = $this->numbersFromPdfArrayResolvingObjects($arrayBody, $objects);
        if (count($numbers) < 4) {
            return null;
        }

        return $this->normalizedPdfReviewNumbers([
            min($numbers[0], $numbers[2]),
            min($numbers[1], $numbers[3]),
            max($numbers[0], $numbers[2]),
            max($numbers[1], $numbers[3]),
        ]);
    }

    /**
     * @param list<float> $mediaBox
     * @param list<float> $cropBox
     * @return list<float>
     */
    private function pdfPageBoundaryIntersection(array $mediaBox, array $cropBox): array
    {
        $left = max($mediaBox[0], min($mediaBox[2], $cropBox[0]));
        $right = max($mediaBox[0], min($mediaBox[2], $cropBox[2]));
        $bottom = max($mediaBox[1], min($mediaBox[3], $cropBox[1]));
        $top = max($mediaBox[1], min($mediaBox[3], $cropBox[3]));

        return $this->normalizedPdfReviewNumbers([
            min($left, $right),
            min($bottom, $top),
            max($left, $right),
            max($bottom, $top),
        ]);
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     */
    private function pdfRectanglesHavePositiveIntersection(array $left, array $right): bool
    {
        return min($left[2], $right[2]) - max($left[0], $right[0]) > 0.000001
            && min($left[3], $right[3]) - max($left[1], $right[1]) > 0.000001;
    }

    /**
     * @param array<int, string> $objects
     */
    private function pageResourceDictionaryBlocksFallback(int $pageObjectNumber, array $objects): bool
    {
        $lineage = $this->pageObjectLineageResolution($pageObjectNumber, $objects);
        foreach ($lineage['lineage'] as $objectNumber) {
            $resolution = $this->pageResourceDictionaryResolution($objects[$objectNumber], $objects);
            if ($resolution['state'] === 'resolved') {
                return false;
            }

            if ($resolution['state'] === 'blocked') {
                return true;
            }
        }

        return $lineage['blocked'];
    }

    /**
     * @param array<int, string> $objects
     * @return array{state: 'inherit'}|array{state: 'blocked'}|array{state: 'resolved', body: string, object: int|null, generation: int|null}
     */
    private function pageResourceDictionaryResolution(string $objectBody, array $objects): array
    {
        $value = $this->topLevelPdfValueAfterName($objectBody, 'Resources');
        if ($value === null) {
            return ['state' => 'inherit'];
        }

        $value = trim($value);
        if ($value === '' || $value === 'null') {
            return ['state' => 'inherit'];
        }

        if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', $value, $match) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $resolved = $this->resolvedResourceObjectBody($objects, $objectNumber, $generation);
            if ($resolved === null) {
                return ['state' => 'blocked'];
            }

            $objectBody = $resolved['body'];
            if ($this->objectBodyIsStreamObject($objectBody)) {
                return ['state' => 'blocked'];
            }

            if (trim($objectBody) === 'null') {
                return ['state' => 'inherit'];
            }

            $body = $this->dictionaryObjectBody($objectBody);
            return $body === null
                ? ['state' => 'blocked']
                : [
                    'state' => 'resolved',
                    'body' => $body,
                    'object' => $resolved['object'],
                    'generation' => $resolved['generation'],
                ];
        }

        if (str_starts_with($value, '<<')) {
            $body = $this->readPdfDictionaryAt($value, 0);
            return $body === null
                ? ['state' => 'blocked']
                : ['state' => 'resolved', 'body' => $body, 'object' => null, 'generation' => null];
        }

        return ['state' => 'blocked'];
    }

    /**
     * @param array<int, string> $objects
     */
    private function resourceDictionaryBody(string $objectBody, array $objects): ?string
    {
        $value = $this->topLevelPdfValueAfterName($objectBody, 'Resources');
        if ($value === null) {
            return null;
        }

        $value = trim($value);
        if ($value === '' || $value === 'null') {
            return null;
        }

        if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', $value, $match) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $resolved = $this->resolvedResourceObjectBody($objects, $objectNumber, $generation);
            if ($resolved === null || $this->objectBodyIsStreamObject($resolved['body'])) {
                return null;
            }

            return $this->dictionaryObjectBody($resolved['body']);
        }

        return str_starts_with($value, '<<') ? $this->readPdfDictionaryAt($value, 0) : null;
    }

    /**
     * @param array<int, string> $objects
     * @param array<string, true> $seen
     * @return array{body: string, object: int, generation: int}|null
     */
    private function resolvedResourceObjectBody(
        array $objects,
        int $objectNumber,
        int $generation,
        array $seen = []
    ): ?array {
        $referenceKey = $objectNumber . ':' . $generation;
        if (isset($seen[$referenceKey])) {
            return null;
        }

        $body = $this->objectBodyForResourceReference($objects, $objectNumber, $generation);
        if ($body === null) {
            return null;
        }

        $seen[$referenceKey] = true;
        $trimmed = trim($body);
        if (preg_match('/^(\d+)\s+(\d+)\s+R\s*$/s', $trimmed, $match) === 1) {
            return $this->resolvedResourceObjectBody(
                $objects,
                (int) $match[1],
                (int) $match[2],
                $seen
            );
        }

        return [
            'body' => $body,
            'object' => $objectNumber,
            'generation' => $generation,
        ];
    }

    /**
     * @return array<string, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}>
     * @param array<int, string> $objects
     * @param array<int, array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}> $fontObjectMaps
     */
    private function fontResourceMapsFromResourceDictionary(string $resourceDictionary, array $objects, array $fontObjectMaps): array
    {
        $fontDictionary = $this->fontResourceDictionaryBody($resourceDictionary, $objects);
        if ($fontDictionary === null) {
            return [];
        }

        $maps = [];
        $namedCMapBodies = $this->namedCMapBodies($objects);
        if (preg_match_all('/\/([^\s\[\]()<>{}\/%]+)\s+(\d+)\s+(\d+)\s+R\b/', $fontDictionary, $resourceMatches, PREG_SET_ORDER)) {
            foreach ($resourceMatches as $resourceMatch) {
                $fontObjectNumber = (int) $resourceMatch[2];
                $fontGeneration = (int) $resourceMatch[3];
                $fontBody = $this->objectBodyForResourceReference($objects, $fontObjectNumber, $fontGeneration);
                if ($fontBody === null || $this->objectBodyIsStreamObject($fontBody)) {
                    continue;
                }

                $map = isset($objects[$fontObjectNumber], $fontObjectMaps[$fontObjectNumber]) && $objects[$fontObjectNumber] === $fontBody
                    ? $fontObjectMaps[$fontObjectNumber]
                    : $this->fontMapFromFontBody($fontBody, $objects, $namedCMapBodies);
                if ($map !== null) {
                    $maps[$this->decodePdfName($resourceMatch[1])] = $map;
                }
            }
        }

        foreach ($this->directFontResourceDictionaries($fontDictionary) as $name => $fontBody) {
            if (isset($maps[$name])) {
                continue;
            }

            $map = $this->fontMapFromFontBody($fontBody, $objects, $namedCMapBodies);
            if ($map !== null) {
                $maps[$name] = $map;
            }
        }

        return $maps;
    }

    /**
     * @return array<string, string>
     */
    private function directFontResourceDictionaries(string $fontDictionary): array
    {
        $fonts = [];
        $offset = 0;
        $length = strlen($fontDictionary);

        while ($offset < $length) {
            $this->skipContentWhitespaceAndComments($fontDictionary, $offset);
            if ($offset >= $length) {
                break;
            }

            if ($fontDictionary[$offset] !== '/') {
                $offset++;
                continue;
            }

            $nameStart = $offset + 1;
            $nameEnd = $nameStart;
            while ($nameEnd < $length && !str_contains(" \t\r\n\f[]()<>{}/%", $fontDictionary[$nameEnd])) {
                $nameEnd++;
            }
            if ($nameEnd === $nameStart) {
                $offset++;
                continue;
            }

            $name = $this->decodePdfName(substr($fontDictionary, $nameStart, $nameEnd - $nameStart));
            $valueOffset = $nameEnd;
            $this->skipContentWhitespaceAndComments($fontDictionary, $valueOffset);
            if ($valueOffset >= $length) {
                break;
            }

            if (preg_match('/\G\d+\s+\d+\s+R\b/s', $fontDictionary, $match, 0, $valueOffset) === 1) {
                $offset = $valueOffset + strlen($match[0]);
                continue;
            }

            if (substr($fontDictionary, $valueOffset, 2) !== '<<') {
                $nextOffset = $this->skipPdfValueAt($fontDictionary, $valueOffset);
                $offset = $nextOffset > $valueOffset ? $nextOffset : $valueOffset + 1;
                continue;
            }

            $dictionaryOffset = $valueOffset;
            $dictionary = $this->readPdfDictionaryTokenAt($fontDictionary, $dictionaryOffset);
            if ($dictionary === null) {
                $offset = $valueOffset + 2;
                continue;
            }

            if ($this->bodyMayContainFontDictionary($dictionary)) {
                $fonts[$name] = $dictionary;
            }
            $offset = $dictionaryOffset;
        }

        return $fonts;
    }

    /**
     * @return array<string, array{actualText: string|null, altText: string|null}>
     * @param array<int, string> $objects
     */
    private function markedContentPropertiesFromResourceDictionary(string $resourceDictionary, array $objects): array
    {
        $propertiesDictionary = $this->propertiesResourceDictionaryBody($resourceDictionary, $objects);
        if ($propertiesDictionary === null) {
            return [];
        }

        $properties = [];
        if (preg_match_all(
            '/\/([^\s\[\]()<>{}\/%]+)\s*(?:(\d+)\s+(\d+)\s+R|<<)/s',
            $propertiesDictionary,
            $matches,
            PREG_SET_ORDER | PREG_OFFSET_CAPTURE
        ) !== false) {
            foreach ($matches as $match) {
                $name = $this->decodePdfName($match[1][0]);
                if (($match[2][0] ?? '') !== '') {
                    $objectNumber = (int) $match[2][0];
                    $generation = (int) ($match[3][0] ?? '0');
                    $objectBody = $this->objectBodyForResourceReference($objects, $objectNumber, $generation);
                    $dictionary = $objectBody === null || $this->objectBodyIsStreamObject($objectBody)
                        ? null
                        : $this->dictionaryObjectBody($objectBody);
                } else {
                    $offset = strpos($propertiesDictionary, '<<', $match[0][1]);
                    $dictionary = $offset === false ? null : $this->readPdfDictionaryAt($propertiesDictionary, $offset);
                }

                if ($dictionary === null) {
                    continue;
                }

                $properties[$name] = [
                    'actualText' => $this->pdfOptionalStringValueAfterName($dictionary, 'ActualText', $objects),
                    'altText' => $this->pdfOptionalStringValueAfterName($dictionary, 'Alt', $objects),
                ];
            }
        }

        return $properties;
    }

    /**
     * @param array<int, string> $objects
     */
    private function propertiesResourceDictionaryBody(string $resourceDictionary, array $objects): ?string
    {
        return $this->resourceCategoryDictionaryBody($resourceDictionary, $objects, 'Properties');
    }

    /**
     * @param array<int, string> $objects
     * @return array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}|null
     */
    private function fontEncodingMap(string $fontBody, array $objects = []): ?array
    {
        $encodingObject = $this->objectBodyForExactReferenceAfterName($fontBody, 'Encoding', $objects);
        if ($encodingObject !== null) {
            $encodingObject = trim($encodingObject);
            if (preg_match('/^\/([^\s\[\]()<>{}\/%]+)/', $encodingObject, $match) === 1) {
                return $this->namedEncodingMap($this->decodePdfName($match[1]));
            }

            if (str_starts_with($encodingObject, '<<')) {
                $objectEncoding = $this->fontEncodingMap($encodingObject, $objects);
                if ($objectEncoding !== null) {
                    return $objectEncoding;
                }
            }
        }

        $baseEncoding = null;
        $baseEncodingName = $this->pdfNameValueAfterNameResolvingObjects($fontBody, 'BaseEncoding', $objects);
        if ($baseEncodingName !== null) {
            $baseEncoding = $this->namedEncodingMap($baseEncodingName);
        }

        $differencesArray = $this->pdfArrayValueAfterNameResolvingObjects($fontBody, 'Differences', $objects);
        if ($differencesArray !== null) {
            $differences = $this->encodingDifferencesMap($differencesArray);
            if ($baseEncoding !== null) {
                $baseEncoding['map'] = array_replace($baseEncoding['map'], $differences['map']);
                return $baseEncoding;
            }

            return $differences;
        }

        if ($baseEncoding !== null) {
            return $baseEncoding;
        }

        $encodingName = $this->pdfNameValueAfterNameResolvingObjects($fontBody, 'Encoding', $objects);
        if ($encodingName !== null) {
            return $this->namedEncodingMap($encodingName);
        }

        return $this->implicitBaseFontEncodingMap($fontBody);
    }

    /**
     * @return array{cidMap: array<string, int>, codeSpaceRanges: list<array{start: int, end: int, width: int}>, cidRanges?: list<array{start: int, end: int, width: int, cid: int, overwrite: bool}>, writingMode?: int}|null
     * @param array<int, string> $objects
     * @param array<string, string> $namedCMapBodies
     */
    private function fontCidEncodingMap(string $fontBody, array $objects, array $namedCMapBodies): ?array
    {
        if (preg_match('/\/Subtype\s*\/Type0\b/s', $fontBody) !== 1 && !$this->isType3FontBody($fontBody)) {
            return null;
        }

        if (preg_match('/\/Encoding\s+\/([^\s\[\]()<>{}\/%]+)/s', $fontBody, $nameMatch) === 1) {
            return $this->cidEncodingMapFromNamedCMap($this->decodePdfName($nameMatch[1]), $namedCMapBodies);
        }

        $encodingReference = $this->objectReferenceAfterName($fontBody, 'Encoding');
        if ($encodingReference === null) {
            return null;
        }

        $encodingObject = $this->objectBodyForExactReference(
            $objects,
            $encodingReference['objectNumber'],
            $encodingReference['generation']
        );
        if ($encodingObject === null) {
            return null;
        }

        $decoded = $this->decodedCMapBodyForParsing($encodingObject, $objects);
        if ($decoded === null) {
            $encodingObject = trim($encodingObject);
            if (preg_match('/^\/([^\s\[\]()<>{}\/%]+)/', $encodingObject, $nameMatch) === 1) {
                return $this->cidEncodingMapFromNamedCMap($this->decodePdfName($nameMatch[1]), $namedCMapBodies);
            }

            return null;
        }

        $rawDecoded = $this->decodedCMapBody($encodingObject, $objects);
        $currentName = is_string($rawDecoded) ? $this->cMapName($rawDecoded) : $this->cMapName($decoded);

        return $this->parseCidCMap($decoded, $namedCMapBodies, $currentName === null ? [] : [$currentName]);
    }

    /**
     * @return array{cidMap: array<string, int>, codeSpaceRanges: list<array{start: int, end: int, width: int}>, cidRanges?: list<array{start: int, end: int, width: int, cid: int, overwrite: bool}>, writingMode?: int}|null
     * @param array<string, string> $namedCMapBodies
     */
    private function cidEncodingMapFromNamedCMap(string $encodingName, array $namedCMapBodies): ?array
    {
        $cmap = $namedCMapBodies[$encodingName] ?? null;
        if ($cmap !== null) {
            return $this->parseCidCMap($cmap, $namedCMapBodies, [$encodingName]);
        }

        return $this->predefinedCidCMap($encodingName);
    }

    /**
     * @return array{name: string|null, flags: int|null, weight: float|null}
     * @param array<int, string> $objects
     */
    private function fontDescriptorInfo(string $fontBody, array $objects): array
    {
        $name = $this->pdfNameValueAfterName($fontBody, 'BaseFont');
        $flags = null;
        $weight = null;

        foreach ([$fontBody, ...$this->descendantFontBodies($fontBody, $objects)] as $body) {
            $descriptor = $this->fontDescriptorBody($body, $objects);
            if ($descriptor === null) {
                continue;
            }

            $descriptorName = $this->pdfNameValueAfterNameResolvingObjects($descriptor, 'FontName', $objects);
            if ($descriptorName !== null && $descriptorName !== '') {
                $name = $descriptorName;
            }

            $descriptorFlags = $this->pdfIntegerValueAfterNameResolvingObjects($descriptor, 'Flags', $objects);
            if ($descriptorFlags !== null) {
                $flags = $descriptorFlags;
            }

            $descriptorWeight = $this->pdfNumberValueAfterNameResolvingObjects($descriptor, 'FontWeight', $objects);
            if ($descriptorWeight !== null) {
                $weight = $descriptorWeight;
            }
        }

        if ($weight === null && $flags !== null && ($flags & (1 << 18)) !== 0) {
            $weight = 700.0;
        }

        return [
            'name' => $name,
            'flags' => $flags,
            'weight' => $weight,
        ];
    }

    /**
     * @return array{widths: array<int, float>, defaultWidth: float|null, cidSet: array<int, true>|null, verticalDisplacements: array<int, float>, defaultVerticalDisplacement: float|null}
     * @param array<int, string> $objects
     */
    private function fontWidthMetrics(string $fontBody, array $objects): array
    {
        $widths = [];
        $defaultWidth = null;
        $cidSet = null;
        $hasWidthArray = false;
        $hasCidFontBody = false;
        $verticalDisplacements = [];
        $defaultVerticalDisplacement = null;
        $hasVerticalWidthArray = false;

        foreach ($this->type3CharProcWidths($fontBody, $objects) as $code => $width) {
            $metric = $this->finiteFontAdvanceMetric($width);
            if ($metric !== null) {
                $widths[$code] = $metric;
            }
        }

        foreach ([$fontBody, ...$this->descendantFontBodies($fontBody, $objects)] as $body) {
            if ($this->isCidFontBody($body)) {
                $hasCidFontBody = true;
            }

            $bodyIsType3Font = $this->isType3FontBody($body);
            $simpleWidths = $this->simpleFontWidthMetrics($body, $objects);
            foreach ($simpleWidths as $code => $width) {
                $metric = $this->finiteFontAdvanceMetric($width);
                if ($metric === null) {
                    continue;
                }
                if ($bodyIsType3Font && array_key_exists((int) $code, $widths)) {
                    continue;
                }

                $widths[$code] = $metric;
            }

            if ($this->isSimpleFontBody($body)) {
                $missingWidth = $this->finiteFontAdvanceMetric($this->fontDescriptorMissingWidth($body, $objects));
                if ($missingWidth !== null) {
                    $defaultWidth = $missingWidth;
                } elseif ($simpleWidths !== [] && !$bodyIsType3Font) {
                    $defaultWidth = $this->averagePositiveFontWidth($simpleWidths) ?? $defaultWidth;
                }
            }

            $widthArray = $this->pdfArrayValueAfterNameResolvingObjects($body, 'W', $objects);
            if ($widthArray !== null) {
                $hasWidthArray = true;
                foreach ($this->cidWidthsFromWArray($widthArray, $objects) as $cid => $width) {
                    $widths[$cid] = $width;
                }
            }

            $bodyDefaultWidth = $this->finiteFontAdvanceMetric($this->pdfNumberValueAfterNameResolvingObjects($body, 'DW', $objects));
            if ($bodyDefaultWidth !== null) {
                $defaultWidth = $bodyDefaultWidth;
            }

            $verticalWidthArray = $this->pdfArrayValueAfterNameResolvingObjects($body, 'W2', $objects);
            if ($verticalWidthArray !== null) {
                $hasVerticalWidthArray = true;
                foreach ($this->cidVerticalDisplacementsFromW2Array($verticalWidthArray, $objects) as $cid => $displacement) {
                    $verticalDisplacements[$cid] = $displacement;
                }
            }

            $verticalDefaultMetrics = $this->pdfArrayValueAfterNameResolvingObjects($body, 'DW2', $objects);
            if ($verticalDefaultMetrics !== null) {
                $metrics = $this->numbersFromPdfArrayResolvingObjects($verticalDefaultMetrics, $objects);
                if (count($metrics) >= 2) {
                    $metric = $this->finiteFontAdvanceMetric((float) $metrics[1]);
                    if ($metric !== null) {
                        $defaultVerticalDisplacement = $metric;
                    }
                }
            }

            $bodyCidSet = $this->cidSetFromFontBody($body, $objects);
            if ($bodyCidSet !== null) {
                $cidSet = $cidSet === null ? $bodyCidSet : ($cidSet + $bodyCidSet);
            }
        }

        if (($hasCidFontBody || $hasWidthArray || $cidSet !== null) && $defaultWidth === null) {
            $defaultWidth = 1000.0;
        }
        if ($hasVerticalWidthArray && $defaultVerticalDisplacement === null) {
            $defaultVerticalDisplacement = -1000.0;
        }

        return [
            'widths' => $widths,
            'defaultWidth' => $defaultWidth,
            'cidSet' => $cidSet,
            'verticalDisplacements' => $verticalDisplacements,
            'defaultVerticalDisplacement' => $defaultVerticalDisplacement,
        ];
    }

    /**
     * @return array<int, float>
     * @param array<int, string> $objects
     */
    private function type3CharProcWidths(string $fontBody, array $objects): array
    {
        if (!$this->isType3FontBody($fontBody)) {
            return [];
        }

        $glyphNamesByCode = $this->type3EncodingGlyphNamesByCode($fontBody, $objects);
        $charProcObjectReferences = $this->charProcObjectReferences($fontBody, $objects);
        if ($glyphNamesByCode === [] || $charProcObjectReferences === []) {
            return [];
        }

        $fontMatrix = $this->type3FontMatrix($fontBody, $objects);
        $widths = [];
        foreach ($glyphNamesByCode as $code => $glyphName) {
            $reference = $charProcObjectReferences[$glyphName] ?? null;
            if ($reference === null) {
                continue;
            }

            $objectBody = $this->objectBodyForExactReference($objects, $reference['objectNumber'], $reference['generation']);
            if ($objectBody === null) {
                continue;
            }

            $widthVector = $this->type3CharProcDeclaredWidthVector($objectBody, $objects);
            if ($widthVector !== null) {
                $widths[$code] = $this->type3FontMatrixWidthVectorAdvance($widthVector, $fontMatrix);
            }
        }

        return $widths;
    }

    /**
     * @return list<float>
     * @param array<int, string> $objects
     */
    private function type3FontMatrix(string $fontBody, array $objects): array
    {
        $matrix = $this->topLevelPdfMatrixValueAfterName($fontBody, 'FontMatrix', $objects);
        if ($matrix === null) {
            return [0.001, 0.0, 0.0, 0.001, 0.0, 0.0];
        }

        return $matrix;
    }

    /**
     * @param list<float> $widthVector
     * @param list<float> $fontMatrix
     */
    private function type3FontMatrixWidthVectorAdvance(array $widthVector, array $fontMatrix): float
    {
        $wx = $widthVector[0] ?? 0.0;
        $wy = $widthVector[1] ?? 0.0;
        $advanceX = ($wx * ($fontMatrix[0] ?? 0.001)) + ($wy * ($fontMatrix[2] ?? 0.0));

        return is_finite($advanceX) && abs($advanceX) > 0.0 ? abs($advanceX) * 1000.0 : abs($wx);
    }

    /**
     * @param list<float> $fontMatrix
     */
    private function type3FontMatrixScalarWidthExtentAdvance(float $width, array $fontMatrix): float
    {
        $advanceX = $width * ($fontMatrix[0] ?? 0.001);
        $advanceY = $width * ($fontMatrix[1] ?? 0.0);
        $advance = sqrt(($advanceX * $advanceX) + ($advanceY * $advanceY));

        return is_finite($advance) && $advance > 0.0 ? $advance * 1000.0 : abs($width);
    }

    /**
     * @return array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}|null
     * @param array<int, string> $objects
     * @param array{cidMap: array<string, int>, codeSpaceRanges: list<array{start: int, end: int, width: int}>, writingMode?: int}|null $cidEncodingMap
     */
    private function type3CharProcUnicodeMap(string $fontBody, array $objects, ?array $cidEncodingMap): ?array
    {
        if (!$this->isType3FontBody($fontBody) || preg_match('/\/ToUnicode\b/s', $fontBody) === 1) {
            return null;
        }

        $unicodeByGlyphName = $this->type3StandardCharProcUnicodeByName($fontBody, $objects);
        if ($unicodeByGlyphName === null) {
            return null;
        }

        $map = [];
        foreach ($this->type3EncodingGlyphNamesByCode($fontBody, $objects) as $code => $glyphName) {
            if (!isset($unicodeByGlyphName[$glyphName])) {
                continue;
            }

            $map[str_pad(strtolower(dechex($code)), 2, '0', STR_PAD_LEFT)] = $unicodeByGlyphName[$glyphName];
        }

        $codeSpaceRanges = [
            ['start' => 0, 'end' => 255, 'width' => 2],
        ];
        if ($cidEncodingMap !== null && $cidEncodingMap['codeSpaceRanges'] !== []) {
            $codeSpaceRanges = $cidEncodingMap['codeSpaceRanges'];
        }

        if ($cidEncodingMap !== null && $cidEncodingMap['cidMap'] !== []) {
            $unicodeByCodepoint = [];
            foreach ($unicodeByGlyphName as $unicode) {
                $codepoint = $this->singleUnicodeCodepoint($unicode);
                if ($codepoint !== null) {
                    $unicodeByCodepoint[$codepoint] = $unicode;
                }
            }

            foreach ($cidEncodingMap['cidMap'] as $sourceKey => $cid) {
                if (isset($unicodeByCodepoint[$cid])) {
                    $map[$this->normalizeHexKey((string) $sourceKey)] = $unicodeByCodepoint[$cid];
                }
            }
        }

        if ($map === []) {
            return null;
        }

        return [
            'map' => $map,
            'codeSpaceRanges' => $codeSpaceRanges,
        ];
    }

    /**
     * @return array<string, string>|null
     * @param array<int, string> $objects
     */
    private function type3StandardCharProcUnicodeByName(string $fontBody, array $objects): ?array
    {
        $charProcObjectReferences = $this->charProcObjectReferences($fontBody, $objects);
        if ($charProcObjectReferences === []) {
            return null;
        }

        $unicodeByName = [];
        foreach (array_keys($charProcObjectReferences) as $glyphName) {
            $unicode = $this->glyphNameToUnicode($glyphName);
            if ($unicode === '') {
                continue;
            }

            $unicodeByName[$glyphName] = $unicode;
        }

        return $unicodeByName === [] ? null : $unicodeByName;
    }

    /**
     * @return array<int, string>
     * @param array<int, string> $objects
     */
    private function type3EncodingGlyphNamesByCode(string $fontBody, array $objects): array
    {
        $glyphNames = $this->baseEncodingGlyphNamesByCode($fontBody, $objects);
        $differences = $this->encodingDifferencesGlyphNames($fontBody, $objects);

        if ($glyphNames === []) {
            $glyphNames = $this->namedEncodingGlyphNamesByCode('StandardEncoding');
        }

        return $differences === [] ? $glyphNames : array_replace($glyphNames, $differences);
    }

    /**
     * @return array<int, string>
     * @param array<int, string> $objects
     */
    private function baseEncodingGlyphNamesByCode(string $fontBody, array $objects): array
    {
        $encodingObject = $this->objectBodyForExactReferenceAfterName($fontBody, 'Encoding', $objects);
        if ($encodingObject !== null) {
            $encodingObject = trim($encodingObject);
            if (preg_match('/^\/([^\s\[\]()<>{}\/%]+)/', $encodingObject, $match) === 1) {
                return $this->namedEncodingGlyphNamesByCode($this->decodePdfName($match[1]));
            }

            if (str_starts_with($encodingObject, '<<')) {
                return $this->baseEncodingGlyphNamesByCode($encodingObject, $objects);
            }
        }

        $baseEncodingName = $this->pdfNameValueAfterNameResolvingObjects($fontBody, 'BaseEncoding', $objects);
        if ($baseEncodingName !== null) {
            return $this->namedEncodingGlyphNamesByCode($baseEncodingName);
        }

        $encodingName = $this->pdfNameValueAfterNameResolvingObjects($fontBody, 'Encoding', $objects);
        if ($encodingName !== null) {
            return $this->namedEncodingGlyphNamesByCode($encodingName);
        }

        return [];
    }

    /**
     * @return array<int, string>
     * @param array<int, string> $objects
     */
    private function encodingDifferencesGlyphNames(string $fontBody, array $objects = []): array
    {
        $encodingObject = $this->objectBodyForExactReferenceAfterName($fontBody, 'Encoding', $objects);
        if ($encodingObject !== null) {
            $encodingObject = trim($encodingObject);
            if (str_starts_with($encodingObject, '<<')) {
                $objectGlyphNames = $this->encodingDifferencesGlyphNames($encodingObject, $objects);
                if ($objectGlyphNames !== []) {
                    return $objectGlyphNames;
                }
            }
        }

        $differences = $this->pdfArrayValueAfterNameResolvingObjects($fontBody, 'Differences', $objects);
        if ($differences === null) {
            return [];
        }

        preg_match_all('/\/[^\s\[\]()<>{}\/%]+|[+-]?\d+/', $differences, $tokens);
        $glyphNames = [];
        $code = null;
        foreach ($tokens[0] ?? [] as $token) {
            if (preg_match('/^[+-]?\d+$/', $token) === 1) {
                $code = max(0, min(255, (int) $token));
                continue;
            }

            if ($code === null || !str_starts_with($token, '/')) {
                continue;
            }

            $glyphNames[$code] = $this->decodePdfName(substr($token, 1));
            $code++;
        }

        return $glyphNames;
    }

    /**
     * @return array<int, string>
     */
    private function namedEncodingGlyphNamesByCode(string $encodingName): array
    {
        if (!in_array($encodingName, ['WinAnsiEncoding', 'StandardEncoding', 'MacRomanEncoding'], true)) {
            return [];
        }

        $glyphNames = [
            0x20 => 'space',
            0x21 => 'exclam',
            0x22 => 'quotedbl',
            0x23 => 'numbersign',
            0x24 => 'dollar',
            0x25 => 'percent',
            0x26 => 'ampersand',
            0x27 => 'quotesingle',
            0x28 => 'parenleft',
            0x29 => 'parenright',
            0x2a => 'asterisk',
            0x2b => 'plus',
            0x2c => 'comma',
            0x2d => 'hyphen',
            0x2e => 'period',
            0x2f => 'slash',
            0x3a => 'colon',
            0x3b => 'semicolon',
            0x3c => 'less',
            0x3d => 'equal',
            0x3e => 'greater',
            0x3f => 'question',
            0x40 => 'at',
            0x5b => 'bracketleft',
            0x5c => 'backslash',
            0x5d => 'bracketright',
            0x5e => 'asciicircum',
            0x5f => 'underscore',
            0x60 => 'grave',
            0x7b => 'braceleft',
            0x7c => 'bar',
            0x7d => 'braceright',
            0x7e => 'asciitilde',
        ];

        for ($code = 0x30; $code <= 0x39; $code++) {
            $glyphNames[$code] = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'][$code - 0x30];
        }
        for ($code = 0x41; $code <= 0x5a; $code++) {
            $glyphNames[$code] = chr($code);
        }
        for ($code = 0x61; $code <= 0x7a; $code++) {
            $glyphNames[$code] = chr($code);
        }

        return $glyphNames;
    }

    /**
     * @return array<string, array{objectNumber: int, generation: int}>
     * @param array<int, string> $objects
     */
    private function charProcObjectReferences(string $fontBody, array $objects): array
    {
        $dictionary = $this->charProcsDictionaryBody($fontBody, $objects);
        if ($dictionary === null) {
            return [];
        }

        $references = [];
        $offset = 0;
        $length = strlen($dictionary);
        while ($offset < $length) {
            $this->skipContentWhitespaceAndComments($dictionary, $offset);
            if ($offset >= $length) {
                break;
            }

            if ($dictionary[$offset] !== '/') {
                $nextOffset = $this->skipPdfValueAt($dictionary, $offset);
                $offset = $nextOffset > $offset ? $nextOffset : $offset + 1;
                continue;
            }

            $nameStart = $offset + 1;
            $nameEnd = $nameStart;
            while ($nameEnd < $length && !str_contains(" \t\r\n\f[]()<>{}/%", $dictionary[$nameEnd])) {
                $nameEnd++;
            }

            if ($nameEnd === $nameStart) {
                $offset++;
                continue;
            }

            $valueOffset = $nameEnd;
            $this->skipContentWhitespaceAndComments($dictionary, $valueOffset);
            if ($valueOffset >= $length) {
                break;
            }

            $referenceOffset = $valueOffset;
            $reference = $this->readPdfIndirectReferenceToken($dictionary, $referenceOffset);
            if ($reference !== null) {
                $references[$this->decodePdfName(substr($dictionary, $nameStart, $nameEnd - $nameStart))] = [
                    'objectNumber' => $reference['objectNumber'],
                    'generation' => $reference['generation'],
                ];
                $offset = $referenceOffset;
                continue;
            }

            $nextOffset = $this->skipPdfValueAt($dictionary, $valueOffset);
            $offset = $nextOffset > $valueOffset ? $nextOffset : $valueOffset + 1;
        }

        return $references;
    }

    /**
     * @param array<int, string> $objects
     */
    private function charProcsDictionaryBody(string $fontBody, array $objects): ?string
    {
        $offset = $this->topLevelNameValueOffset($fontBody, 'CharProcs');
        if ($offset === null) {
            return null;
        }

        $referenceOffset = $offset;
        $reference = $this->readPdfIndirectReferenceToken($fontBody, $referenceOffset);
        if ($reference !== null) {
            $objectBody = $this->objectBodyForExactReference(
                $objects,
                $reference['objectNumber'],
                $reference['generation']
            );

            return $objectBody === null ? null : $this->dictionaryObjectBody($objectBody);
        }

        $offset = $this->skipPdfWhitespace($fontBody, $offset);
        return substr($fontBody, $offset, 2) === '<<' ? $this->readPdfDictionaryAt($fontBody, $offset) : null;
    }

    /**
     * @return list<float>|null
     * @param array<int, string> $objects
     */
    private function type3CharProcDeclaredWidthVector(string $objectBody, array $objects): ?array
    {
        $stream = $this->streamDictionaryAndPayload($objectBody, $objects);
        if ($stream !== null) {
            if ($this->isImageStreamDictionary($stream['dict'], $objects)) {
                return null;
            }

            $decoded = $this->decodeStream($stream['dict'], $stream['stream'], $objects);
            if ($decoded === null) {
                return null;
            }

            $charProc = $decoded;
        } else {
            $charProc = trim($objectBody);
        }
        $operands = [];
        $compatibilityDepth = 0;

        foreach ($this->contentTokens($charProc, true) as $token) {
            if ($token === 'BX') {
                $compatibilityDepth++;
                $operands = [];
                continue;
            }

            if ($compatibilityDepth > 0) {
                if ($token === 'EX') {
                    $compatibilityDepth--;
                }

                $operands = [];
                continue;
            }

            if ($token === 'd0') {
                if (count($operands) !== 2) {
                    return null;
                }

                $wx = $this->numericOperand($operands[0]);
                $wy = $this->numericOperand($operands[1]);

                return $wx === null || $wy === null ? null : [$wx, $wy];
            }

            if ($token === 'd1') {
                if (count($operands) !== 6) {
                    return null;
                }

                $wx = $this->numericOperand($operands[0]);
                $wy = $this->numericOperand($operands[1]);

                return $wx === null || $wy === null ? null : [$wx, $wy];
            }

            if ($this->isOperator($token)) {
                if (!$this->type3CharProcAllowsPreMetricSetupOperator($token, $operands)) {
                    return null;
                }

                $operands = [];
                continue;
            }

            $operands[] = $token;
        }

        return null;
    }

    /**
     * @param list<string> $operands
     */
    private function type3CharProcAllowsPreMetricSetupOperator(string $token, array $operands): bool
    {
        if (!in_array($token, [
            'q',
            'Q',
            'cm',
            'w',
            'J',
            'j',
            'M',
            'd',
            'ri',
            'i',
            'gs',
            'CS',
            'cs',
            'SC',
            'SCN',
            'sc',
            'scn',
            'G',
            'g',
            'RG',
            'rg',
            'K',
            'k',
            'Tc',
            'Tw',
            'Tz',
            'TL',
            'Tf',
            'Tr',
            'Ts',
            'm',
            'l',
            'c',
            'v',
            'y',
            'h',
            're',
            'W',
            'W*',
            'n',
            'MP',
            'DP',
            'BMC',
            'BDC',
            'EMC',
        ], true)) {
            return false;
        }

        if ($token === 'MP') {
            return count($operands) === 1 && $this->markedContentTagOperand($operands[0]);
        }

        if ($token === 'DP') {
            return count($operands) === 2
                && $this->markedContentTagOperand($operands[0])
                && $this->markedContentPropertyOperand($operands[1]);
        }

        if (in_array($token, ['Tc', 'Tw', 'Tz', 'TL', 'Tr', 'Ts'], true)) {
            return count($operands) === 1 && $this->numericOperand($operands[0]) !== null;
        }

        if ($token === 'Tf') {
            return count($operands) === 2
                && str_starts_with($operands[0], '/')
                && $this->numericOperand($operands[1]) !== null;
        }

        if ($token === 'BMC') {
            return count($operands) === 1 && str_starts_with($operands[0], '/');
        }

        if ($token === 'BDC') {
            return count($operands) === 2 && str_starts_with($operands[0], '/');
        }

        if ($token === 'EMC') {
            return count($operands) === 0;
        }

        return true;
    }

    /**
     * @return list<string>
     * @param array<int, string> $objects
     */
    private function descendantFontBodies(string $fontBody, array $objects): array
    {
        $descendantFonts = $this->pdfArrayValueAfterNameResolvingObjects($fontBody, 'DescendantFonts', $objects);
        if ($descendantFonts === null) {
            return [];
        }

        $bodies = [];
        foreach ($this->objectReferences($descendantFonts) as $objectNumber) {
            if (isset($objects[$objectNumber])) {
                $bodies[] = $objects[$objectNumber];
            }
        }

        $offset = 0;
        while (($offset = strpos($descendantFonts, '<<', $offset)) !== false) {
            $dictionary = $this->readPdfDictionaryAt($descendantFonts, $offset);
            $dictionaryEnd = $this->pdfDictionaryEndOffset($descendantFonts, $offset);
            if ($dictionary === null || $dictionaryEnd === null) {
                break;
            }
            $bodies[] = $dictionary;
            $offset = $dictionaryEnd + 1;
        }

        return $bodies;
    }

    /**
     * @return array<int, float>
     * @param array<int, string> $objects
     */
    private function simpleFontWidthMetrics(string $fontBody, array $objects): array
    {
        if (!$this->isSimpleFontBody($fontBody)) {
            return [];
        }

        $explicitWidths = $this->simpleFontExplicitWidths($fontBody, $objects);
        if ($explicitWidths !== []) {
            return $explicitWidths;
        }

        return $this->base14FontWidthMetrics($fontBody);
    }

    private function isSimpleFontBody(string $fontBody): bool
    {
        if (preg_match('/\/Subtype\s*\/Type0\b/s', $fontBody) === 1 || $this->isCidFontBody($fontBody)) {
            return false;
        }

        if (preg_match('/\/Subtype\s*\/(?:Type1|MMType1|TrueType)\b/s', $fontBody) === 1 || $this->isType3FontBody($fontBody)) {
            return true;
        }

        return $this->pdfNameValueAfterName($fontBody, 'BaseFont') !== null
            && $this->pdfArrayValueAfterName($fontBody, 'DescendantFonts') === null;
    }

    private function isCidFontBody(string $fontBody): bool
    {
        return preg_match('/\/Subtype\s*\/CIDFontType[02]\b/s', $fontBody) === 1;
    }

    private function isType3FontBody(string $fontBody): bool
    {
        $subtype = $this->topLevelPdfValueAfterName($fontBody, 'Subtype');
        if ($subtype === null) {
            return false;
        }

        return $this->pdfNameValueAt($subtype, 0, []) === 'Type3';
    }

    /**
     * @return array<int, float>
     * @param array<int, string> $objects
     */
    private function simpleFontExplicitWidths(string $fontBody, array $objects): array
    {
        $firstChar = $this->pdfNumberValueAfterNameResolvingObjects($fontBody, 'FirstChar', $objects);
        $firstCode = $this->simpleFontWidthRangeCode($firstChar);
        if ($firstCode === null) {
            return [];
        }

        $lastChar = $this->pdfNumberValueAfterNameResolvingObjects($fontBody, 'LastChar', $objects);
        $lastCode = $lastChar === null ? null : $this->simpleFontWidthRangeCode($lastChar);
        if ($lastChar !== null && ($lastCode === null || $lastCode < $firstCode)) {
            return [];
        }

        $widthArray = $this->pdfArrayValueAfterNameResolvingObjects($fontBody, 'Widths', $objects);
        if ($widthArray === null) {
            return [];
        }

        $widths = [];
        foreach ($this->nullableNumbersFromPdfArrayResolvingObjects($widthArray, $objects) as $offset => $width) {
            $metric = $this->finiteFontAdvanceMetric($width);
            if ($metric === null) {
                continue;
            }
            $code = $firstCode + $offset;
            if ($lastCode !== null && $code > $lastCode) {
                continue;
            }
            if ($code >= 0 && $code <= 255) {
                $widths[$code] = $metric;
            }
        }

        if ($widths !== [] && $this->isType3FontBody($fontBody)) {
            $fontMatrix = $this->type3FontMatrix($fontBody, $objects);
            $transformedWidths = [];
            foreach ($widths as $code => $width) {
                $metric = $this->finiteFontAdvanceMetric($this->type3FontMatrixScalarWidthExtentAdvance($width, $fontMatrix));
                if ($metric !== null) {
                    $transformedWidths[$code] = $metric;
                }
            }
            $widths = $transformedWidths;
        }

        return $widths;
    }

    private function finiteFontAdvanceMetric(?float $value): ?float
    {
        return $value !== null && is_finite($value) ? $value : null;
    }

    private function simpleFontWidthRangeCode(?float $value): ?int
    {
        if ($value === null || !is_finite($value)) {
            return null;
        }

        $code = (int) round($value);
        if (abs($value - $code) > 0.000001 || $code < 0 || $code > 255) {
            return null;
        }

        return $code;
    }

    /**
     * @param array<int, float> $widths
     */
    private function averagePositiveFontWidth(array $widths): ?float
    {
        $sum = 0.0;
        $count = 0;
        foreach ($widths as $width) {
            if (!is_finite($width) || $width <= 0.0) {
                continue;
            }

            $sum += $width;
            $count++;
        }

        return $count === 0 ? null : $sum / $count;
    }

    /**
     * @return list<float>
     * @param array<int, string> $objects
     */
    private function numbersFromPdfArrayResolvingObjects(string $arrayBody, array $objects): array
    {
        $numbers = [];
        foreach ($this->pdfArrayItems($arrayBody) as $item) {
            $number = $this->pdfNumberValueAt($item, 0, $objects);
            if ($number !== null) {
                $numbers[] = $number;
            }
        }

        return $numbers;
    }

    /**
     * @return list<float|null>
     * @param array<int, string> $objects
     */
    private function nullableNumbersFromPdfArrayResolvingObjects(string $arrayBody, array $objects): array
    {
        $numbers = [];
        foreach ($this->pdfArrayItems($arrayBody) as $item) {
            $numbers[] = $this->pdfNumberValueAt($item, 0, $objects);
        }

        return $numbers;
    }

    /**
     * @return array<int, float>
     */
    private function base14FontWidthMetrics(string $fontBody): array
    {
        $baseFont = $this->pdfNameValueAfterName($fontBody, 'BaseFont');
        if ($baseFont === null || $baseFont === '') {
            return [];
        }

        if (preg_match('/^[A-Z]{6}\+(.+)$/', $baseFont, $match) === 1) {
            $baseFont = $match[1];
        }

        $metricName = self::BASE14_FONT_WIDTH_ALIASES[$baseFont] ?? null;
        if ($metricName === null) {
            return [];
        }

        if ($metricName === 'Courier') {
            return array_fill_keys(range(32, 126), 600.0);
        }

        $widthString = self::BASE14_ASCII_WIDTHS[$metricName] ?? null;
        if ($widthString === null) {
            return [];
        }

        $widths = [];
        foreach (explode(' ', $widthString) as $offset => $width) {
            $code = 32 + $offset;
            if ($code > 126) {
                break;
            }
            $widths[$code] = (float) $width;
        }

        return $widths;
    }

    /**
     * @param array<int, string> $objects
     * @return array<int, float>
     */
    private function cidWidthsFromWArray(string $arrayBody, array $objects): array
    {
        $tokens = $this->pdfArrayItems($arrayBody);
        $widths = [];

        for ($index = 0, $count = count($tokens); $index < $count;) {
            $firstCid = $this->cidWidthArrayInteger($tokens[$index] ?? '', $objects);
            if ($firstCid === null) {
                $index++;
                continue;
            }
            $index++;

            $next = $tokens[$index] ?? null;
            if ($next === null) {
                break;
            }

            $widthList = $this->pdfArrayFromValue($next, $objects);
            if ($widthList !== null) {
                if ($firstCid < 0 || $firstCid > 0xffff) {
                    $index++;
                    continue;
                }

                foreach ($this->nullableNumbersFromPdfArrayResolvingObjects($widthList, $objects) as $offset => $width) {
                    $metric = $this->finiteFontAdvanceMetric($width);
                    if ($metric === null) {
                        continue;
                    }
                    $cid = $firstCid + $offset;
                    if ($cid >= 0 && $cid <= 0xffff) {
                        $widths[$cid] = $metric;
                    }
                }
                $index++;
                continue;
            }

            $lastCid = $this->cidWidthArrayInteger($next, $objects);
            $width = $this->finiteFontAdvanceMetric($this->pdfNumberValueAt($tokens[$index + 1] ?? '', 0, $objects));
            if ($lastCid === null || $width === null) {
                $index++;
                continue;
            }

            $index += 2;
            if ($firstCid < 0 || $lastCid < $firstCid) {
                continue;
            }

            for ($cid = $firstCid, $limit = min($lastCid, 0xffff); $cid <= $limit; $cid++) {
                $widths[$cid] = $width;
            }
        }

        return $widths;
    }

    /**
     * @param array<int, string> $objects
     */
    private function cidWidthArrayInteger(string $item, array $objects): ?int
    {
        $value = $this->pdfNumberValueAt($item, 0, $objects);
        if ($value === null || !is_finite($value)) {
            return null;
        }

        $integer = (int) round($value);
        return abs($value - $integer) > 0.000001 ? null : $integer;
    }

    /**
     * @return array<int, float>
     * @param array<int, string> $objects
     */
    private function cidVerticalDisplacementsFromW2Array(string $arrayBody, array $objects): array
    {
        $tokens = $this->pdfArrayItems($arrayBody);
        $displacements = [];

        for ($index = 0, $count = count($tokens); $index < $count;) {
            $firstCid = $this->cidWidthArrayInteger($tokens[$index] ?? '', $objects);
            if ($firstCid === null) {
                $index++;
                continue;
            }
            $index++;

            $next = $tokens[$index] ?? null;
            if ($next === null) {
                break;
            }

            $metricsList = $this->pdfArrayFromValue($next, $objects);
            if ($metricsList !== null) {
                if ($firstCid < 0 || $firstCid > 0xffff) {
                    $index++;
                    continue;
                }

                $metrics = $this->nullableNumbersFromPdfArrayResolvingObjects($metricsList, $objects);
                for ($offset = 0, $metricCount = count($metrics); $offset + 2 < $metricCount; $offset += 3) {
                    $verticalDisplacement = $this->finiteFontAdvanceMetric($metrics[$offset]);
                    $positionX = $this->finiteFontAdvanceMetric($metrics[$offset + 1]);
                    $positionY = $this->finiteFontAdvanceMetric($metrics[$offset + 2]);
                    if ($verticalDisplacement === null || $positionX === null || $positionY === null) {
                        continue;
                    }
                    $cid = $firstCid + intdiv($offset, 3);
                    if ($cid >= 0 && $cid <= 0xffff) {
                        $displacements[$cid] = $verticalDisplacement;
                    }
                }
                $index++;
                continue;
            }

            $lastCid = $this->cidWidthArrayInteger($next, $objects);
            $verticalDisplacement = $this->finiteFontAdvanceMetric($this->pdfNumberValueAt($tokens[$index + 1] ?? '', 0, $objects));
            $positionX = $this->finiteFontAdvanceMetric($this->pdfNumberValueAt($tokens[$index + 2] ?? '', 0, $objects));
            $positionY = $this->finiteFontAdvanceMetric($this->pdfNumberValueAt($tokens[$index + 3] ?? '', 0, $objects));
            if ($lastCid === null || $verticalDisplacement === null || $positionX === null || $positionY === null) {
                $index++;
                continue;
            }

            $index += 4;
            if ($firstCid < 0 || $lastCid < $firstCid) {
                continue;
            }

            for ($cid = $firstCid, $limit = min($lastCid, 0xffff); $cid <= $limit; $cid++) {
                $displacements[$cid] = $verticalDisplacement;
            }
        }

        return $displacements;
    }

    /**
     * @return array<int, true>|null
     * @param array<int, string> $objects
     */
    private function cidSetFromFontBody(string $fontBody, array $objects): ?array
    {
        $isCMapEncodedType3 = $this->isType3FontBody($fontBody) && $this->fontHasDecodedCMapEncoding($fontBody, $objects);
        if (!$this->isCidFontBody($fontBody) && !$isCMapEncodedType3) {
            return null;
        }

        $descriptor = $this->fontDescriptorBody($fontBody, $objects);
        if ($descriptor === null) {
            return null;
        }

        $cidSetReference = $this->objectReferenceAfterName($descriptor, 'CIDSet');
        if ($cidSetReference === null) {
            return null;
        }

        $cidSetObject = $this->indirectObjectBodyForReference(
            $objects,
            $cidSetReference['objectNumber'],
            $cidSetReference['generation']
        );
        if ($cidSetObject === null) {
            return null;
        }

        $decoded = $this->decodeStreamObject($cidSetObject, $objects);
        if ($decoded === null || $decoded === '') {
            return null;
        }

        return $this->cidSetBits($decoded);
    }

    /**
     * @param array<int, string> $objects
     */
    private function fontHasDecodedCMapEncoding(string $fontBody, array $objects): bool
    {
        $encodingObject = $this->objectBodyForExactReferenceAfterName($fontBody, 'Encoding', $objects);

        return $encodingObject !== null && $this->decodedCMapBody($encodingObject, $objects) !== null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function fontDescriptorBody(string $fontBody, array $objects): ?string
    {
        $descriptorObjectNumber = $this->objectReferenceValueAfterName($fontBody, 'FontDescriptor');
        if ($descriptorObjectNumber !== null) {
            return $objects[$descriptorObjectNumber] ?? null;
        }

        if (preg_match('/\/FontDescriptor\s*<</s', $fontBody, $match, PREG_OFFSET_CAPTURE) !== 1) {
            return null;
        }

        $offset = strpos($fontBody, '<<', $match[0][1]);
        return $offset === false ? null : $this->readPdfDictionaryAt($fontBody, $offset);
    }

    /**
     * @param array<int, string> $objects
     */
    private function fontDescriptorMissingWidth(string $fontBody, array $objects): ?float
    {
        $descriptor = $this->fontDescriptorBody($fontBody, $objects);
        if ($descriptor === null) {
            return null;
        }

        return $this->pdfNumberValueAfterNameResolvingObjects($descriptor, 'MissingWidth', $objects);
    }

    /**
     * @return array<int, true>|null
     */
    private function cidSetBits(string $bytes): ?array
    {
        $cids = [];
        for ($byteIndex = 0, $length = strlen($bytes); $byteIndex < $length; $byteIndex++) {
            $byte = ord($bytes[$byteIndex]);
            for ($bit = 0; $bit < 8; $bit++) {
                if (($byte & (1 << (7 - $bit))) === 0) {
                    continue;
                }

                $cid = ($byteIndex * 8) + $bit;
                if ($cid > 0xffff) {
                    break 2;
                }

                $cids[$cid] = true;
            }
        }

        return $cids === [] ? null : $cids;
    }

    private function integerToken(string $token): ?int
    {
        if (preg_match('/^[+-]?\d+$/', $token) !== 1) {
            return null;
        }

        return (int) $token;
    }

    /**
     * @param array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>} $map
     * @param array{widths: array<int, float>, defaultWidth: float|null, cidSet: array<int, true>|null, verticalDisplacements: array<int, float>, defaultVerticalDisplacement: float|null} $metrics
     * @return array<string, mixed>
     */
    private function withFontWidthMetrics(array $map, array $metrics, int $writingMode): array
    {
        if (
            $writingMode === 0
            && $metrics['widths'] === []
            && $metrics['defaultWidth'] === null
            && $metrics['cidSet'] === null
            && $metrics['verticalDisplacements'] === []
            && $metrics['defaultVerticalDisplacement'] === null
        ) {
            return $map;
        }

        $map['writingMode'] = $writingMode;
        $map['cidWidths'] = $metrics['widths'];
        $map['cidDefaultWidth'] = $metrics['defaultWidth'];
        $map['cidVerticalDisplacements'] = $metrics['verticalDisplacements'];
        $map['cidDefaultVerticalDisplacement'] = $writingMode === 1
            ? ($metrics['defaultVerticalDisplacement'] ?? -1000.0)
            : $metrics['defaultVerticalDisplacement'];
        if ($metrics['cidSet'] !== null) {
            $map['cidSet'] = $metrics['cidSet'];
        }

        return $map;
    }

    /**
     * @param array<string, mixed> $map
     * @param array{cidMap: array<string, int>, codeSpaceRanges: list<array{start: int, end: int, width: int}>, cidRanges?: list<array{start: int, end: int, width: int, cid: int, overwrite: bool}>, writingMode?: int}|null $cidEncodingMap
     * @return array<string, mixed>
     */
    private function withFontCidEncodingMap(array $map, ?array $cidEncodingMap): array
    {
        if ($cidEncodingMap === null) {
            return $map;
        }

        if ($cidEncodingMap['cidMap'] !== []) {
            $map['cidMap'] = $cidEncodingMap['cidMap'];
        }
        if ($cidEncodingMap['codeSpaceRanges'] !== []) {
            $map['cidCodeSpaceRanges'] = $cidEncodingMap['codeSpaceRanges'];
        }
        if (($cidEncodingMap['cidRanges'] ?? []) !== []) {
            $map['cidRanges'] = $cidEncodingMap['cidRanges'];
        }

        return $map;
    }

    /**
     * @param array<string, mixed> $map
     * @param array{name: string|null, flags: int|null, weight: float|null} $info
     * @return array<string, mixed>
     */
    private function withFontDescriptorInfo(array $map, array $info): array
    {
        if ($info['name'] !== null) {
            $map['fontName'] = $info['name'];
        }
        if ($info['flags'] !== null) {
            $map['fontFlags'] = $info['flags'];
        }
        if ($info['weight'] !== null) {
            $map['fontWeight'] = $info['weight'];
        }

        return $map;
    }

    /**
     * @param array<string, mixed> $cmap
     * @param array{cidMap: array<string, int>, codeSpaceRanges: list<array{start: int, end: int, width: int}>, cidRanges?: list<array{start: int, end: int, width: int, cid: int, overwrite: bool}>, writingMode?: int}|null $cidEncodingMap
     */
    private function fontWritingMode(string $fontBody, array $cmap, ?array $cidEncodingMap = null, array $objects = []): int
    {
        $encodingName = $this->pdfNameValueAfterNameResolvingObjects($fontBody, 'Encoding', $objects);
        if ($encodingName !== null) {
            $writingMode = $this->cMapNameWritingMode($encodingName);
            if ($writingMode !== null) {
                return $writingMode;
            }
        }

        if ($cidEncodingMap !== null && array_key_exists('writingMode', $cidEncodingMap)) {
            return (int) $cidEncodingMap['writingMode'] === 1 ? 1 : 0;
        }

        return $this->mapWritingMode($cmap);
    }

    private function cMapNameWritingMode(string $encodingName): ?int
    {
        if ($encodingName === 'Identity-V' || str_ends_with($encodingName, '-V')) {
            return 1;
        }

        if ($encodingName === 'Identity-H' || str_ends_with($encodingName, '-H')) {
            return 0;
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function fontResourceDictionaryBody(string $resourceDictionary, array $objects): ?string
    {
        return $this->resourceCategoryDictionaryBody($resourceDictionary, $objects, 'Font');
    }

    /**
     * @param array<int, string> $objects
     */
    private function resourceCategoryDictionaryBody(string $resourceDictionary, array $objects, string $category): ?string
    {
        $dictionary = trim($resourceDictionary);
        if (str_starts_with($dictionary, '<<')) {
            $dictionary = $this->readPdfDictionaryAt($dictionary, 0);
            if ($dictionary === null) {
                return null;
            }
        }

        $value = $this->topLevelPdfValueAfterNameInDictionaryBody($dictionary, $category);
        if ($value === null) {
            return null;
        }

        $value = trim($value);
        if (preg_match('/^(\d+)\s+(\d+)\s+R\b/s', $value, $match) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $resolved = $this->resolvedResourceObjectBody($objects, $objectNumber, $generation);
            if ($resolved === null || $this->objectBodyIsStreamObject($resolved['body'])) {
                return null;
            }

            return $this->dictionaryObjectBody($resolved['body']);
        }

        return str_starts_with($value, '<<') ? $this->readPdfDictionaryAt($value, 0) : null;
    }

    private function dictionaryObjectBody(string $objectBody): ?string
    {
        $offset = strpos($objectBody, '<<');
        return $offset === false ? null : $this->readPdfDictionaryAt($objectBody, $offset);
    }

    private function objectBodyIsStreamObject(string $objectBody): bool
    {
        $offset = $this->skipPdfWhitespace($objectBody, 0);
        $dictionaryEnd = $offset;
        if ($this->readPdfDictionaryTokenAt($objectBody, $dictionaryEnd) === null) {
            return false;
        }

        $streamOffset = $this->skipPdfWhitespace($objectBody, $dictionaryEnd);
        return $this->pdfKeywordAt($objectBody, $streamOffset, 'stream');
    }

    private function readPdfDictionaryAt(string $value, int $offset): ?string
    {
        return $this->readPdfDictionaryTokenAt($value, $offset);
    }

    private function readPdfDictionaryTokenAt(string $value, int &$offset): ?string
    {
        if (substr($value, $offset, 2) !== '<<') {
            return null;
        }

        $depth = 0;
        $bodyStart = $offset + 2;
        $index = $offset;
        $length = strlen($value);
        while ($index < $length - 1) {
            if ($value[$index] === '%') {
                $this->skipPdfComment($value, $index);
                continue;
            }

            if ($value[$index] === '(') {
                $this->readLiteralToken($value, $index);
                continue;
            }

            if ($value[$index] === '<' && $value[$index + 1] !== '<') {
                $this->readHexToken($value, $index);
                continue;
            }

            $pair = substr($value, $index, 2);
            if ($pair === '<<') {
                $depth++;
                $index += 2;
                continue;
            }

            if ($pair === '>>') {
                $depth--;
                $index += 2;
                if ($depth === 0) {
                    $offset = $index;
                    return substr($value, $bodyStart, $index - 2 - $bodyStart);
                }
                continue;
            }

            $index++;
        }

        return null;
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfStringValueAfterName(string $body, string $name, array $objects): ?string
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        return $this->pdfStringTokenAt($body, $offset, $objects);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfOptionalStringValueAfterName(string $body, string $name, array $objects): ?string
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        return $this->pdfStringTokenAt($body, $offset, $objects);
    }

    private function pdfArrayValueAfterName(string $body, string $name): ?string
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        return $this->readPdfArrayAt($body, $offset);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfArrayValueAfterNameResolvingObjects(string $body, string $name, array $objects): ?string
    {
        $direct = $this->pdfArrayValueAfterName($body, $name);
        if ($direct !== null) {
            return $direct;
        }

        $reference = $this->objectReferenceAfterName($body, $name);
        if ($reference === null) {
            return null;
        }

        $objectBody = $this->objectBodyForExactReference($objects, $reference['objectNumber'], $reference['generation']);
        return $objectBody === null ? null : $this->pdfArrayAtStart(trim($objectBody));
    }

    /**
     * @return list<float>|null
     * @param array<int, string> $objects
     */
    private function pdfMatrixValueAfterName(string $body, string $name, array $objects): ?array
    {
        $arrayBody = $this->pdfArrayValueAfterNameResolvingObjects($body, $name, $objects);
        if ($arrayBody === null) {
            return null;
        }

        $numbers = $this->numbersFromPdfArrayResolvingObjects($arrayBody, $objects);
        if (count($numbers) < 6) {
            return null;
        }

        return array_slice($numbers, 0, 6);
    }

    /**
     * @return list<float>|null
     * @param array<int, string> $objects
     */
    private function topLevelPdfMatrixValueAfterName(string $body, string $name, array $objects): ?array
    {
        $value = $this->topLevelPdfValueAfterName($body, $name);
        if ($value === null) {
            return null;
        }

        $arrayBody = $this->pdfArrayFromValue($value, $objects);
        if ($arrayBody === null) {
            return null;
        }

        $numbers = $this->numbersFromPdfArray($arrayBody);
        if (count($numbers) < 6) {
            return null;
        }

        return array_slice($numbers, 0, 6);
    }

    /**
     * @return list<float>|null
     * @param array<int, string> $objects
     */
    private function pdfRectangleValueAfterName(string $body, string $name, array $objects): ?array
    {
        $arrayBody = $this->pdfArrayValueAfterNameResolvingObjects($body, $name, $objects);
        if ($arrayBody === null) {
            return null;
        }

        $numbers = $this->numbersFromPdfArray($arrayBody);
        if (count($numbers) < 4) {
            return null;
        }

        return [
            min($numbers[0], $numbers[2]),
            min($numbers[1], $numbers[3]),
            max($numbers[0], $numbers[2]),
            max($numbers[1], $numbers[3]),
        ];
    }

    /**
     * @param list<float> $left
     * @param list<float> $right
     * @return list<float>
     */
    private function pdfMatrixMultiply(array $left, array $right): array
    {
        return [
            ($left[0] * $right[0]) + ($left[2] * $right[1]),
            ($left[1] * $right[0]) + ($left[3] * $right[1]),
            ($left[0] * $right[2]) + ($left[2] * $right[3]),
            ($left[1] * $right[2]) + ($left[3] * $right[3]),
            ($left[0] * $right[4]) + ($left[2] * $right[5]) + $left[4],
            ($left[1] * $right[4]) + ($left[3] * $right[5]) + $left[5],
        ];
    }

    /**
     * @param list<float> $matrix
     */
    private function pdfMatrixIsIdentity(array $matrix): bool
    {
        return count($matrix) >= 6
            && abs($matrix[0] - 1.0) < 0.000001
            && abs($matrix[1]) < 0.000001
            && abs($matrix[2]) < 0.000001
            && abs($matrix[3] - 1.0) < 0.000001
            && abs($matrix[4]) < 0.000001
            && abs($matrix[5]) < 0.000001;
    }

    /**
     * @param list<float> $rectangle
     */
    private function pdfPointInsideRectangle(float $x, float $y, array $rectangle): bool
    {
        return $x >= $rectangle[0] - 0.000001
            && $x <= $rectangle[2] + 0.000001
            && $y >= $rectangle[1] - 0.000001
            && $y <= $rectangle[3] + 0.000001;
    }

    /**
     * @param list<float> $rectangle
     */
    private function pdfRectangleHasArea(array $rectangle): bool
    {
        return count($rectangle) >= 4
            && $rectangle[2] > $rectangle[0] + 0.000001
            && $rectangle[3] > $rectangle[1] + 0.000001;
    }

    /**
     * @param list<string> $operands
     * @param list<float>|null $clipRectangle
     * @param list<float>|null $currentPathRectangle
     * @param list<float> $currentTransformationMatrix
     * @param array{0: float, 1: float}|null $currentPathPoint
     * @param array{0: float, 1: float}|null $currentSubpathStartPoint
     */
    private function applyClipPathStateOperator(
        string $operator,
        array $operands,
        ?array &$clipRectangle,
        ?array &$currentPathRectangle,
        array &$currentTransformationMatrix,
        ?array &$currentPathPoint,
        ?array &$currentSubpathStartPoint
    ): bool {
        if ($operator === 'cm') {
            $matrix = $this->contentMatrixOperand($operands);
            if ($matrix !== null) {
                $currentTransformationMatrix = $this->pdfMatrixMultiply($currentTransformationMatrix, $matrix);
            }

            return true;
        }

        if ($operator === 're') {
            $rectangle = $this->rectanglePathOperand($operands, $currentTransformationMatrix);
            if ($rectangle !== null) {
                $currentPathRectangle = $this->pdfRectangleUnion($currentPathRectangle, $rectangle);
            }

            return true;
        }

        if ($operator === 'm') {
            $point = $this->pathPointOperand($operands, $currentTransformationMatrix);
            if ($point !== null) {
                $currentPathPoint = $point;
                $currentSubpathStartPoint = $point;
                $currentPathRectangle = $this->pdfRectangleUnion($currentPathRectangle, [
                    $point[0],
                    $point[1],
                    $point[0],
                    $point[1],
                ]);
            }

            return true;
        }

        if ($operator === 'l') {
            $point = $this->pathPointOperand($operands, $currentTransformationMatrix);
            if ($point !== null) {
                $currentPathRectangle = $this->pdfRectangleUnionPathSegment(
                    $currentPathRectangle,
                    $currentPathPoint,
                    $point
                );
                $currentPathPoint = $point;
            }

            return true;
        }

        if ($operator === 'c' || $operator === 'v' || $operator === 'y') {
            $points = $this->curvePathOperandPoints($operator, $operands, $currentTransformationMatrix, $currentPathPoint);
            if ($points !== []) {
                $currentPathRectangle = $this->pdfRectangleUnionPathPoints($currentPathRectangle, $points);
                $currentPathPoint = $points[count($points) - 1];
            }

            return true;
        }

        if ($operator === 'h') {
            if ($currentSubpathStartPoint !== null) {
                $currentPathRectangle = $this->pdfRectangleUnionPathSegment(
                    $currentPathRectangle,
                    $currentPathPoint,
                    $currentSubpathStartPoint
                );
                $currentPathPoint = $currentSubpathStartPoint;
            }

            return true;
        }

        if ($operator === 'W' || $operator === 'W*') {
            if ($currentPathRectangle !== null) {
                $clipRectangle = $this->pdfRectangleIntersection($clipRectangle, $currentPathRectangle);
            }

            return true;
        }

        if ($this->pathOperatorClearsCurrentPath($operator)) {
            $currentPathRectangle = null;
            $currentPathPoint = null;
            $currentSubpathStartPoint = null;

            return true;
        }

        return false;
    }

    /**
     * @param list<string> $operands
     * @param list<float> $matrix
     * @return list<float>|null
     */
    private function rectanglePathOperand(array $operands, array $matrix): ?array
    {
        if (count($operands) < 4) {
            return null;
        }

        $numbers = [];
        foreach (array_slice($operands, -4) as $operand) {
            $number = $this->numericOperand($operand);
            if ($number === null) {
                return null;
            }
            $numbers[] = $number;
        }

        [$x, $y, $width, $height] = $numbers;
        if (abs($width) < 0.000001 || abs($height) < 0.000001) {
            return null;
        }

        $points = [
            $this->pdfMatrixTransformPoint($matrix, $x, $y),
            $this->pdfMatrixTransformPoint($matrix, $x + $width, $y),
            $this->pdfMatrixTransformPoint($matrix, $x, $y + $height),
            $this->pdfMatrixTransformPoint($matrix, $x + $width, $y + $height),
        ];
        $xs = array_column($points, 0);
        $ys = array_column($points, 1);

        return [
            min($xs),
            min($ys),
            max($xs),
            max($ys),
        ];
    }

    /**
     * @param list<string> $operands
     * @param list<float> $matrix
     * @return array{0: float, 1: float}|null
     */
    private function pathPointOperand(array $operands, array $matrix): ?array
    {
        if (count($operands) < 2) {
            return null;
        }

        $x = $this->numericOperand($operands[count($operands) - 2]);
        $y = $this->numericOperand($operands[count($operands) - 1]);
        if ($x === null || $y === null) {
            return null;
        }

        return $this->pdfMatrixTransformPoint($matrix, $x, $y);
    }

    /**
     * @param list<string> $operands
     * @param list<float> $matrix
     * @param array{0: float, 1: float}|null $currentPathPoint
     * @return list<array{0: float, 1: float}>
     */
    private function curvePathOperandPoints(
        string $operator,
        array $operands,
        array $matrix,
        ?array $currentPathPoint
    ): array {
        $requiredOperands = $operator === 'c' ? 6 : 4;
        if (count($operands) < $requiredOperands) {
            return [];
        }

        $numbers = [];
        foreach (array_slice($operands, -$requiredOperands) as $operand) {
            $number = $this->numericOperand($operand);
            if ($number === null) {
                return [];
            }
            $numbers[] = $number;
        }

        $points = [];
        if ($currentPathPoint !== null) {
            $points[] = $currentPathPoint;
        }

        if ($operator === 'c') {
            for ($index = 0; $index < 6; $index += 2) {
                $points[] = $this->pdfMatrixTransformPoint($matrix, $numbers[$index], $numbers[$index + 1]);
            }

            return $points;
        }

        if ($operator === 'v') {
            for ($index = 0; $index < 4; $index += 2) {
                $points[] = $this->pdfMatrixTransformPoint($matrix, $numbers[$index], $numbers[$index + 1]);
            }

            return $points;
        }

        $points[] = $this->pdfMatrixTransformPoint($matrix, $numbers[0], $numbers[1]);
        $points[] = $this->pdfMatrixTransformPoint($matrix, $numbers[2], $numbers[3]);

        return $points;
    }

    /**
     * @param list<float> $matrix
     * @return array{0: float, 1: float}
     */
    private function pdfMatrixTransformPoint(array $matrix, float $x, float $y): array
    {
        return [
            ($matrix[0] * $x) + ($matrix[2] * $y) + $matrix[4],
            ($matrix[1] * $x) + ($matrix[3] * $y) + $matrix[5],
        ];
    }

    /**
     * @param list<float> $matrix
     * @param list<float> $rectangle
     * @return list<float>
     */
    private function pdfRectangleTransform(array $matrix, array $rectangle): array
    {
        $points = [
            $this->pdfMatrixTransformPoint($matrix, $rectangle[0], $rectangle[1]),
            $this->pdfMatrixTransformPoint($matrix, $rectangle[2], $rectangle[1]),
            $this->pdfMatrixTransformPoint($matrix, $rectangle[0], $rectangle[3]),
            $this->pdfMatrixTransformPoint($matrix, $rectangle[2], $rectangle[3]),
        ];
        $xs = array_column($points, 0);
        $ys = array_column($points, 1);

        return [
            min($xs),
            min($ys),
            max($xs),
            max($ys),
        ];
    }

    /**
     * @param list<float>|null $left
     * @param list<float> $right
     * @return list<float>
     */
    private function pdfRectangleUnion(?array $left, array $right): array
    {
        if ($left === null) {
            return $right;
        }

        return [
            min($left[0], $right[0]),
            min($left[1], $right[1]),
            max($left[2], $right[2]),
            max($left[3], $right[3]),
        ];
    }

    /**
     * @param list<float>|null $rectangle
     * @param array{0: float, 1: float}|null $start
     * @param array{0: float, 1: float} $end
     * @return list<float>
     */
    private function pdfRectangleUnionPathSegment(?array $rectangle, ?array $start, array $end): array
    {
        if ($start === null) {
            return $this->pdfRectangleUnion($rectangle, [$end[0], $end[1], $end[0], $end[1]]);
        }

        return $this->pdfRectangleUnion($rectangle, [
            min($start[0], $end[0]),
            min($start[1], $end[1]),
            max($start[0], $end[0]),
            max($start[1], $end[1]),
        ]);
    }

    /**
     * @param list<float>|null $rectangle
     * @param list<array{0: float, 1: float}> $points
     * @return list<float>|null
     */
    private function pdfRectangleUnionPathPoints(?array $rectangle, array $points): ?array
    {
        foreach ($points as $point) {
            $rectangle = $this->pdfRectangleUnion($rectangle, [
                $point[0],
                $point[1],
                $point[0],
                $point[1],
            ]);
        }

        return $rectangle;
    }

    /**
     * @param list<list<float>> $rectangles
     * @return list<float>|null
     */
    private function pdfRectangleUnionList(array $rectangles): ?array
    {
        $union = null;
        foreach ($rectangles as $rectangle) {
            if (count($rectangle) < 4) {
                continue;
            }

            $union = $this->pdfRectangleUnion($union, array_slice($rectangle, 0, 4));
        }

        return $union === null ? null : $this->normalizedPdfReviewNumbers($union);
    }

    /**
     * @param list<float>|null $clip
     * @param list<float> $path
     * @return list<float>
     */
    private function pdfRectangleIntersection(?array $clip, array $path): array
    {
        if ($clip === null) {
            return $path;
        }

        return [
            max($clip[0], $path[0]),
            max($clip[1], $path[1]),
            min($clip[2], $path[2]),
            min($clip[3], $path[3]),
        ];
    }

    /**
     * @param list<float>|null $clipRectangle
     */
    private function textPositionInsideActiveClip(?float $x, ?float $y, ?array $clipRectangle): bool
    {
        if ($clipRectangle === null) {
            return true;
        }

        return $this->pdfPointInsideRectangle($x ?? 0.0, $y ?? 0.0, $clipRectangle);
    }

    private function pathOperatorClearsCurrentPath(string $operator): bool
    {
        return in_array($operator, ['n', 'S', 's', 'f', 'F', 'f*', 'B', 'B*', 'b', 'b*'], true);
    }

    private function pdfNumberValueAfterName(string $body, string $name): ?float
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null || preg_match('/\G([+-]?(?:\d+(?:\.\d*)?|\.\d+))/s', $body, $match, 0, $offset) !== 1) {
            return null;
        }

        return (float) $match[1];
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfNumberValueAfterNameResolvingObjects(string $body, string $name, array $objects): ?float
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        return $this->pdfNumberValueAt($body, $offset, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, true> $seen
     */
    private function pdfNumberValueAt(string $value, int $offset, array $objects, array $seen = []): ?float
    {
        $offset = $this->skipPdfWhitespace($value, $offset);
        if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $value, $match, 0, $offset) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->pdfNumberValueAt(trim($body), 0, $objects, $seen);
        }

        if (preg_match('/\G([+-]?(?:\d+(?:\.\d*)?|\.\d+))/s', $value, $match, 0, $offset) !== 1) {
            return null;
        }

        return (float) $match[1];
    }

    private function pdfIntegerValueAfterName(string $body, string $name): ?int
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null || preg_match('/\G([+-]?\d+)/s', $body, $match, 0, $offset) !== 1) {
            return null;
        }

        return (int) $match[1];
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfIntegerValueAfterNameResolvingObjects(string $body, string $name, array $objects): ?int
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        return $this->streamLengthValueAt($body, $offset, $objects);
    }

    private function objectReferenceValueAfterName(string $body, string $name): ?int
    {
        $reference = $this->objectReferenceAfterName($body, $name);
        return $reference === null ? null : $reference['objectNumber'];
    }

    private function topLevelObjectReferenceValueAfterName(string $body, string $name): ?int
    {
        $value = $this->topLevelPdfValueAfterName($body, $name);
        if ($value === null) {
            return null;
        }

        $offset = 0;
        $reference = $this->readPdfIndirectReferenceToken($value, $offset);

        return $reference === null ? null : $reference['objectNumber'];
    }

    /**
     * @return array{objectNumber: int, generation: int}|null
     */
    private function objectReferenceAfterName(string $body, string $name): ?array
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        $referenceOffset = $offset;
        return $this->readPdfIndirectReferenceToken($body, $referenceOffset);
    }

    /**
     * @param array<int, string> $objects
     */
    private function objectBodyForExactReferenceAfterName(string $body, string $name, array $objects): ?string
    {
        $reference = $this->objectReferenceAfterName($body, $name);
        if ($reference === null) {
            return null;
        }

        return $this->objectBodyForExactReference($objects, $reference['objectNumber'], $reference['generation']);
    }

    /**
     * @return array{objectNumber: int, generation: int}|null
     */
    private function readPdfIndirectReferenceToken(string $value, int &$offset): ?array
    {
        $cursor = $offset;
        $objectNumber = $this->readPdfUnsignedIntegerToken($value, $cursor);
        if ($objectNumber === null) {
            return null;
        }

        $generation = $this->readPdfUnsignedIntegerToken($value, $cursor);
        if ($generation === null) {
            return null;
        }

        $cursor = $this->skipPdfWhitespace($value, $cursor);
        if (!$this->pdfKeywordAt($value, $cursor, 'R')) {
            return null;
        }

        $offset = $cursor + 1;
        return [
            'objectNumber' => $objectNumber,
            'generation' => $generation,
        ];
    }

    private function pdfNameValueAfterName(string $body, string $name): ?string
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        return $this->pdfNameValueAt($body, $offset, []);
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfNameValueAfterNameResolvingObjects(string $body, string $name, array $objects): ?string
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null) {
            return null;
        }

        return $this->pdfNameValueAt($body, $offset, $objects);
    }

    /**
     * @param array<int, string> $objects
     * @param array<int, true> $seen
     */
    private function pdfNameValueAt(string $value, int $offset, array $objects, array $seen = []): ?string
    {
        $offset = $this->skipPdfWhitespace($value, $offset);
        if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $value, $match, 0, $offset) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $objectKey = $objectNumber . ':' . $generation;
            if ($objectNumber <= 0 || isset($seen[$objectKey])) {
                return null;
            }

            $body = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            if ($body === null) {
                return null;
            }

            $seen[$objectKey] = true;
            return $this->pdfNameValueAt(trim($body), 0, $objects, $seen);
        }

        if (($value[$offset] ?? '') !== '/') {
            return null;
        }

        $end = $offset + 1;
        while ($end < strlen($value) && !str_contains(" \t\r\n\f[]()<>{}/%", $value[$end])) {
            $end++;
        }

        return $this->decodePdfName(substr($value, $offset + 1, $end - $offset - 1));
    }

    private function pdfValueAfterName(string $body, string $name): ?string
    {
        $offset = $this->nameValueOffset($body, $name);
        if ($offset === null || $offset >= strlen($body)) {
            return null;
        }

        return $this->pdfValueAtOffset($body, $offset);
    }

    private function topLevelPdfValueAfterName(string $body, string $name): ?string
    {
        $dictionary = $this->dictionaryObjectBody($body) ?? $body;

        return $this->topLevelPdfValueAfterNameInDictionaryBody($dictionary, $name);
    }

    private function topLevelPdfValueAfterNameInDictionaryBody(string $dictionary, string $name): ?string
    {
        $offset = 0;
        $length = strlen($dictionary);

        while ($offset < $length) {
            $this->skipContentWhitespaceAndComments($dictionary, $offset);
            if ($offset >= $length) {
                break;
            }

            if ($dictionary[$offset] !== '/') {
                $nextOffset = $this->skipPdfValueAt($dictionary, $offset);
                $offset = $nextOffset > $offset ? $nextOffset : $offset + 1;
                continue;
            }

            $keyStart = $offset + 1;
            $keyEnd = $keyStart;
            while ($keyEnd < $length && !str_contains(" \t\r\n\f[]()<>{}/%", $dictionary[$keyEnd])) {
                $keyEnd++;
            }

            if ($keyEnd === $keyStart) {
                $offset++;
                continue;
            }

            $key = $this->decodePdfName(substr($dictionary, $keyStart, $keyEnd - $keyStart));
            $valueOffset = $keyEnd;
            $this->skipContentWhitespaceAndComments($dictionary, $valueOffset);
            if ($valueOffset >= $length) {
                return null;
            }

            if ($key === $name) {
                return $this->pdfValueAtOffset($dictionary, $valueOffset);
            }

            $nextOffset = $this->skipPdfValueAt($dictionary, $valueOffset);
            $offset = $nextOffset > $valueOffset ? $nextOffset : $valueOffset + 1;
        }

        return null;
    }

    private function skipPdfValueAt(string $body, int $offset): int
    {
        $length = strlen($body);
        if ($offset < 0 || $offset >= $length) {
            return $length;
        }

        if ($body[$offset] === '[') {
            $array = $this->readPdfArrayAt($body, $offset);
            return $array === null ? $offset + 1 : $offset + strlen($array) + 2;
        }

        if (substr($body, $offset, 2) === '<<') {
            $end = $this->pdfDictionaryEndOffset($body, $offset);
            return $end === null ? $offset + 2 : $end + 1;
        }

        if ($body[$offset] === '(') {
            $end = $this->skipPdfLiteralStringAt($body, $offset);
            return $end === null ? $offset + 1 : $end + 1;
        }

        if ($body[$offset] === '<') {
            $end = strpos($body, '>', $offset + 1);
            return $end === false ? $length : $end + 1;
        }

        $reference = $this->pdfIndirectReferenceTokenAt($body, $offset);
        if ($reference !== null) {
            return $reference['endOffset'];
        }

        if ($body[$offset] === '/') {
            $end = $offset + 1;
            while ($end < $length && !str_contains(" \t\r\n\f[]()<>{}/%", $body[$end])) {
                $end++;
            }

            return $end;
        }

        $end = $offset;
        while ($end < $length && !ctype_space($body[$end]) && !str_contains('[]()<>{}/%', $body[$end])) {
            $end++;
        }

        return $end === $offset ? $offset + 1 : $end;
    }

    /**
     * @return list<string>
     */
    private function pdfArrayItems(string $arrayBody): array
    {
        $items = [];
        $index = 0;
        $length = strlen($arrayBody);

        while ($index < $length) {
            $this->skipContentWhitespaceAndComments($arrayBody, $index);
            if ($index >= $length) {
                break;
            }

            $reference = $this->pdfIndirectReferenceTokenAt($arrayBody, $index);
            if ($reference !== null) {
                $items[] = $reference['token'];
                $index = $reference['endOffset'];
                continue;
            }

            $char = $arrayBody[$index];
            if (substr($arrayBody, $index, 2) === '<<') {
                $items[] = $this->readDictionaryToken($arrayBody, $index);
                continue;
            }

            if ($char === '[') {
                $items[] = $this->readArrayToken($arrayBody, $index);
                continue;
            }

            if ($char === '(') {
                $items[] = $this->readLiteralToken($arrayBody, $index);
                continue;
            }

            if ($char === '<') {
                $items[] = $this->readHexToken($arrayBody, $index);
                continue;
            }

            if ($char === '/') {
                $items[] = $this->readNameToken($arrayBody, $index);
                continue;
            }

            $start = $index;
            while ($index < $length && !$this->isDelimiter($arrayBody[$index])) {
                $index++;
            }

            if ($index === $start) {
                $index++;
                continue;
            }

            $items[] = substr($arrayBody, $start, $index - $start);
        }

        return array_values(array_filter($items, static fn (string $item): bool => trim($item) !== ''));
    }

    private function nameValueOffset(string $body, string $name): ?int
    {
        return $this->pdfNameValueOffset($body, $name, false);
    }

    /**
     * PDF comments are whitespace, including inside indirect-reference operands.
     *
     * @return array{token: string, objectNumber: int, generation: int, endOffset: int}|null
     */
    private function pdfIndirectReferenceTokenAt(string $body, int $offset): ?array
    {
        $length = strlen($body);
        $start = $this->skipPdfWhitespace($body, $offset);
        if ($start >= $length || preg_match('/\G\d+/s', $body, $objectMatch, 0, $start) !== 1) {
            return null;
        }

        $afterObject = $start + strlen($objectMatch[0]);
        $generationOffset = $this->skipPdfWhitespace($body, $afterObject);
        if (
            $generationOffset <= $afterObject
            || $generationOffset >= $length
            || preg_match('/\G\d+/s', $body, $generationMatch, 0, $generationOffset) !== 1
        ) {
            return null;
        }

        $afterGeneration = $generationOffset + strlen($generationMatch[0]);
        $referenceOffset = $this->skipPdfWhitespace($body, $afterGeneration);
        if (
            $referenceOffset <= $afterGeneration
            || ($body[$referenceOffset] ?? '') !== 'R'
        ) {
            return null;
        }

        $endOffset = $referenceOffset + 1;
        if ($endOffset < $length && !$this->isBareTokenDelimiter($body[$endOffset])) {
            return null;
        }

        return [
            'token' => (int) $objectMatch[0] . ' ' . (int) $generationMatch[0] . ' R',
            'objectNumber' => (int) $objectMatch[0],
            'generation' => (int) $generationMatch[0],
            'endOffset' => $endOffset,
        ];
    }

    private function topLevelNameValueOffset(string $body, string $name): ?int
    {
        return $this->pdfNameValueOffset($body, $name, true);
    }

    private function pdfNameValueOffset(string $body, string $name, bool $topLevelOnly): ?int
    {
        $length = strlen($body);
        $firstTokenOffset = 0;
        $this->skipContentWhitespaceAndComments($body, $firstTokenOffset);
        $targetDictionaryDepth = substr($body, $firstTokenOffset, 2) === '<<' ? 1 : 0;
        $dictionaryDepth = 0;
        $arrayDepth = 0;
        $index = 0;

        while ($index < $length) {
            $char = $body[$index];

            if ($char === '%') {
                $this->skipPdfComment($body, $index);
                continue;
            }

            if ($char === '(') {
                $this->readLiteralToken($body, $index);
                continue;
            }

            if ($char === '<') {
                if (($body[$index + 1] ?? '') === '<') {
                    $dictionaryDepth++;
                    $index += 2;
                    continue;
                }

                $this->readHexToken($body, $index);
                continue;
            }

            if ($char === '>' && ($body[$index + 1] ?? '') === '>') {
                $dictionaryDepth = max(0, $dictionaryDepth - 1);
                $index += 2;
                continue;
            }

            if ($char === '[') {
                $arrayDepth++;
                $index++;
                continue;
            }

            if ($char === ']') {
                $arrayDepth = max(0, $arrayDepth - 1);
                $index++;
                continue;
            }

            if ($char !== '/') {
                $index++;
                continue;
            }

            $nameStart = $index + 1;
            $nameEnd = $nameStart;
            while ($nameEnd < $length && !str_contains(" \t\r\n\f[]()<>{}/%", $body[$nameEnd])) {
                $nameEnd++;
            }

            if (
                (!$topLevelOnly || ($arrayDepth === 0 && $dictionaryDepth === $targetDictionaryDepth))
                && $nameEnd > $nameStart
                && $this->decodePdfName(substr($body, $nameStart, $nameEnd - $nameStart)) === $name
            ) {
                $valueOffset = $nameEnd;
                $this->skipContentWhitespaceAndComments($body, $valueOffset);
                return $valueOffset;
            }

            $index = $nameEnd > $index ? $nameEnd : $index + 1;
        }

        return null;
    }

    private function skipPdfWhitespace(string $value, int $offset): int
    {
        $length = strlen($value);
        while ($offset < $length) {
            if (ctype_space($value[$offset])) {
                $offset++;
                continue;
            }

            if ($value[$offset] === '%') {
                $this->skipPdfComment($value, $offset);
                continue;
            }

            break;
        }

        return $offset;
    }

    /**
     * @param array<int, string> $objects
     */
    private function pdfStringTokenAt(string $body, int $offset, array $objects): ?string
    {
        $offset = $this->skipPdfWhitespace($body, $offset);
        if ($offset >= strlen($body)) {
            return null;
        }

        $char = $body[$offset];
        if ($char === '(') {
            $raw = $this->readPdfLiteralStringAt($body, $offset);
            return $raw === null ? null : $this->decodePdfTextStringBytes($this->decodeLiteralString($raw));
        }

        if ($char === '<' && substr($body, $offset, 2) !== '<<') {
            $bytes = $this->readPdfHexStringAt($body, $offset);
            return $bytes === null ? null : $this->decodePdfTextStringBytes($bytes);
        }

        if (preg_match('/\G(\d+)\s+(\d+)\s+R\b/s', $body, $match, 0, $offset) === 1) {
            $objectNumber = (int) $match[1];
            $generation = (int) $match[2];
            $objectBody = $this->indirectObjectBodyForReference($objects, $objectNumber, $generation);
            return $objectBody === null
                ? null
                : $this->pdfStringTokenAt(trim($objectBody), 0, $objects);
        }

        if ($char === '/') {
            $end = strcspn($body, " \t\r\n\f[]()<>{}/%", $offset + 1);
            return $this->decodePdfName(substr($body, $offset + 1, $end));
        }

        return null;
    }

    private function readPdfLiteralStringAt(string $value, int $offset): ?string
    {
        if ($offset >= strlen($value) || $value[$offset] !== '(') {
            return null;
        }

        $depth = 0;
        $raw = '';
        for ($index = $offset + 1, $length = strlen($value); $index < $length; $index++) {
            $char = $value[$index];
            if ($char === '\\') {
                if ($index + 1 < $length) {
                    $raw .= $char . $value[$index + 1];
                    $index++;
                    continue;
                }

                $raw .= $char;
                continue;
            }

            if ($char === '(') {
                $depth++;
                $raw .= $char;
                continue;
            }

            if ($char === ')') {
                if ($depth === 0) {
                    return $raw;
                }
                $depth--;
                $raw .= $char;
                continue;
            }

            $raw .= $char;
        }

        return null;
    }

    private function readPdfHexStringAt(string $value, int $offset): ?string
    {
        $end = strpos($value, '>', $offset + 1);
        if ($end === false) {
            return null;
        }

        $hex = preg_replace('/\s+/', '', substr($value, $offset + 1, $end - $offset - 1));
        if ($hex === null || preg_match('/^[\da-fA-F]*$/', $hex) !== 1) {
            return null;
        }

        if (strlen($hex) % 2 === 1) {
            $hex .= '0';
        }

        $bytes = hex2bin($hex);
        return $bytes === false ? null : $bytes;
    }

    private function pdfArrayAtStart(string $value): ?string
    {
        return str_starts_with($value, '[') ? $this->readPdfArrayAt($value, 0) : null;
    }

    private function readPdfArrayAt(string $value, int $offset): ?string
    {
        if ($offset >= strlen($value) || $value[$offset] !== '[') {
            return null;
        }

        $depth = 0;
        $bodyStart = $offset + 1;
        for ($index = $offset, $length = strlen($value); $index < $length; $index++) {
            $char = $value[$index];
            if ($char === '%') {
                $this->skipPdfComment($value, $index);
                continue;
            }

            if ($char === '(') {
                $skipped = $this->skipPdfLiteralStringAt($value, $index);
                if ($skipped === null) {
                    return null;
                }
                $index = $skipped;
                continue;
            }

            if ($char === '<' && substr($value, $index, 2) === '<<') {
                $dictionaryEnd = $this->pdfDictionaryEndOffset($value, $index);
                if ($dictionaryEnd === null) {
                    return null;
                }
                $index = $dictionaryEnd;
                continue;
            }

            if ($char === '<') {
                $hexEnd = strpos($value, '>', $index + 1);
                if ($hexEnd === false) {
                    return null;
                }
                $index = $hexEnd;
                continue;
            }

            if ($char === '[') {
                $depth++;
                continue;
            }

            if ($char !== ']') {
                continue;
            }

            $depth--;
            if ($depth === 0) {
                return substr($value, $bodyStart, $index - $bodyStart);
            }
        }

        return null;
    }

    private function skipPdfLiteralStringAt(string $value, int $offset): ?int
    {
        if ($offset >= strlen($value) || $value[$offset] !== '(') {
            return null;
        }

        $depth = 0;
        for ($index = $offset + 1, $length = strlen($value); $index < $length; $index++) {
            $char = $value[$index];
            if ($char === '\\') {
                $index++;
                continue;
            }
            if ($char === '(') {
                $depth++;
                continue;
            }
            if ($char === ')') {
                if ($depth === 0) {
                    return $index;
                }
                $depth--;
            }
        }

        return null;
    }

    private function pdfDictionaryEndOffset(string $value, int $offset): ?int
    {
        if (substr($value, $offset, 2) !== '<<') {
            return null;
        }

        $depth = 0;
        for ($index = $offset, $length = strlen($value); $index < $length - 1; $index++) {
            if ($value[$index] === '%') {
                $this->skipPdfComment($value, $index);
                continue;
            }

            if ($value[$index] === '(') {
                $skipped = $this->skipPdfLiteralStringAt($value, $index);
                if ($skipped === null) {
                    return null;
                }
                $index = $skipped;
                continue;
            }

            $pair = substr($value, $index, 2);
            if ($pair === '<<') {
                $depth++;
                $index++;
                continue;
            }

            if ($pair !== '>>') {
                continue;
            }

            $depth--;
            if ($depth === 0) {
                return $index + 1;
            }
            $index++;
        }

        return null;
    }

    private function firstObjectReference(string $value): ?int
    {
        $references = $this->objectReferencePairs($value);
        return $references[0]['objectNumber'] ?? null;
    }

    /**
     * @return array{map: array<string, string>, codeSpaceRanges: list<array{start: int, end: int, width: int}>}
     */
    private function encodingDifferencesMap(string $differences): array
    {
        preg_match_all('/\/[^\s\[\]()<>{}\/%]+|[+-]?\d+/', $differences, $matches);
        $map = [];
        $code = null;

        foreach ($matches[0] ?? [] as $token) {
            if (preg_match('/^[+-]?\d+$/', $token) === 1) {
                $code = max(0, min(255, (int) $token));
                continue;
            }

            if ($code === null || !str_starts_with($token, '/')) {
                continue;
            }

            $glyph = $this->glyphNameToUnicode($this->decodePdfName(substr($token, 1)));
            if ($glyph !== '') {
                $map[str_pad(strtolower(dechex($code)), 2, '0', STR_PAD_LEFT)] = $glyph;
            }
            $code++;
        }

        return [
            'map' => $map,
            'codeSpaceRanges' => [
                ['start' => 0, 'end' => 255, 'width' => 2],
            ],
        ];
    }

